// Arabic written in English letters for the Arabic hymns that came without it (mostly the Kiahk praises and the
// Great Lent psalis), written for the app in the same style as the rest: g for ج, ' for ع, "Hallelouia".
// Each entry is the hymns (by id) that share one Arabic text, and that text in English letters, paragraph for paragraph.
export const arabicInEnglishLetters: [string[], string][] = [
  [["kiahk-liturgy-lord-have-mercy", "lent-weekday-lord-have-mercy"], "Esh-sha'b:\n\n(14/1) Ya Rabb irham. Ya Rabb irham. Ya Rabb irham.\n\n(14/2) Ya Rabb irham. Ya Rabb irham. Irhamna ya Allah.\n\n(14/3) Ya Rabb irham. Ya Rabb irham. Isma'na warhamna.\n\n(14/4) Ya Rabb irham. Ya Rabb irham. Ya Rabb irham.\n\n(14/5) Ya Rabb irham. Ya Rabb irham. Irhamna ya Allah.\n\n(14/6) Ya Rabb irham. Ya Rabb irham. Isma'na warhamna.\n\n(14/7) Ya Rabb irham. Ya Rabb irham. Ya Rabb irham.\n\n(14/8) Ya Rabb irham. Ya Rabb irham. Irhamna ya Allah.\n\n(14/9) Ya Rabb irham. Ya Rabb irham. Isma'na warhamna.\n\n(14/10) Ya Rabb irham. Ya Rabb irham. Ya Rabb irham.\n\n(14/11) Ya Rabb irham. Ya Rabb irham. Irhamna ya Allah.\n\n(14/12) Ya Rabb irham. Ya Rabb irham. Isma'na warhamna.\n\n(14/13) Ya Rabb irham. Ya Rabb irham. Ya Rabb irham.\n\n(14/14) Ya Rabb irham. Ya Rabb irham."],
  [["kiahk-liturgy-hymn-7", "lent-weekday-liturgy-hymn-of-the-virtues", "lent-weekend-liturgy-hymn-of-the-virtues"], "El-ithna 'ashrat fadeela allati lir-Rouh el-Qudus, el-maktouba fil-kutub el-muqaddasa, wa hadhihi asma'uha.\n\n(Tahillu 'ala) (2) ra's abeena el-qiddees ra'ees el-kahana, el-Baba Anba (..).\n\n(Wa shareekuhu fil-khidma er-rasouliyya, abeena el-qiddees el-usquf (el-mutran) Anba (...)).\n\nEl-oula el-mahabba, eth-thaniya er-raga', eth-thalitha el-iman.\n\n(Tahillu 'ala) (2) ra's abeena el-qiddees ra'ees el-kahana, el-Baba Anba (..).\n\n(Wa shareekuhu fil-khidma er-rasouliyya, abeena el-qiddees el-usquf (el-mutran) Anba (...)).\n\nEr-rabi'a et-tahara, el-khamisa el-batouliyya, es-sadisa es-salam.\n\n(Tahillu 'ala) (2) ra's abeena el-qiddees ra'ees el-kahana, el-Baba Anba (..).\n\n(Wa shareekuhu fil-khidma er-rasouliyya, abeena el-qiddees el-usquf (el-mutran) Anba (...)).\n\nEs-sabi'a el-hikma, eth-thamina el-birr, et-tasi'a el-wada'a.\n\n(Tahillu 'ala) (2) ra's abeena el-qiddees ra'ees el-kahana, el-Baba Anba (..).\n\n(Wa shareekuhu fil-khidma er-rasouliyya, abeena el-qiddees el-usquf (el-mutran) Anba (...)).\n\nEl-'ashira es-sabr, el-hadiya 'ashar toul er-rouh, eth-thaniya 'ashar en-nusk.\n\n(Tahillu 'ala) (2) ra's abeena el-qiddees ra'ees el-kahana, el-Baba Anba (..).\n\n(Wa shareekuhu fil-khidma er-rasouliyya, abeena el-qiddees el-usquf (el-mutran) Anba (...)).\n\nAmeen (3) yakoun (2).\n\nYatagammal (2)\n\nFi hadha el-mada (sayyidi el-Ab) (2),\n\n(Abouna el-qiddees) (2)\n\nEl-mukarram ra'ees el-kahana el-Baba Anba (..) (wa abeena el-usquf (el-mutran) el-Anba (...)).\n\nAmeen (3) yakoun (2) laka (lakum) fi gamee' ayyam hayatak (hayatikum)."],
  [["kiahk-liturgy-hymn-8", "lent-weekday-liturgy-the-blessed", "lent-weekend-liturgy-the-blessed"], "Et-toubawi el-aqdas el-kulli el-ikram, abouna wa mawlana wa sayyiduna\n\nBaba wa batriyark el-madeena el-'uzma el-Iskandariyya, wa Leebya wal-khams el-mudun el-gharbiyya wal-Habasha wa Afreeqya wa gamee' ard Masr.\n\nAbou el-aba', ra'i er-ru'ah, ra'ees ru'asa' kahanatina, thalith 'ashar er-rusul, wa qadi el-maskouna,\n\nFal-takun sinouhu 'adeeda, sayyiduna ra'ees kahanatina ya Rabb ihfazhu (li-sineen katheera ya sayyid) (3).\n\nWa abeena el-usquf (el-mutran) Anba (...).\n\nFal-yakun el-ikleerous wa kull esh-sha'b mu'afeen fir-Rabb. Ameen yakoun."],
  [["kiahk-vespers-verses-of-cymbals-1", "kiahk-matins-verses-of-cymbals-1"], "Ya Rabbu irham.\n\nNasgud lil-Ab wal-Ibn war-Rouh el-Qudus, eth-thalouth el-quddous el-musawi fil-gawhar.\n\nEs-salam lil-kaneesa bayt el-mala'ika, es-salam lil-'Adhra' allati waladat mukhallisana.\n\nEs-salam laki ya Maryam el-hamama el-hasana, allati waladat lana Allah el-Kalima.\n\nEs-salam laki ya Maryam, salaman muqaddasan, es-salam laki ya Maryam umm el-Quddous.\n\nEs-salam li-Ghubriyal ra'ees el-mala'ika el-'azeem: es-salam lilladhi bashshar: Maryam el-'Adhra'.\n\nEs-salam lish-Sharoubeem, es-salam lis-Sarafeem, es-salam li-gamee' et-tughmat es-sama'iyya.\n\nEs-salam li-Youhanna es-sabiq el-'azeem, es-salam lil-kahin naseeb 'Immanu'eel.\n\nEs-salam li-sadati el-aba' er-rusul. Es-salam li-talameedh rabbina Yasou' el-Maseeh.\n\nEs-salam laka ayyuha esh-shaheed, es-salam lil-Ingeeli, es-salam lir-Rasoul Marqus nazir el-Ilah.\n\nEs-salam laka ayyuha esh-shaheed, es-salam lish-shugaa' el-mugahid, es-salam lil-labis el-gihad, sayyidi el-malik Gi'orgios.\n\nEs-salam laka ayyuha esh-shaheed. Es-salam lish-shugaa' el-batal. Es-salam lil-mugahid muhibb el-Ab Marqourios.\n\nEs-salam laka ayyuha esh-shaheed. Es-salam lish-shugaa' el-batal. Es-salam lil-mugahid el-qiddees Aba Mina.\n\nToubaka bil-haqeeqa, ya abana el-qiddees el-batriyark, el-Anba Kyrillos es-sadis, habeeb el-Maseeh.\n\nToubaka bil-haqeeqa ya abana el-qiddees el-barr Anba Abra'am el-usquf, habeeb el-Maseeh.\n\nNas'aluka ya Ibn Allah, an tahfaz hayat batriyarkina, el-Baba Anba (...) ra'ees el-kahana, thabbithu 'ala kursiyyih.\n\nWa shareekahu fil-khidma er-rasouliyya, abana el-qiddees el-barr, Anba (...) el-usquf (el-mutran), thabbithu 'ala kursiyyih.\n\nBi-shafa'at walidat el-Ilah el-qiddeesa Maryam, ya Rabb an'im 'alayna bi-maghfirat khatayana.\n\nLi-kay nusabbihak, ma'a abeeka es-salih, war-Rouh el-Qudus, li-annaka ateet wa khallastana, irhamna."],
  [["kiahk-vespers-verses-of-cymbals-2", "kiahk-matins-verses-of-cymbals-2"], "Ya Rabbu irham.\n\nTa'alou fal-nasgud lith-thalouth el-quddous, alladhi huwa el-Ab wal-Ibn war-Rouh el-Qudus.\n\nNahnu esh-shu'oub el-maseehiyyeen, li-anna hadha huwa ilahuna el-haqeeqi.\n\nLana raga' fil-qiddeesa Maryam. Allah yarhamna bi-shafa'atiha.\n\nKull hudou' fil-'alam, min qibal salat el-qiddeesa Maryam el-'Adhra'.\n\nEs-salam laki ya Maryam el-hamama el-hasana, allati waladat lana Allah el-Kalima.\n\nEs-salam laki ya Maryam, salaman muqaddasan, es-salam laki ya Maryam umm el-Quddous.\n\nEs-salam li-Ghubriyal ra'ees el-mala'ika el-'azeem: es-salam lilladhi bashshar: Maryam el-'Adhra'.\n\nEs-salam lish-Sharoubeem, es-salam lis-Sarafeem, es-salam li-gamee' et-tughmat es-sama'iyya.\n\nEs-salam li-Youhanna es-sabiq el-'azeem, es-salam lil-kahin naseeb 'Immanu'eel.\n\nEs-salam li-sadati el-aba' er-rusul. Es-salam li-talameedh rabbina Yasou' el-Maseeh.\n\nEs-salam laka ayyuha esh-shaheed, es-salam lil-Ingeeli, es-salam lir-Rasoul Marqus nazir el-Ilah.\n\nEs-salam laka ayyuha esh-shaheed, es-salam lish-shugaa' el-mugahid, es-salam lil-labis el-gihad, sayyidi el-malik Gi'orgios.\n\nEs-salam laka ayyuha esh-shaheed. Es-salam lish-shugaa' el-batal. Es-salam lil-mugahid muhibb el-Ab Marqourios.\n\nEs-salam laka ayyuha esh-shaheed. Es-salam lish-shugaa' el-batal. Es-salam lil-mugahid el-qiddees Aba Mina.\n\nToubaka bil-haqeeqa, ya abana el-qiddees el-batriyark, el-Anba Kyrillos es-sadis, habeeb el-Maseeh.\n\nToubaka bil-haqeeqa ya abana el-qiddees el-barr Anba Abra'am el-usquf, habeeb el-Maseeh.\n\nNas'aluka ya Ibn Allah, an tahfaz hayat batriyarkina, el-Baba Anba (...) ra'ees el-kahana, thabbithu 'ala kursiyyih.\n\nWa shareekahu fil-khidma er-rasouliyya, abana el-qiddees el-barr, Anba (...) el-usquf (el-mutran), thabbithu 'ala kursiyyih.\n\nBi-shafa'at walidat el-Ilah el-qiddeesa Maryam, ya Rabb an'im 'alayna bi-maghfirat khatayana.\n\nLi-kay nusabbihak, ma'a abeeka es-salih, war-Rouh el-Qudus, li-annaka ateet wa khallastana, irhamna."],
  [["kiahk-vespers-psalm-trailer"], "Ya Rabbu ilayka da'out, fa-asri' li-ighathati. Asghi ila sawti 'indama asrukhu ilayk.\n\nLi-takun salati amamaka kal-bakhour, wa raf'u yadayya mithl taqdimat el-masa'."],
  [["kiahk-vespers-hymn-15", "kiahk-matins-hymn-15", "kiahk-liturgy-hymn-17"], "Nu'teeki es-salam, ma'a Ghubriyal el-malak qa'ileen, \"Es-salam laki ya mumtali'a ni'ma, er-Rabb ma'aki.\"\n\nMin agl hadha numaggiduki, ka-walidat el-Ilah kull heen, is'ali er-Rabb 'anna, li-yaghfir lana khatayana.\n\nLi-annahu mubarakun el-Ab wal-Ibn war-Rouh el-Qudus, eth-thalouth el-kamil, nasgud lahu wa numaggiduh."],
  [["kiahk-vespers-hymn-16", "kiahk-matins-hymn-16", "kiahk-liturgy-hymn-18"], "Nu'azzimuki bi-istihqaq, ma'a Aleesabat naseebatiki qa'ileen, \"Mubarakatun anti fin-nisa', wa mubarakatun hiya thamarat batniki.\"\n\nMin agl hadha numaggiduki, ka-walidat el-Ilah kull heen, is'ali er-Rabb 'anna, li-yaghfir lana khatayana.\n\nLi-annahu mubarakun el-Ab wal-Ibn war-Rouh el-Qudus, eth-thalouth el-kamil, nasgud lahu wa numaggiduh."],
  [["kiahk-vespers-hymn-17", "kiahk-matins-hymn-17"], "Ameen. Hallelouia. El-magdu lil-Ab wal-Ibn war-Rouh el-Qudus, el-ana wa kull awan wa ila dahr ed-duhour. Ameen.\n\nNasrukh qa'ileen: ya rabbana Yasou' el-Maseeh, el-mawloud min el-Ab qabl kull ed-duhour.\n\nYa Rabb irham, ya Rabb irham, ya Rabb barik ameen. Barikou 'alayya, barikou 'alayya, ha metanoia, ighfirou li, qul el-baraka."],
  [["kiahk-vespers-hymn-4", "kiahk-matins-hymn-4"], "Li-anni idha ma takallamtu min aglik, ayyatuha el-markaba esh-sharoubeemiyya, fa-inna lisani la yat'ab, abadan nughabbituki.\n\nLi-anni haqqan amdi, ila diyar bayt Dawoud, li-akhdh sawtan min qibalih, li-kay antiq bi-karamatik.\n\nLi-anna Allah waqaf, fi hudoud el-Yahoudiyya, wa a'ta sawtahu bi-tahleel, wa sibt Yahouza qabilahu ilayh.\n\nSibt Yahouza huwa el-'Adhra', allati waladat mukhallisana, wa aydan ba'da wiladatih, baqiyat 'adhra'.\n\nFa-min qibal sawt, Ghubriyal el-malak, nu'teeki es-salam, ya walidat el-Ilah Maryam.\n\nEs-salam laki min qibal Allah, es-salam laki min qibal Ghubriyal, es-salam laki min qibalina, qa'ileen \"Es-salam laki narfa'uki.\"\n\nEl-malak el-muqaddas Ghubriyal, bashshar el-'Adhra', wa ba'd es-salam, qawwaha bi-qawlih.\n\n\"La takhafi ya Maryam, li-annaki wagadti ni'ma, 'ind Allah ha satahbaleen, wa taladeen ibnan.\n\nWa yu'teehi er-Rabb el-Ilah, kursi Dawoud abeeh, wa yamlik 'ala bayt Ya'qoub, ila abad el-abad.\"\n\nMin agl hadha numaggiduki, ka-walidat el-Ilah kull heen, is'ali er-Rabb 'anna, li-yaghfir lana khatayana.\n\nEs-salam laki ayyatuha el-'Adhra', el-malika el-haqeeqiyya el-haqqaniyya, es-salam li-fakhr ginsina, waladti lana 'Immanu'eel.\n\nNas'aluki an tadhkureena, ayyatuha esh-shafee'a el-mu'tamana, amam rabbina Yasou' el-Maseeh, li-yaghfir lana khatayana."],
  [["kiahk-vespers-hymn-5", "kiahk-matins-hymn-5"], "Zeenat el-'Adhra' ya Maryam, ibnat el-malik Dawoud, 'an yameen Yasou' el-Maseeh, Ibn Allah el-habeeb.\n\nKa-qawl Dawoud el-malik, el-murattil fil-mazmour, \"Qamat el-malika, 'an yameen el-'arsh.\"\n\nAnti arfa' min esh-Sharoubeem, ya umm Allah dhi el-'izza, wa akram min es-Sarafeem, fis-sama' wa 'ala el-ard.\n\nToubaki anti ya Maryam, li-annaki waladti el-haqeeqi, wa batouliyyatuki makhtouma, wa anti baqiya 'adhra'.\n\nKama qal Isha'ya, bi-sawt et-tahleel, \"Ha fatah 'adhra', satalidu lana 'Immanu'eel.\"\n\nNarfa'uki yawman fa-yawman, qa'ileen ma'a Ghubriyal, \"Ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki.\"\n\nEs-salam laki ayyatuha el-'Adhra', nutawwibuki, ma'a Ghubriyal el-malak, er-Rabb ma'aki.\n\nNas'aluki an tadhkureena, ayyatuha esh-shafee'a el-mu'tamana, amam rabbina Yasou' el-Maseeh, li-yaghfir lana khatayana."],
  [["kiahk-vespers-hymn-6", "kiahk-matins-hymn-6"], "Gibra'eel el-malak, bashshar el-'Adhra', wabtada' bis-salam qa'ilan, \"Es-salam laki ya mumtali'a ni'ma.\"\n\nFa-lamma sami'at sawtahu, el-fatah el-'afeefa, agabat bi-hikma, wa fakkarat \"Ma huwa hadha?\"\n\nFa-qal laha el-malak, el-multahib naran, el-ghayr el-gasadani, \"Ya sayyidati el-'Adhra', ameeli sam'aki wasma'i minni.\n\nLa takhafi wa la tatazaz'a'i, ya Maryam ibnat Yowaqeem, er-Rabb ilah es-Sarafeem, ikhtaraki maskanan lahu.\"\n\nBil-haqeeqa tahbaleen, bil-Kalima alladhi iftaqar, li-aglina nahnu el-fuqara', hatta yag'alana aghniya'.\n\n\"Kayfa yakoun li hadha, law lam yadkhul ilayya ahad, as'aluka akhbirni, wa la tukhfi 'anni shay'an.\"\n\n\"Er-Rouh el-Qudus yahillu 'alayki, wa quwwat el-'Aliyy tuzalliluki, el-mala'ika tusabbihuki, min agl khawf khaliqihim.\"\n\nSataladeen Ibn Allah, wa hikmat Allah, li-annahu huwa ilah aba'ina, wa laysa akhar siwah.\n\n\"(Adh-hab bil-qawl innahu min qibaliki), Ibn Allah yaseer fil-mustawda', fa-unzuri la takhafi, li-anna el-kull yakhlus min qibaliki.\"\n\nEl-'Adhra' Maryam, min zar' Ibraheem, allati khallasat Adam, min la'nat el-khatiyya.\n\nEs-salam laki ayyatuha el-'Adhra', el-malika el-haqeeqiyya el-haqqaniyya, es-salam li-fakhr ginsina, waladti lana 'Immanu'eel.\n\nNas'aluki an tadhkureena, ayyatuha esh-shafee'a el-mu'tamana, amam rabbina Yasou' el-Maseeh, li-yaghfir lana khatayana."],
  [["kiahk-vespers-hymn-7", "kiahk-matins-hymn-7"], "Fish-shahr es-sadis, ursila Gibra'eel, kama fil-Ingeel el-muqaddas, bashshar [el-'Adhra'] Maryam.\n\nUrsila Gibra'eel, khadim el-khalas, ursila el-'abd el-ghayr el-gasadani, ila el-'Adhra' el-ghayr ed-danisa.\n\nUrsila Gibra'eel, aqamana bid-da'wa el-gadeeda, ursila el-hurr, ila el-fatah el-'afeefa.\n\nUrsila Gibra'eel, li-yuhayyi' el-khidr el-haqeeqi, ursila Ghubriyal, ila el-balat el-'ulwi.\n\nSirrun 'ageeb, wa mu'gizun murtafi', li-anna Kalimat el-Ab, sara ma'a el-bashar.\n\nNasgud lahu wa numaggiduh, ma'a abeehi el-ghayr el-mudrak, war-Rouh el-Mu'azzi, li-annahu ata wa khallasana."],
  [["kiahk-vespers-hymn-8", "kiahk-matins-hymn-8"], "Lamma waqa'at el-qur'a, 'ala Zakariyya an yarfa' bakhouran, dakhala ila el-haykal, wa akmala khidmatah.\n\nFa-zahara lahu malak, 'an yameen el-madhbah, wa huwa yarfa' el-bakhour, qa'ilan \"La takhaf ya Zakariyya.\n\nLi-annahu qad nuzira ila karamatik, wamra'atuka Aleesabat, satalidu laka ibnan, wa tad'ou ismahu Youhanna.\"\n\nWa Zakariyya el-kahin, 'an yameen el-madhbah, yada' el-bakhour, Ghubriyal kallamah.\n\n\"Inna imra'ataka Aleesabat, satalidu laka ibnan, wa yakoun laka farah, wa tahleel bi-mawlidih.\"\n\nQal \"Kayfa yakoun li hadha, li-anni qad shikht, wamra'ati Aleesabat, 'aqir la talid.\"\n\n\"Anta takoun samitan, hatta youlad es-sabi, wa mata absarat 'aynak, tumaggid Allah Isra'eel.\"\n\nUrsila Gibra'eel, min qibal malik el-magd, ila madeena min el-Galeel, ismuha Nasira.\n\nIla fatah 'adhra', min bayt Dawoud, ismuha Maryam, ibnat el-malik Dawoud.\n\nSirta tu'azzeeha, qa'ilan \"Ifrahi wabtahigi, es-salam laki ya mumtali'a ni'ma, er-Rabb ma'aki.\"\n\nEs-salam laki ayyatuha el-'Adhra', el-malika el-haqeeqiyya el-haqqaniyya, es-salam li-fakhr ginsina, waladti lana 'Immanu'eel.\n\nNas'aluki an tadhkureena, ayyatuha esh-shafee'a el-mu'tamana, amam rabbina Yasou' el-Maseeh, li-yaghfir lana khatayana."],
  [["kiahk-vespers-hymn-9", "kiahk-matins-hymn-9"], "Li-annahu bil-haqeeqa mustahiqqun wa 'adilun an nusabbih el-Ilah el-haqeeqi, er-Rabb el-ka'in fis-sama'.\n\nIsmuhu hulwun wa mubarak fi afwah el-qiddiseen, a'ni Allah el-Ab wal-Ibn war-Rouh el-Qudus.\n\nWa numaggid Maryam el-'afeefa walidat el-Ilah, el-qubba eth-thaniya, el-kanz el-haqeeqi.\n\nWa nasrukh gahran bi-baha' 'azeem qa'ileen: es-salam laki ayyatuha el-'Adhra', er-Rabb ma'aki.\n\nEs-salam laki ayyatuha el-'Adhra' khalas Adam wa Hawwa', es-salam laki ayyatuha el-'Adhra' farah el-agyal.\n\nEs-salam laki ayyatuha el-'Adhra' farah Habeel el-barr, es-salam laki ayyatuha el-'Adhra' el-murtafi'a 'ala el-haykal.\n\nEs-salam laki ayyatuha el-'Adhra' fulk Nouh, es-salam laki ayyatuha el-'Adhra' ila en-nafas el-akheer.\n\nEs-salam laki ayyatuha el-'Adhra' ni'mat abeena Ibraheem, es-salam laki ayyatuha el-'Adhra' esh-shafee'a el-ameena.\n\nEs-salam laki ayyatuha el-'Adhra' khalas el-qiddees Ishaq, es-salam laki ayyatuha el-'Adhra' umm el-Quddous.\n\nEs-salam laki ayyatuha el-'Adhra' ta'leel abeena Ya'qoub, es-salam laki ayyatuha el-'Adhra' ulouf wa rabawat muda'afa.\n\nEs-salam laki ayyatuha el-'Adhra' fakhr Yahouza wa ikhwatih, es-salam laki ayyatuha el-'Adhra' ila kamal el-azman.\n\nEs-salam laki ayyatuha el-'Adhra' ru'ya Mousa, es-salam laki ayyatuha el-'Adhra' umm es-Sayyid.\n\nEs-salam laki ayyatuha el-'Adhra' quwwat Yashou' wa Gid'oun, es-salam laki ayyatuha el-'Adhra' ghalabat Baraq wa Shamshoun.\n\nEs-salam laki ayyatuha el-'Adhra' quwwat Samou'eel, es-salam laki ayyatuha el-'Adhra' malikat Isra'eel.\n\nEs-salam laki ayyatuha el-'Adhra' sabr Ayyoub, es-salam laki ayyatuha el-'Adhra' bi-anwa' katheera wa marrat 'adeeda.\n\nEs-salam laki ayyatuha el-'Adhra' ibnat el-malik Dawoud, es-salam laki ayyatuha el-'Adhra' el-mutasarbila bit-tahara.\n\nEs-salam laki ayyatuha el-'Adhra' sadeeqat Sulayman, es-salam laki ayyatuha el-'Adhra' 'asa khashab el-lawz.\n\nEs-salam laki ayyatuha el-'Adhra' nubouwat Isha'ya, es-salam laki ayyatuha el-'Adhra' 'awdat Armiya'.\n\nEs-salam laki ayyatuha el-'Adhra' markabat Hizqiyal, es-salam laki ayyatuha el-'Adhra' ru'ya Danyal.\n\nEs-salam laki ayyatuha el-'Adhra' rif'at Eliya, es-salam laki ayyatuha el-'Adhra' allati waladat Masiya.\n\nEs-salam laki ayyatuha el-'Adhra' ni'mat Aleesha', es-salam laki ayyatuha el-'Adhra' el-'arous en-naqiyya.\n\nEs-salam laki ayyatuha el-'Adhra' farah el-mala'ika, es-salam laki ayyatuha el-'Adhra' bahgat ru'asa' el-mala'ika.\n\nEs-salam laki ayyatuha el-'Adhra' karamat ru'asa' el-aba', es-salam laki ayyatuha el-'Adhra' karazat el-anbiya'.\n\nEs-salam laki ayyatuha el-'Adhra' lisan er-rusul, es-salam laki ayyatuha el-'Adhra' tuhr el-'adhara.\n\nEs-salam laki ayyatuha el-'Adhra' ikleel esh-shuhada', es-salam laki ayyatuha el-'Adhra' tahleel es-siddeeqeen.\n\nEs-salam laki ayyatuha el-'Adhra' thabat el-kana'is, es-salam laki ayyatuha el-'Adhra' el-qiddeesa el-haqeeqa Maryam.\n\nEs-salam laki ayyatuha el-'Adhra' yanbou' el-hayah el-fa'id, es-salam laki ayyatuha el-'Adhra' maghfirat el-khataya.\n\nEs-salam laki ayyatuha el-'Adhra' nasl Isra'eel, es-salam laki ayyatuha el-'Adhra' waladti lana 'Immanu'eel.\n\nEs-salam laki ayyatuha el-'Adhra' hullat labisi es-saleeb, es-salam laki ayyatuha el-'Adhra' raga' el-maseehiyyeen.\n\nNas'aluki an tadhkureena ayyatuha esh-shafee'a el-ameena, 'ind er-Rabb alladhi ta'annas wa a'tana ni'matah.\n\nLi-yuthabbitana fil-iman nahnu kulluna ghanamuh, wa yurshidana bi-masarratihi ila kamal el-ayyam.\n\nWa yahfaz ra'eena Anba (…) wa yarfa' magdah, li-yar'a sha'bahu ma'a aba'ina el-asaqifa.\n\nWa yaqbal ilayhi salawatina wa yakoun lana malga', wa yunayyih nufous el-maseehiyyeen er-raqideen.\n\nWa yamnahna dalla bi-talabat wa shafa'at sayyidatina es-sayyida Maryam ila el-inqida'.\n\nNumaggiduki ayyatuha el-ameena ma'a malak el-baraka qa'ileen: es-salam laki ya mumtali'a ni'ma, er-Rabb ma'aki.\n\nIshfa'i feena ya sayyidatina kulluna, es-sayyida walidat el-Ilah Maryam, umm mukhallisina, li-yaghfir lana khatayana."],
  [["kiahk-vespers-hymn-10", "kiahk-matins-hymn-10"], "Anta 'azeemun haqqan, ayyuha el-mubashshir el-hasan, fit-tuqous el-mala'ikiyya, wat-tughmat es-sama'iyya.\n\nYa Ghubriyal el-mubashshir, el-'azeem fil-mala'ika, wat-tughmat el-muqaddasa el-'ulwiyya, hamil es-sayf el-multahib naran.\n\nQad nazar karamatak, Danyal en-nabi, wa a'lamtahu, sirr eth-thalouth el-muhyi.\n\nWa Zakariyya el-kahin, anta bashshartahu, bi-meelad es-sabiq, Youhanna el-Ma'madan.\n\nWa bashsharta aydan el-'Adhra', qa'ilan \"Es-salam laki ya mumtali'a ni'ma, er-Rabb ma'aki, sataladeen mukhallis el-'alam kullih.\"\n\nIshfa' feena [amam er-Rabb], ya ra'ees el-mala'ika et-tahir, Ghubriyal el-mubashshir, li-yaghfir lana khatayana."],
  [["kiahk-matins-hymn-14"], "Isma'i ya ibnati wanzuri wa ameeli udhunaki, wansay sha'baki wa bayt abeeki. Fa-yashtahi el-malik husnaki, li-annahu huwa sayyiduki."],
  [["kiahk-liturgy-hymn-2"], "Bi-shafa'at walidat el-Ilah el-qiddeesa Maryam, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-shafa'at, ra'ees el-mala'ika et-tahir, Ghubriyal el-mubashshir, ya Rabb an'im 'alayna bi-maghfirat khatayana.\n\nBi-shafa'at ru'asa' el-mala'ika es-sab'a wat-tughmat es-sama'iyya, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-shafa'at naseeb 'Immanu'eel, Youhanna ibn Zakariyya, ya Rabb an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat el-kahin Zakariyya wamra'atihi Aleesabat, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat, esh-shaykhayn el-mubarakayn, Yowaqeem wa Hanna, ya Rabb an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat sadati el-aba' er-rusul wa baqiyyat et-talameedh, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat nazir el-Ilah el-Ingeeli Marqus er-Rasoul, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat el-mugahid esh-shaheed sayyidi el-malik Gi'orgios, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat el-mugahid esh-shaheed Filobateer Marqourios, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat el-mugahid esh-shaheed Aba Mina el-Bayyadi, ya Rabbu an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat, ya abana el-qiddees el-batriyark, el-Anba Kyrillos es-sadis, ya Rabb an'im 'alayna bi-maghfirat khatayana.\n\nBi-salawat, sadati el-aba' muhibbi awladihim, Anba Bishoy wa Anba Boula, ya Rabb an'im lana bi-maghfirat khatayana.\n\nBi-salawat abeena el-qiddees el-barr Anba Abram el-usquf, ya Rabb an'im lana bi-maghfirat khatayana."],
  [["kiahk-liturgy-hymn-3"], "En-ni'ma lakum was-salam ma'an. Ameen. Yakoun."],
  [["kiahk-liturgy-hymn-4"], "Ni'mat rabbina Yasou' el-Maseeh takoun ma'a rouhak et-tahira, ya sayyidi el-ab el-mukarram ra'ees el-kahana el-Baba Anba (...).\n\nWa abeena el-mutran el-Anba (...).\n\nWa abeena el-usquf el-Anba (...).\n\nFal-yakun el-ikleerous wa kull esh-sha'b mu'afeen fir-Rabb. Ameen yakoun."],
  [["kiahk-liturgy-hymn-5"], "Ni'mat Allah el-Ab dabit el-kull.\n\nWa ni'mat ibnihi el-waheed Yasou' el-Maseeh rabbina.\n\nWa sharikat wa 'atiyyat er-Rouh el-Qudus el-Mu'azzi.\n\nTahillu 'ala ra's abeena et-toubawi el-mukarram ra'ees el-kahana el-Baba Anba (..).\n\n(Wa 'ala ra's abeena el-qiddees el-usquf (el-mutran) Anba (...).)\n\nIlah es-sama' yuthabbituhu (yuthabbituhum) 'ala kursiyyih (kursiyyayhima), sineen katheera wa azmina salamiyya.\n\nWa yukhdi' gamee' a'da'ihi (a'da'ihim) taht aqdamihi (aqdamihim) saree'an.\n\nUtlub (utluba) min el-Maseeh 'anna, li-yaghfir lana khatayana bi-salam ka-'azeem rahmatih.\n\nFal-yakun el-ikleerous wa kull esh-sha'b mu'afeen fir-Rabb. Ameen yakoun."],
  [["kiahk-liturgy-hymn-6", "lent-weekend-liturgy-pauline-alternate-response"], "Mahabbat Allah el-Ab, wa ni'mat el-Ibn el-waheed rabbina wa ilahina wa mukhallisina Yasou' el-Maseeh, wa sharikat wa 'atiyyat er-Rouh el-Qudus, takoun ma'a el-aqdas et-toubawi abeena el-Baba Anba (..), baba wa batriyark el-madeena el-'uzma el-Iskandariyya, wa kull kourat Masr, wa madeenat ilahina Urushaleem, wal-khams mudun el-gharbiyya wa Leebya wan-Nouba wal-Habasha wa Afreeqya (wa Ourouba wa Asya wa Kanada wa Amreeka wa Ostralya).\n\nWal-qiddees el-maghbout el-kulli el-ikram abeena Anba (...), usqufina el-orthodoksi alladhi li-hadhihi el-madeena wa tukhoumiha.\n\nFal-yakun el-ikleerous wa kull esh-sha'b mu'afeen fir-Rabb. Ameen yakoun."],
  [["kiahk-liturgy-praxis-response"], "Esh-sha'b:\n\nEs-salam laki ya Maryam el-hamama el-hasana allati waladat lana Allah el-Kalima.\n\nEs-salam laki ya Maryam salaman muqaddasan, es-salam laki ya Maryam umm el-Quddous.\n\nEs-salam li-Ghubriyal el-mubashshir, el-'azeem fil-mala'ika, wat-tughmat el-muqaddasa el-'ulwiyya, el-hamil es-sayf el-multahib naran.\n\nMubarakun anta bil-haqeeqa, ma'a abeeka es-salih war-Rouh el-Qudus, li-annaka ateet wa khallastana. Irhamna."],
  [["kiahk-liturgy-hymn-9"], "El-kamil barakat abeehi el-Kalima, ata wa tagassad ka-insan kamil.\n\nEl-magd lil-Ab wal-Ibn war-Rouh el-Qudus.\n\nEl-madhbouh nazarouh, el-madhbouh el-ka'in ma'akum, el-madhbouh mu'allaq 'ala es-saleeb.\n\nEl-ana wa kull awan wa ila dahr ed-duhour. Ameen.\n\nHadhihi el-'aqliyya, hadhihi el-u'gouba, es-sugoud lil-Maseeh el-wahid.\n\n(Barakat eth-thalouth el-aqdas) 2, el-Ab wal-Ibn war-Rouh el-Qudus.\n\n(Barakat walidat el-Ilah) 2, Maryam umm Yasou' el-Maseeh.\n\n(Barakat batriyarkina) 2, el-ab el-mukarram ra'ees el-kahana el-Baba Anba (...).\n\nBarakat el-ab el-mutran el-Anba (...)\n\nBarakat el-ab el-usquf el-Anba (...)\n\nTahillu 'ala hadha esh-sha'b kullih. Ameen yakoun.\n\nEl-katholikon, el-katholikon."],
  [["kiahk-liturgy-hymn-10"], "El-katholikon min abeena ___ ahibba'i."],
  [["kiahk-liturgy-hymn-11"], "Es-salam laki ya Maryam el-hamama el-hasana allati waladat lana Allah el-Kalima.\n\nEs-salam laki ya Maryam salaman muqaddasan, es-salam laki ya Maryam umm el-Quddous.\n\nEs-salam li-Ghubriyal, ra'ees el-mala'ika el-'azeem, es-salam lilladhi bashshar, Maryam el-'Adhra'.\n\nEs-salam laka ayyuha esh-shaheed, es-salam lil-Ingeeli, es-salam lir-Rasoul Marqus nazir el-Ilah.\n\nEs-salam laka ayyuha esh-shaheed, es-salam lish-shugaa' el-mugahid, es-salam lil-labis el-gihad, sayyidi el-malik Gi'orgios.\n\nEs-salam laka ayyuha esh-shaheed. Es-salam lish-shugaa' el-batal. Es-salam lil-mugahid muhibb el-Ab Marqourios.\n\nEs-salam laka ayyuha esh-shaheed. Es-salam lish-shugaa' el-batal. Es-salam lil-mugahid el-qiddees Aba Mina.\n\nToubaka bil-haqeeqa, ya abana el-qiddees el-batriyark, el-Anba Kyrillos es-sadis, habeeb el-Maseeh.\n\nEs-salam li-abeena Anba Bishoy, er-ragul el-barr el-kamil, es-salam li-abeena Anba Boula, habeeb el-Maseeh.\n\nToubaka bil-haqeeqa ya abana el-qiddees el-barr Anba Abra'am el-usquf, habeeb el-Maseeh.\n\nMubarakun anta bil-haqeeqa, ma'a abeeka es-salih war-Rouh el-Qudus, li-annaka ateet wa khallastana. Irhamna."],
  [["kiahk-liturgy-hymn-12"], "Ya rabbi Yasou' el-Maseeh, el-mawloud min el-Ab, qabl kull ed-duhour, irhamna ka-'azeem rahmatik.\n\nEsh-Sharoubeem yasgudouna lahu, es-Sarafeem yumaggidounah, sarikheen qa'ileen, \"Quddous quddous.\n\nQuddous Rabb el-ulouf, mukarram bir-rabawat, anta bakhour ya mukhallisi, li-annaka ateet wa khallastana.\""],
  [["kiahk-liturgy-psalm-chant-sunday-1"], "Anta ya Rabb targi' wa tatara'af 'ala Sahyoun, li-annahu waqt et-tahannun 'alayha, li-anna er-Rabb yabni Sahyoun, wa yazhar bi-magdih. Hallelouia."],
  [["kiahk-liturgy-psalm-chant-sunday-2"], "Isma'i ya ibnati wanzuri wa ameeli sam'aki, wansay sha'baki wa kull bayt abeeki, fa-inna el-malik qad ishtaha husnaki, li-annahu huwa rabbuki. Hallelouia."],
  [["kiahk-liturgy-psalm-chant-sunday-3"], "Er-rahmatu wal-haqqu iltaqaya, wal-'adlu was-salamu talathama, el-haqqu min el-ardi ashraq, wal-'adlu min es-sama'i tatalla'. Hallelouia."],
  [["kiahk-liturgy-psalm-chant-sunday-4"], "Ya galisan 'ala esh-Sharoubeem izhar, quddam Ifrayim wa Binyameen wa Manassa, li-khalasina ya Allah urdudna, wal-yunir waghuka 'alayna fa-nakhlus. Hallelouia."],
  [["kiahk-liturgy-hymn-19"], "Zakariyya el-kahin ibn Barakhiya, feema huwa fil-haykal yarfa' el-bakhour.\n\nLamma ra'a en-nour el-ka'in fi waghih, khaf wa saqat taht riglayh.\n\nNas'aluka ya Ibn Allah, an tahfaz hayat batriyarkina, el-Baba Anba (...) ra'ees el-kahana, thabbithu 'ala kursiyyih.\n\nWa shareekahu fil-khidma er-rasouliyya, abana el-qiddees el-barr, Anba (...) el-usquf (el-mutran), thabbithu 'ala kursiyyih.\n\nLi-kay nusabbihak, ma'a esh-Sharoubeem wa es-Sarafeem, sarikheen qa'ileen:\n\n\"Quddous quddous quddous, ayyuha er-Rabb ed-dabit el-kull, es-sama' wal-ard mamlou'atan, min magdika wa karamatik.\""],
  [["kiahk-liturgy-hymn-23"], "Ghubriyal el-malak bashshar el-'Adhra' qa'ilan: ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki,\n\nSatahbaleen wa taladeen ibnan wa yud'a ismuhu Yasou'. Fa-agabat el-hakeema: li-takun mashee'atuka ya Rabb.\n\nHallelouia hallelouia hallelouia, el-mawloud min el-Ab qabl kull ed-duhour, khallisna warhamna.\n\nQuddous quddous quddous, Rabb es-Saba'out, es-sama' wal-ard, mamlou'atan min magdika el-aqdas."],
  [["kiahk-liturgy-hymn-24"], "Ayyuha er-Rabb ilah el-quwwat, irgi' wattali' min es-sama', wanzur wa ta'ahhad hadhihi el-karma, aslihha wa thabbitha, hadhihi allati gharasatha yameenuk.\n\nHallelouia hallelouia hallelouia.\n\nBarik ez-zurou' wal-'ushb, li-takun rahmatuka wa salamuka hisnan li-sha'bik.\n\nQuddous quddous quddous, Rabb es-Saba'out, es-sama' wal-ard, mamlou'atan min magdika el-aqdas."],
  [["kiahk-midnight-hymn-1"], "(53/1) Agios o Theos / Agios Ischyros / Agios Athanatos / Ameen Hallelouia\n\n(53/2) Quddous Allah quddous / quddous el-qawi quddous / quddous el-hayy Allah / ameen hallelouia\n\n(53/3) Bi-ma'ounat Rabbin qadeer / ilahin 'azeemin khabeer / ashrah ma'na tafseer / ameen hallelouia\n\n(53/4) Ma'nahu ya ma ahlah / laysa ghayr Allah ilah / nusabbihuhu fawq a'la samah / ameen hallelouia\n\n(53/5) Mikha'eel wa Ghubriyal / Rufa'eel wa Souriyal / yatlouna tasabeeh wa aqwal / ameen hallelouia\n\n(53/6) Tasbihat esh-Sheeroubeem / wa aydan es-Sarafeem / qa'ileen bi-sawtin 'azeem / ameen hallelouia\n\n(53/7) Agnadun nouraniyya / wa tughmatun rouhaniyya / yaseehouna 'alaniya / ameen hallelouia\n\n(53/8) Rabawat rabawat wa ulouf / min hawl el-'arsh sufouf / yaqoulouna wa hum wuqouf / ameen hallelouia\n\n(53/9) Wal-arba'a hayawanat / min taht el-'arsh thabat / yatlouna kull el-awqat / ameen hallelouia\n\n(53/10) El-awwal shibh asad / manzarun min ghayr gasad / wa a'yunun bila 'adad / ameen hallelouia\n\n(53/11) Eth-thani shibh eth-thawr / wa huwa manzarun min nour / yaseeh bila futour / ameen hallelouia\n\n(53/12) Eth-thalith shibh 'uqab / yas'al 'an et-tayr bi-eegab / amam waheed el-Ab / ameen hallelouia\n\n(53/13) Er-rabi' shibh insan / yas'al 'anna el-ghufran / amam Allah ed-dayyan / ameen hallelouia\n\n(53/14) Manzarun bin-nour muksi / yusabbihouna fi et-hemsi / min fawq a'la el-kursi / ameen hallelouia\n\n(53/15) Manzarun bi-anwa' shatta / Sarafeem bi-agniha sitta / yaseehouna bila saktah / ameen hallelouia\n\n(53/16) Wal-arba'a wal-'ishroun qissees / kahana bi-maqamin nafees / yaseehouna bit-taqdees / ameen hallelouia\n\n(53/17) Wa tusabbihuhu el-aflak / alladheena salakou el-aslak / min fawq a'la es-samawat / ameen hallelouia\n\n(53/18) Satana'eel qad sar / shaytanan bil-istikbar / lamma battal hadha et-tidhkar / ameen hallelouia\n\n(53/19) Miskeen man yasma'uha / fi hadrat qa'iliha / wa la yatlou ma'aha / ameen hallelouia\n\n(53/20) El-hallelouia tasbeeh / wa tarteel wa madeeh / biha nasrukh wa naseeh / ameen hallelouia\n\n(53/21) El-hallelouia tamgeed / li-ilahin 'azeemin mageed / wa huwa tidhkarun 'azeemun fareed / ameen hallelouia\n\n(53/22) El-hallelouia tanzeeh / wa qa'iluha yakfeeh / yaqoul alfayn bi-feeh / ameen hallelouia\n\n(53/23) El-hallelouia bahga / wa hiya ahla lahga / wa qa'iluha yunga / ameen hallelouia\n\n(53/24) El-hallelouia ta'zeem / li-ilahin ra'oufin raheem / khafiyy el-altaf kareem / ameen hallelouia\n\n(53/25) El-hallelouia tidhkar / li-ilahin 'azeemin sattar / yagibu lahu et-tidhkar / ameen hallelouia\n\n(53/26) El-hallelouia tarteel / wa tasbeeh wa tahleel / wa hiya afdal ma qeel / ameen hallelouia\n\n(53/27) Subhanahu mukawwin ma kan / ka'in qabl el-akwan / ma yakhla minhu makan / ameen hallelouia\n\n(53/28) Subhanahu galla thanah / khafiyyun la 'ayn tarah / wa la ma'boud siwah / ameen hallelouia\n\n(53/29) Subhanahu khalaq min el-ma' / naran wa ardan samma' / awgadaha min el-'adama / ameen hallelouia\n\n(53/30) Subhanahu Rabbun ghayour / ra'oufun raheemun ghafour / 'ala kull fi'lin sattour / ameen hallelouia\n\n(53/31) Subhanahu munshi' el-akwan / bi-tadbeerihi qad kan / idh qal lish-shay' kun fa-kan / ameen hallelouia\n\n(53/32) Bil-hallelouia qad sar / tahqeeq birr el-abrar / qoulou ayyuha el-huddar / ameen hallelouia\n\n(53/33) Dawoud biha tanabba' / wa bi-fadliha anba' / bi-aqwalin tatala'la' / ameen hallelouia\n\n(53/34) Fi sharh sifr el-mazameer / el-mi'a wahid wal-khamseen mazmour / wa fi akhir kull mazmour / ameen hallelouia\n\n(53/35) Tuqra' sa'ir el-awqat / ila khaliq es-samawat / wa fi sharh el-hawsat / ameen hallelouia\n\n(53/36) Wa qismatun lil-qurban / hebi efki niman / wa feeha sharh el-iman / ameen hallelouia\n\n(53/37) Madah Dawoud el-barr / Maryam sayyidat el-abkar / 'ala el-'ashara el-awtar / ameen hallelouia\n\n(53/38) Bil-arghan wal-qeethar / was-sunouq wal-awtar / wad-daff ma'a el-mizmar / ameen hallelouia\n\n(53/39) Qal ya ibnati rabbuki / ikhtaraki wa ahabbaki / asghi wansay sha'baki / ameen hallelouia\n\n(53/40) Wa 'anha aydan qal / hiya gabal Allah el-'al / a'la min kull mithal / ameen hallelouia\n\n(53/41) Wa sammaha Sahyoun / wa qal sawfa yakoun / ilahun sirruhu maknoun / ameen hallelouia\n\n(53/42) Wa sammaha bil-gumla / el-malika el-mushtamila / bin-nour wal-hulla / ameen hallelouia\n\n(53/43) Wa qal gamee' el-umam / tusaffiq bi-tarateel wa himam / yatlouna tasabeeh bi-nagham / ameen hallelouia\n\n(53/44) Wa qal touba lil-insan / el-muta'attif bil-ihsan / 'ala el-ba'is wal-muhan / ameen hallelouia\n\n(53/45) Fa-inna er-Rabb yungeeh / wa min el-khayrat yu'teeh / ma yakfeehi wa yu'afeeh / ameen hallelouia\n\n(53/46) Ya Rabb ilayka nas'al / ihfaz el-Baba (...) el-amthal / batriyarkana wa a'tihi el-iqbal / ameen hallelouia\n\n(53/47) Ya Rabb tamminna / 'ala es-sahireen 'anna / matarinatina wa asaqifatina / ameen hallelouia\n\n(53/48) Wahfaz ya Rabb el-arbab / sa'ir kull el-ahbab / el-huddar wal-ghiyab / ameen hallelouia\n\n(53/49) Wahfaz qareeha / wash-sharih li-ma'aneeha / wal-'amil bi-ma feeha / ameen hallelouia\n\n(53/50) Wa nazimaha ighfir lahu / khatayahu ma'a zalaah / wa bi-rahmatika an'im lahu / ameen hallelouia\n\n(53/51) Youhanna min Samannoud / musamma wa biha mawloud / ya Rabb tahannan 'alayhi wa gud / ameen hallelouia\n\n(53/52) Yaqra' mithl fad qalbi / qawlan hasanan mugalli / yatahaqqaq bi-murad rabbi / ameen hallelouia\n\n(53/53) Lisani nataq yatakallam / bi-kalamin mahirin mafhoum / bi-murad man huwa ya'lam / ameen hallelouia"],
  [["kiahk-midnight-hymn-2"], "(26/1) Er-Rabb qad malak washtamal bil-baha' wal-magd wal-karama, wa tamantaq bil-quwwa\n\n(26/2) Ayyuha el-malik el-Ab Rabb el-quwwat, bil-qat' qad qata' ma' el-bahr\n\n(26/3) Ardan ghayr manzoura wa ghayr zahira kanou yamshouna 'alayha, wa qad gamadat el-amwag\n\n(26/4) Haqqan mithl el-hisn eth-thabit, wa Fir'awn bi-khawf ma'a quwwat markabatih\n\n(26/5) Fil-bahr el-a'zam ghariqou fil-'umq, el-khayl wa rukkab el-khayl tarahahum\n\n(26/6) El-khaliq ed-dayyan muhattim el-hurub, markabat muntakhaba wa rukkabuha\n\n(26/7) Hou dha bil-ghalaba qad ahlakahum, wa sahhal tareeq sha'bih\n\n(26/8) Yameen 'Immanu'eel sana'at quwwa, wa banou Isra'eel mashou fil-bahr\n\n(26/9) Wa kana fi wast el-'umq mithl es-sakhra, hatta adkhalahum ila barriyat Sina\n\n(26/10) Kama yaleeq bi-ihtiras ma'a Mousa el-mumaggad qa'ileen: falnusabbih er-Rabb, li-annahu bil-magd qad tamaggad\n\n(26/11) Kull esh-shu'oub ma'an yurattilouna lak, rabawat ad'af yusabbihounak\n\n(26/12) Fal-yushriq feena nour lahoutika el-'azeem kull heen, ayyuha el-Maseeh ilahuna\n\n(26/13) Irhamna wa naggina ya Yasou' el-Maseeh, el-Kalima en-nour el-haqeeqi el-ati ila el-'alam\n\n(26/14) Tabarakta ya Ibn Allah el-ka'in fin-nour, el-hayy el-ghayr el-ma'it, es-sani' el-ayat\n\n(26/15) Ihsibna ma'a el-liss el-yameen ya ilahi, wa adi' 'uqoulana wa afhamana\n\n(26/16) Wa mithlahu hakadha nakhlus min esh-shayateen, wa bi-quwwatika ishaq quwwatiha en-nagisa\n\n(26/17) Uhrusna ila en-nafas el-akheer nahnu kulluna, waqbal ilayka bakhourana wa kull qarabeenana\n\n(26/18) Unzur wastagib lana, bi-Allah er-rahoum, unzur ilayna bi-'ayn er-rahma.\n\n(26/19) Qum ayyuha er-Rabb el-Ilah wa a'inna, li-annaka anta huwa nasiruna wa mukhallisuna\n\n(26/20) Ya Ibn Allah irhamna waghfir lana, wahdina bi-rahmatika ila el-ghaya\n\n(26/21) Ya Allah el-galis fawq esh-Sharoubeem, a'ti sha'baka naseeban fi Urushaleem\n\n(26/22) Es-salam laki ya Maryam salaman muqaddasan, es-salam laki ya Maryam umm el-Quddous\n\n(26/23) Es-salam laki ya Maryam el-hamama el-hasana, es-salam laki ya Maryam umm Yasou' el-Maseeh\n\n(26/24) Kourat el-farah mamlou'a tahleel, bi-talabat khuddamik Mikha'eel wa Ghubriyal\n\n(26/25) Baqiyyat el-mala'ika wa Mousa en-nabi, wa Ayyoub es-siddeeq wa Youhanna el-Ma'madan\n\n(26/26) Fa-li-hadha 'abduka el-miskeen el-haqeer, ig'alhu ma'ahum bi-ghayr lawm ila akhir el-azman"],
  [["kiahk-midnight-hymn-5"], "(33/1) Qal er-Rabb li-Mousa / qul li-sha'bika huwa yarhal / idrib el-bahr bil-'asa / yanfatih laka feehi madkhal.\n\n(33/2) Fa-qam Mousa bil-layl / wa darab el-bahr bi-sur'a / fanfatah feehi darbun taweel / wa tareequn muttasi'a.\n\n(33/3) Fanshaqq el-bahr nusfayn / wa 'abarou gumla sawiyya / wa sarou feehi mashyeen / 'ala el-ard es-sufliyya.\n\n(33/4) Wa 'amoud en-nour daleel / lit-tareeq yadulluhum / min quddam Al Isra'eel / wa bi-nourihi shamilhum.\n\n(33/5) Dasou 'ala el-ard was-soukhour / fi wast qa' el-bahr / wal-miyah ka-mithl es-sour / el-'ali yameen wa yasar.\n\n(33/6) Dakhal Fir'awn wa tagasar / bi-khuyoulihi fi atharihim / wa ma'ahu kull gunoudih / bi-'abeedihi yutariduhum.\n\n(33/7) Fa-atahum 'amoud ghamam / wa hagaz bayn es-saffayn / fa-baqiya Fir'awn fi zalam / wa 'abeeduhu matmouseen.\n\n(33/8) Qal el-Masriyyoun / nahnu nahrub minhum / min quddam Al Isra'eel / er-Rabb yuharib 'anhum.\n\n(33/9) Qal er-Rabb li-Mousa / idrib el-bahr ruddah / fa-darab el-bahr bil-'asa / raga' el-ma' ila aslih.\n\n(33/10) Fanqalabat bakarat Fir'awn / wa ghatasou fi wast el-miyah / wa 'abeeduhu intamasou / wa 'ammat-hum ez-zulma.\n\n(33/11) Fa-thar 'asifun bi-'agagih / fi wast el-bahr ahagah / wantabaqat amwagah / wa raga' el-ma' ila aslih.\n\n(33/12) Ghatas Fir'awn wa ghas / wa 'asakiruhu el-kull ma'ah / wa sarou el-gamee' kar-rasas / wa rasakhou fi qa' el-miyah.\n\n(33/13) Ashraqat esh-shams tilka es-sa'a / heen ghariq dhalika el-gabbar / wa Isra'eel sar fi shaga'a / 'abar el-bahr wa sar.\n\n(33/14) Gazou el-bahr bi-surour / mashyeen 'ala el-bag was-soukhour / wa tarou mithl en-nusour / wa nazalou 'ala a'la et-Tour.\n\n(33/15) Hina'idhin sabbah Mousa / wa gama'at Isra'eel / wa ma'ahu kull er-ru'asa' / bit-tasabeeh wat-tahleel.\n\n(33/16) Wa kana Mousa wash-sha'b / yaqoulouna bi-fam wahid / ta'alou nusabbih lir-Rabb / li-annahu bil-magd tamaggad.\n\n(33/17) El-khayl wa rukkab el-khayl / tarahahum fil-bahr el-ahmar / wa khallas Isra'eel / min edh-dhilla wal-'ar.\n\n(33/18) Hadha huwa ilahi / umaggid ismahu da'im / hadha huwa ilah aba'i / sani' kull 'aza'im.\n\n(33/19) Hattam el-gaysh bi-gabarouti / er-Rabb ismuhu mukarram / Fir'awn wa quwwatuh / afhitou e-efiom.\n\n(33/20) Khiyar fursanihi eth-thulathiyya / fi wast el-bahr ghatasat / wa 'asakiruhu el-harbiyya / fi qa' el-miyah rasakhat.\n\n(33/21) Wa ghattat-hum el-miyah / wa ghatasou fil-a'maq / mithl hagar wa ramah / wal-bahr 'alayhim daq.\n\n(33/22) Yameenaka ya rabbi / tamaggadat bi-quwaha / yameenaka ya ilahi / ahlakat kull a'daha.\n\n(33/23) Man yushbihuka fil-aliha / ya rabbi man mithluk / mumaggadun fi qiddiseek / yata'aggabouna mink.\n\n(33/24) Basatta yadak / wal-ard ibtala'at-hum / bil-'adl hadayta sha'bak / ila mawdi' rahatihim.\n\n(33/25) Fa-akhadhat Maryam ukht Haroun / ed-daff bi-yadayha / wan-niswa ma'aha yughannoun / bi-tubulihinna hawalayha.\n\n(33/26) Fa-bada'at Maryam en-nabiyya / tughanni quddam wa taqoul / wan-niswa ma'aha sawiyya / yaduqqouna sunougan ma'a tubul.\n\n(33/27) Yughannouna bi-ghina' yutrib / wa yaqoulouna bi-fam wahid / ta'alou nusabbih lir-Rabb / li-annahu bil-magd tamaggad.\n\n(33/28) El-khayl wa rukkab el-khayl / tarahahum fil-bahr el-ahmar / ya farhat Isra'eel / bi-khalasihi min el-kuffar.\n\n(33/29) Bil-qat' inqata' ma' el-bahr / wal-a'maq sarat maslak / wa Mousa feeha 'abar / wal-'adouw saqat fi mahlak.\n\n(33/30) Ardun ghayr manzoura / ashraqat esh-shams 'alayha / wa tareequn mastoura / afmoshi hiōtf.\n\n(33/31) El-ma' es-sa'il waqaf / quddam Mousa wa Haroun / bi-'agabin la yousaf / ouoh emparadokson.\n\n(33/32) Fir'awn wa markabatuh ghatasou / asfal fil-qa' fil-yamm / wa banou Isra'eel 'abarou / nafjinior em-efiom.\n\n(33/33) Wa kana Mousa yusabbih quddam / wa tala'ou min el-meena / ila heen wasalou bi-salam / hi epshafe ensina."],
  [["kiahk-midnight-hymn-6"], "Qal er-Rabb li-Mousa: mudd yadaka 'ala el-bahr el-ahmar fa-yanshaqq nusfayn.\n\nLi-yadkhul banou Isra'eel fi wast el-bahr mithl el-yabas.\n\nWal-ya'lam gamee' ahl Masr, inni ana er-Rabb wa laysa ahadun ghayri.\n\nFa-madda Mousa yadahu 'ala el-bahr, wa darabahu kama qal er-Rabb.\n\nFaftaraq el-bahr wal-miyah inshafat, wa 'abar banou Isra'eel el-bahr.\n\nFa-tabi'ahum el-Masriyyoun wa Fir'awn el-malik, wa kull markabatihi wa khuyoulih.\n\nFa-raga' el-ma' wa ghatta el-Masriyyeen wa khuyoul Fir'awn war-rakibeen 'alayha, wa ghariq el-gamee' fi wast el-bahr, wa lam yabqa minhum wala wahid.\n\nWa kana banou Isra'eel yamshouna 'ala el-yabas fi wast el-bahr.\n\nWa kana el-ma' lahum mithl es-sour, 'an yameenihim wa yasarihim.\n\nFa-lamma ra'a Isra'eel hadhihi el-u'gouba el-'azeema, wa inna el-Masriyyeen matou fil-bahr,\n\nFa-khaf er-Rabb gamee' esh-sha'b, wa amana billah wa bi-'abdihi Mousa.\n\nHina'idhin bit-tasbeeh qad sabbah Mousa wa banou Isra'eel bi-hadhihi et-tasbiha.\n\nWa qal li-yaqoulou min fam wahid: falnusabbih er-Rabb, li-annahu bil-magd qad tamaggad.\n\nBi-talabat Mousa ra'ees el-anbiya', ya Rabb an'im lana bi-ghufran khatayana."],
  [["kiahk-midnight-hymn-7"], "(29/1) Qalbi wa lisani: yusabbihan eth-thalouth: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/2) Kull ahad yusabbihuk: wa yata'abbad lak: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/3) Li-annaka anta ilahuna: wa mukhallisuna el-'azeem: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/4) Es-Sayyid er-Rabb: ata wa khallasana: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/5) (Qarar) Qalbi wa lisani: yusabbihan eth-thalouth: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/6) Min agl ahkamika el-haqeeqiyya: 'allimni 'adlak: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/7) Katheeratun hiya rahmatuk: ta'ahhadna bi-khalasik: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/8) Hou dha ana: iltaga'tu ilayk: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/9) Laka el-quwwa wal-magd: ya malik el-magd: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/10) (Qarar) Qalbi wa lisani: yusabbihan eth-thalouth: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/11) Yasou' huwa raga'una: fi shada'idina: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/12) Tabarakta ya Ibn Allah: naggina min et-tagarib: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/13) Kull esh-shu'oub tusabbihuk: ayyuha el-malik el-Maseeh: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/14) A'tina salamak: ishfi amradana: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/15) (Qarar) Qalbi wa lisani: yusabbihan eth-thalouth: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/16) Anta el-mutahannin: war-rahoum: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/17) Tabarakta anta: nusabbihuka wa nubarikuk: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/18) 'Azeemun bil-haqeeqa: ed-dayyan el-'adil: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/19) Ismuka mubarak: ayyuha el-Kalima el-haqeeqi: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/20) (Qarar) Qalbi wa lisani: yusabbihan eth-thalouth: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/21) Uhrusna ayyuha el-Maseeh: bi-salahik: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/22) Isma' lil-khuta'ah: fi shada'idihim: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/23) Nafsi wa 'aqli: irfa'huma ila es-sama': ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/24) Ya Ibn Allah ilahuna: a'tina khalasan: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/25) (Qarar) Qalbi wa lisani: yusabbihan eth-thalouth: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/26) Allah er-rahoum: taweel el-anah: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/27) Quddous quddous quddous: ya Ibn el-Quddous: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/28) Anfus aba'ina: nayyihhum ayyuha el-mukhallis: ayyuha eth-thalouth: el-quddous irhamna.\n\n(29/29) Ya malikana udhkurna: fi malakoutika es-sama'i: ayyuha eth-thalouth: el-quddous irhamna."],
  [["kiahk-midnight-hymn-10"], "(26/1) Falnurattil ma'a Dawoud / wa nashkur fadl Allah / li-annahu rahoumun wa wadoud / je pefnai shop sha eneh\n\n(26/2) Ushkurou er-Rabb fa-innahu salih / mursil ghaythihi min a'la samah / 'ala es-salih wat-talih / je pefnai shop sha eneh\n\n(26/3) Ushkurou ilah el-aliha / fa-innahu salihun taweel el-anah / lahu el-magd wal-'azama / je pefnai shop sha eneh\n\n(26/4) Quddous quddous ekouab / wahidun la rabba siwah / ushkurou Rabb el-arbab / je pefnai shop sha eneh\n\n(26/5) Mala' el-ard bi-magdih / lahu el-magd fi 'ulou samah / sana' el-'aga'ib wahdah / je pefnai shop sha eneh\n\n(26/6) Sawwar 'ulou es-samawat / wa assasaha bi-kalimat fah / wan-nugoum feeha sa'irat / je pefnai shop sha eneh\n\n(26/7) Gabal el-ard bil-hikma / wa basataha fawq wagh el-miyah / wa mala'aha bil-khilqa / je pefnai shop sha eneh\n\n(26/8) Rattab kawkabayn 'azeemayn / yuneeran fi gaww samah / esh-shams wal-qamar sa'irayn / je pefnai shop sha eneh\n\n(26/9) Ga'al esh-shams li-sultan en-nahar / sa'ira fil-falak da'ira / wal-qamar wan-nugoum lil-layl / je pefnai shop sha eneh\n\n(26/10) Sakab ghadabahu 'ala Fir'awn / wa ahlak kamil a'dah / wakhtar Mousa wa Haroun / je pefnai shop sha eneh\n\n(26/11) Li-sha'bihi sana' el-ayat / fi Masr bi-dhira' a'lah / wa darabahum bi-ashna' ed-darabat / je pefnai shop sha eneh\n\n(26/12) El-Masriyyoun wa abkaruhum / darabahum bi-dhira' ma a'lah / wa khallas sha'bahu min wastihim / je pefnai shop sha eneh\n\n(26/13) Shaqq el-bahr wa falaqah / wa tarah Fir'awn guwwah / wa gaz Isra'eel wastah / je pefnai shop sha eneh\n\n(26/14) Anba' el-ma' min es-sakhra / wa rawa sha'bahu wa saqah / fil-barriyya el-qafra / je pefnai shop sha eneh\n\n(26/15) Awsalahum bilad Kan'an / wa qatal Seehoun wa fanah / wa 'Oug malik Bashan / je pefnai shop sha eneh\n\n(26/16) A'ta ardahum meerathan / li-Isra'eel 'abdihi wa fatah / wa dhakarana fi tawadu'ina / je pefnai shop sha eneh\n\n(26/17) Khallasana min el-a'da' el-muheeteen / li-kull hayy 'aza' / i'tarifou li-ilah es-sama' / je pefnai shop sha eneh\n\n(26/18) Yagibu lahu kull el-ikram / was-sugoud 'ind qadamah / ushkurou fadlahu 'ala ed-dawam / je pefnai shop sha eneh\n\n(26/19) I'tarifou li-ism el-Maseeh / washkurou fadlahu wa ridah / wa zeedouhu min et-tasabeeh / je pefnai shop sha eneh\n\n(26/20) Khallasana min Iblees / Fir'awn el-'aqli khazah / wa agazana bahr et-taqdees / je pefnai shop sha eneh\n\n(26/21) Adkhalana bahr el-'imad / wa 'ataqana min riqq et-tughyan / wa wa'adana bi-ard el-mee'ad / je pefnai shop sha eneh\n\n(26/22) Shaqq el-Maseeh bahr el-gaheem / wa rama esh-shaytan guwwah / wa akhragana minhu bi-sirrin 'azeem / je pefnai shop sha eneh\n\n(26/23) Wa as'adana ma'a sha'bih / ila mahallihi wa hanah / wa da'ana ahbabah / je pefnai shop sha eneh\n\n(26/24) 'Iwad el-mann was-salwa / a'tana gasadahu ghidha' / wa a'tana el-bee'a el-hulwa / je pefnai shop sha eneh\n\n(26/25) Anba' el-ma' min es-sakhra / wa a'tana damahu sharibnah / wa arwa nufousana el-qafra / je pefnai shop sha eneh\n\n(26/26) Wa awsalana ard el-mee'ad / wal-wa'd el-gadeed akhadhnah / wa huwa malakout es-samawat / je pefnai shop sha eneh"],
  [["kiahk-midnight-hymn-11"], "Falnurattil ma'a el-murattil Dawoud en-nabi, el-hasan fit-tarteel.\n\nWa nasrukh bi-sawt wahid qa'ileen: ushkurou er-Rabb fa-innahu salih.\n\nUshkurou Allah Rabb el-arbab, li-anna rahmatahu da'ima ila el-abad, wa ila kull ed-duhour.\n\nLi-annahu sana' 'aga'ib, wa khalaq es-samawat bi-fahmihi er-rafee'.\n\nEn-nayyirayn el-'azeemayn esh-shams wal-qamar, ga'alahuma yuneeran fawq es-samawat.\n\nEsh-shams li-sultan en-nahar, wal-qamar wan-nugoum li-sultan el-layl.\n\nWa darab el-Masriyyeen wa kull abkarihim, wa gharraqahum fil-bahr el-ahmar.\n\nBi-yadin 'azeeza, wa dhira'in rafee', akhrag Isra'eel min wastihim.\n\nFir'awn el-malik, wa marakibahu el-'azeema, gharraqahum fil-bahr el-ahmar.\n\nWa qatal aydan moulukan 'uzama', sarou ma'shar el-muhariben.\n\nWa hum Seehoun malik el-Amouriyyeen, wa 'Oug malik Bashan.\n\nWa ahabb sha'b Isra'eel, wa a'tahum ardahum meerathan.\n\nAlladheena nahnu ma'shar el-maseehiyyeen, wa da'ana khawassah.\n\nWa dhakarana fi tawadu'ina, wa khallasana min a'da'ina.\n\nFa-li-dhalika nasrukh wa naqoul ma'a el-murattil Dawoud en-nabi:\n\nUshkurou Rabb el-arbab, fa-innahu salih, wa ila el-abad rahmatuh.\n\nBi-salawat Dawoud el-murattil, ya Rabb an'im lana bi-ghufran khatayana."],
  [["kiahk-midnight-hymn-12"], "(20/1) Ashkuruk / ya ilah Isra'eel / li-annaka sana'ta ma'ana / ka-'azeem rahmatik\n\n(20/2) Ashkuruk / ya ilah Isra'eel / li-annaka arsalta ibnak / hatta khallasana\n\n(20/3) Ashkuruk / ya ilah Isra'eel / li-annaka tagassadta / min el-qiddeesa Maryam\n\n(20/4) Ashkuruk / ya ilah Isra'eel / li-annaka wulidta fi Bayt Lahm / kan-nubouwa\n\n(20/5) Ashkuruk / ya ilah Isra'eel / li-anna er-ru'ah / nazarou magdak\n\n(20/6) Ashkuruk / ya ilah Isra'eel / li-annaka ashraqta lana / bi-baha'ik\n\n(20/7) Ashkuruk / ya ilah Isra'eel / li-annaka sana'ta ayat / wa mu'gizat katheera\n\n(20/8) Ashkuruk / ya ilah Isra'eel / li-anna el-Yahoud / tashawarou 'alayk\n\n(20/9) Ashkuruk / ya ilah Isra'eel / li-annaka sulibta / 'ala es-saleeb bil-Gulgutha\n\n(20/10) Ashkuruk / ya ilah Isra'eel / li-annaka wudi'ta fil- / qabr mithl el-amwat\n\n(20/11) Ashkuruk / ya ilah Isra'eel / li-annaka qumta min el-mawt / ba'd thalathat ayyam\n\n(20/12) Ashkuruk / ya ilah Isra'eel / li-annaka nazalta ila el-gaheem / haythu el-hawiya\n\n(20/13) Ashkuruk / ya ilah Isra'eel / li-annaka khallasta Adam / wa kull ginsih\n\n(20/14) Ashkuruk / ya ilah Isra'eel / li-annaka awsayta / rusulak\n\n(20/15) Ashkuruk / ya ilah Isra'eel / li-annaka sa'idta / ila a'la es-samawat\n\n(20/16) Ashkuruk / ya ilah Isra'eel / li-annaka galasta / 'an yameen dabit el-kull\n\n(20/17) Ashkuruk / ya ilah Isra'eel / li-annaka sata'ti / wa tadeen el-maskouna\n\n(20/18) Ashkuruk / ya ilah Isra'eel / a'tini rahma / wa ghufranan\n\n(20/19) Ashkuruk / ya ilah Isra'eel / isfah / 'an zallatina\n\n(20/20) Ashkuruk / ya ilah Isra'eel / wa numaggid ismak / wa nasgud lak / ka-'azeem rahmatik"],
  [["kiahk-midnight-hymn-13"], "(20/1) Ashkuruk, ya ilah Isra'eel, li-annaka sana'ta ma'ana, ka-'azeem rahmatik.\n\n(20/2) Ashkuruk, ya ilah Isra'eel, li-annaka arsalta ibnak, hatta khallastana.\n\n(20/3) Ashkuruk, ya ilah Isra'eel, li-annaka tagassadta, min el-qiddeesa Maryam.\n\n(20/4) Ashkuruk, ya ilah Isra'eel, li-annaka wulidta fi Bayt Lahm, kan-nubouwa.\n\n(20/5) Ashkuruk, ya ilah Isra'eel, li-anna er-ru'ah, nazarou magdak.\n\n(20/6) Ashkuruk, ya ilah Isra'eel, li-annaka ashraqta lana, bi-baha'ik.\n\n(20/7) Ashkuruk, ya ilah Isra'eel, li-annaka sana'ta ayat, wa mu'gizat katheera.\n\n(20/8) Ashkuruk, ya ilah Isra'eel, li-anna el-Yahoud, tashawarou 'alayk.\n\n(20/9) Ashkuruk, ya ilah Isra'eel, li-annaka sulibta 'ala, es-saleeb bil-Gulgutha.\n\n(20/10) Ashkuruk, ya ilah Isra'eel, li-annaka wudi'ta fil-qabr, mithl el-amwat.\n\n(20/11) Ashkuruk, ya ilah Isra'eel, li-annaka qumta min el-amwat, ba'd thalathat ayyam.\n\n(20/12) Ashkuruk, ya ilah Isra'eel, li-annaka nazalta ila el-gaheem, haythu el-hawiya.\n\n(20/13) Ashkuruk, ya ilah Isra'eel, li-annaka khallasta Adam, wa kull ginsih.\n\n(20/14) Ashkuruk, ya ilah Isra'eel, li-annaka awsayta, rusulak.\n\n(20/15) Ashkuruk, ya ilah Isra'eel, li-annaka sa'idta, ila a'la es-samawat.\n\n(20/16) Ashkuruk, ya ilah Isra'eel, li-annaka galasta 'an yameen, dabit el-kull.\n\n(20/17) Ashkuruk, ya ilah Isra'eel, li-annaka sata'ti wa tadeen, el-maskouna.\n\n(20/18) Ashkuruk, ya ilah Isra'eel, a'tini rahma, wa ghufranan.\n\n(20/19) Ashkuruk, ya ilah Isra'eel, isfah 'an, zallatina.\n\n(20/20) Ashkuruk, ya ilah Isra'eel, umaggid ismaka wa nasgud lak, 'azeem rahmatik."],
  [["kiahk-midnight-hymn-14", "kiahk-midnight-hymn-15"], "(20/1) Es-sugoud yaleeq bith-thalouth el-quddous / el-Ab wal-Ibn war-Rouh el-Qudus / nasgud wa nusabbih wa nuqaddis / li-ilahin wahid khaliq el-anfus.\n\n(20/2) Lahu el-magd ed-da'im wal-ikram / sahib el-hayba wal-malakout / qadeemun azaliyyun qabl el-ayyam / da'imun baqin hayyun la yamout.\n\n(20/3) Quddous Allah quddous el-qawi / quddous el-hayy alladhi la yamout / Rabb el-'arsh el-malik el-'ulwi / nakriz wa nubashshir bith-thalouth.\n\n(20/4) Mubarakun el-Ab dabit el-kull / mubarakun el-Ibn Yasou' el-Maseeh / mubarakun Rouh qudsihi alladhi la yazal / yagibu lahu es-sugoud ma'a et-tasabeeh.\n\n(20/5) Sahib qudra wa sultan 'azeem / hakim 'alim gayyid wa kareem / ilahun wahid fi thalathat aqaneem / ya'giz 'an wasfihi kull faheem.\n\n(20/6) Gawhar wahid tab' wahid / wa dhat wahid fil-lahout fareed / eth-thalatha wahid fil-gawhar / min ghayr tafreed wala taqseem.\n\n(20/7) Gawhar wahid fi thalathat aqaneem / min ghayr tafreed wala taqseem / sultan wahid fi mulkihi muqeem / mali' samawat wa kull el-aqaleem.\n\n(20/8) Sirrun yafouq el-bashariyya / bi-hasab el-gawhar ilahun wahid / wa amma hasab el-uqnoumiyya / hum thalatha ilahun wahid.\n\n(20/9) El-Ibn mawloud min el-azaliyya / laysa li-taqdeem el-irada wulida min el-Ab / lakin wilada tabee'iyya / war-Rouh el-Qudus munbathiq min el-Ab.\n\n(20/10) Ka-wiladat shu'a' esh-shams wa hararatiha / wal-qurs el-ba'ith lil-ithnayn / wa hadhihi el-wilada tabee'iyya / la munqati'een wala munfasileen.\n\n(20/11) Eth-thalathat aqaneem mutasawiya / fil-gawhar wal-lahoutiyya / wa fi qidam el-azaliyya / wa dawam el-hayah el-abadiyya.\n\n(20/12) Shaf Danyal kursi a'yan / wal-galis 'alayhi 'ateeq el-ayyam / dana minhu Ibn el-insan / wa a'tahu el-karama was-sultan.\n\n(20/13) Nazar el-kursi shabeeh el-barq / wal-galis 'alayhi shabeeh en-nar / sha'r ra'sihi abyad kath-thalg / hamileenahu arba'at ka'inat min nar.\n\n(20/14) Ra'a el-arba'a min ghayr gasad / wahid fi shibh insan wa wahid fi shibh thawr / wal-ka'in eth-thalith shibh asad / wal-ka'in er-rabi' shabeeh en-nusour.\n\n(20/15) Arba'at wugouh lil-wahid minhum / wa sittat agniha wa kulluhu 'uyoun / bi-ithnayn yughattouna argulahum / wa yastourouna wuguhahum bi-ithnayn wa yateerouna bi-ithnayn.\n\n(20/16) Arba'a wa 'ishroun qisseesan bi-karaseehim / wa akaleel dhahab tash'al kan-nar / wa magamir dhahab fi aydeehim / bi-bakhourin sa'idin laylan wa nahar.\n\n(20/17) Yahout bil-kursi ulouf ulouf / wa ru'asa' mala'ika rabawat rabawat / karasi wa salateen sufouf sufouf / turattil lahu bi-a'la el-aswat.\n\n(20/18) Wa 'ind siyah el-ka'inat wal-qusous / yaseehouna gamee'an bi-a'la sawt / sarikheen qa'ileen quddous quddous / quddous el-hayy Rabb es-Saba'out.\n\n(20/19) Es-sama' wal-ard mamlou'a / min magdika el-fa'iq wa madeehik / laka el-magd laka el-quwwa / wa gamee' el-baraya li-tasabeehik.\n\n(20/20) Hallelouia hallelouia / laka el-'azama wal-gabarout / laka el-magd laka el-quwwa / wa laka el-hayba wa laka el-malakout."],
  [["kiahk-midnight-hymn-18"], "(36/1) Allah el-azali qabl el-adhar / arsal malakahu el-mukhtar / nagga el-fitya min atoun en-nar / hōs erof ari-hou-o tshasf\n\n(36/2) Barikou er-Rabb ilah Isra'eel / Hananya wa 'Azarya wa Meesa'eel / sabbihouhu bi-sawt et-tahleel / hōs erof ari-hou-o tshasf\n\n(36/3) Bukhtunassar el-malik aqam souratan min dhahab / wa qal lil-wuzara' wa kull esh-sha'b / idha ma sami'tum alat et-tarab / hōs erof ari-hou-o tshasf\n\n(36/4) Ta'alou li-waqtikum musri'een / wa li-tilka es-soura sagideen / wa idha lam tasgudou tulqouna fil-atoun / hōs erof ari-hou-o tshasf\n\n(36/5) Taqaddam el-Kaldaniyyoun / li-tilka es-soura kharrou sagideen / ma khala eth-thalathat el-fitya el-qiddiseen / hōs erof ari-hou-o tshasf\n\n(36/6) Ta'al ilayna ya Ananias / wa rattil ma'ana bi-sawt el-khalas / wa sabbih ilahaka Masias / hōs erof ari-hou-o tshasf\n\n(36/7) Ga' qawmun wa a'lamou el-malik qa'ileen / ha huna thalathat rigal sakineen / lam yasgudou lis-soura bal muhmileen / hōs erof ari-hou-o tshasf\n\n(36/8) Gama' el-malik ru'asa' esh-sha'b / wa arbab ed-dawla wa kull er-rutab / wa qal lahum awqidou el-atoun bil-hatab / hōs erof ari-hou-o tshasf\n\n(36/9) Atou bil-fitya mawthouqeen / wa tarahouhum fi wast el-atoun / fa-sar ka-nada el-yasameen / hōs erof ari-hou-o tshasf\n\n(36/10) Hina'idhin malak Allah ga'ahum / atfa el-atoun wa qawwahum / wa farihou bihi lamma atahum / hōs erof ari-hou-o tshasf\n\n(36/11) Hina'idhin salla 'Azarias / salatan qawiyya bi-ghayr adnas / ti-ōou ente etjom ente ti-trias / hōs erof ari-hou-o tshasf\n\n(36/12) Khassatan bil-akthar Meesa'eel / 'ala sawtuhu bit-tahleel / esmou e-efran en-Emmanouēl / hōs erof ari-hou-o tshasf\n\n(36/13) Dahish el-malik aydan wahtar / alaysa thalatha ulqou fin-nar / hou dha arba'a yamshouna aghar / hōs erof ari-hou-o tshasf\n\n(36/14) Ra'a el-malik haqqan aghar / arba'at rigal yamshouna fin-nar / wa yusabbihouna bi-bahga wa waqar / hōs erof ari-hou-o tshasf\n\n(36/15) Zad 'agaban wa nataq bi-fah / hou dha er-rabi' yushbih Ibn el-aliha / fi manzarihi wa fi ru'yah / hōs erof ari-hou-o tshasf\n\n(36/16) Sabbihouhu ayyuha es-sadat / el-mala'ika wal-karasi wal-quwwat / sabbihou Rabb es-samawat / hōs erof ari-hou-o tshasf\n\n(36/17) Sabbihouhu wa maggidouh / fi kana'is sha'bihi irfa'ouh / 'ala manabir esh-shuyoukh barikouh / hōs erof ari-hou-o tshasf\n\n(36/18) Sabbih ilahaka ya Sadrak / wa Abdanagho wal-mamdouh Meesak / li-annahu naggakum min el-halak / hōs erof ari-hou-o tshasf\n\n(36/19) Sabbihouhu ya gamee' el-umam / el-ahrar wal-'abeed wal-khadam / li-annahu ansha'akum min el-'adam / hōs erof ari-hou-o tshasf\n\n(36/20) Sa'eer el-laheeb ya Ananias / atfa'ahu ilahuka Masias / esmou epefran todimias / hōs erof ari-hou-o tshasf\n\n(36/21) Sah el-fitya bit-tahleel / barikou er-Rabb ilah Isra'eel / wadhkurou ismahu min geel ila geel / hōs erof ari-hou-o tshasf\n\n(36/22) Taqdimatun qurribat bi-ghayr adnas / ayyuha el-mamdouh 'Azarias / esmou e-efran todimias / hōs erof ari-hou-o tshasf\n\n(36/23) Akhmad el-laheeb 'Immanu'eel / fa-surr wa sabbih ya Meesa'eel / wa rattil li-ilahika bit-tahleel / hōs erof ari-hou-o tshasf\n\n(36/24) Zahar el-fitya bit-tamgeed / wa rattalou bi-sawtin 'alin shadeed / efouab epshēri emmenrit / hōs erof ari-hou-o tshasf\n\n(36/25) 'Ala el-laheeb fawq el-atoun / tis'a wa arba'een dhira'an kamileen / wa lam yarhabhu el-mugahidoun / hōs erof ari-hou-o tshasf\n\n(36/26) Ghalab el-fitya laheeb en-nar / wa qaharou el-a'da' el-kuffar / fastahaqqou el-madeeh wat-tidhkar / hōs erof ari-hou-o tshasf\n\n(36/27) Fa-sah el-malik bi-sawtin 'al / Hananya wa 'Azarya wa Meesa'eel / 'abeed Allah el-qawi el-muta'al / hōs erof ari-hou-o tshasf\n\n(36/28) Ta'alou ukhrugou min en-nar / li-anna ilahakum dhou iqtidar / sani' el-'aga'ib el-kibar / hōs erof ari-hou-o tshasf\n\n(36/29) Karamatan wa magdan ya Isra'eel / qaddim li-ilahika 'Immanu'eel / tasabeeh el-baraka wat-tahleel / hōs erof ari-hou-o tshasf\n\n(36/30) Lahu tasgud kull el-asbat / wa kull el-alsun wal-lughat / tusabbih Rabb el-quwwat / hōs erof ari-hou-o tshasf\n\n(36/31) Man yushbihuka ya Rabb el-arbab / ilahun qawiyyun 'azeezun muhab / sultanuka fi kull el-ahqab / hōs erof ari-hou-o tshasf\n\n(36/32) Nada baridun sar el-atoun / fa-sah el-fitya bi-sawtin hanoun / esmou e-Eptshois ton kyrion / hōs erof ari-hou-o tshasf\n\n(36/33) Hallilou li-ilah Ya'qoub / wabtahigou billah el-qawi el-marhoub / wa rattilou li-ismihi el-mahboub / hōs erof ari-hou-o tshasf\n\n(36/34) Wa sabbihouhu aydan bil-alhan / barikou er-Rabb ayyuha el-fityan / efhōs e-Efnouti en-siou niben / hōs erof ari-hou-o tshasf\n\n(36/35) Li-annahu 'azeemun wa mubarakun giddan / wa mukhawwifun 'ala kull el-aliha / bi-qudratihi nagga el-fitya / hōs erof ari-hou-o tshasf\n\n(36/36) Yaleeq el-ikram was-sugoud / bil-Ilah el-khaliq el-ma'boud / Rabb el-ihsan masdar el-goud / hōs erof ari-hou-o tshasf"],
  [["kiahk-midnight-hymn-22"], "Aqam el-malik Nabukhadnassar sanaman min dhahab, wa amar li-waqtihi hakadha qa'ilan:\n\nInni qultu lakum gamee'an ya ma'shar esh-shu'oub wal-umam wal-qaba'il wal-alsun, ansitou wa ta'ammalou li-kalami.\n\nIdha ma sumi' sawt el-bouq fa-khirrou li-waqtikum, wasgudou li-sourat edh-dhahab.\n\nWa idha lam tasna'ou hakadha wa lam tasma'ou li-qawli, lil-waqt tulqouna fi atoun en-nar el-muttaqid.\n\nFa-lamma sami' hadha el-kalam gamee' el-qaba'il allati fi mamlakatihi, kharrou wa sagadou amam es-soura edh-dhahabiyya.\n\nMa 'ada eth-thalathat fitya el-qiddiseen, Sadrak wa Meesak wa Abednagho, fa-innahum lam yutee'ou el-malik wa lam yasgudou lis-soura.\n\nBal taqawwou fi quloubihim wa fi nufousihim wa agsadihim, wa aqamou 'ala imanihim bir-Rabb ilah es-sama'.\n\nFa-lamma sami' el-malik ghadib ghadaban 'azeeman, wa amar an yarbutouhum wa yulqouhum fi atoun en-nar el-muttaqid.\n\nWa idha bi-malak er-Rabb qad nazal min es-sama', wa nafad laheeb en-nar wa sayyarahu kan-nada el-barid.\n\nWath-thalathat fitya el-qiddisoun mashou fi wast el-atoun, wa kanou yusabbihouna Allah bi-farah ma'a malak er-Rabb.\n\nThumma waqaf 'Azarya fi wast atoun en-nar, wa fatah fah, wa barak Allah huwa wa rufqatuhu ma'ah.\n\nQa'ileen: mubarakun ayyuha er-Rabb el-Ilah. Sabbihouhu wa zeedouhu 'ulouwwan. Mubarakun huwa ism magdihi el-quddous ila abad el-abad.\n\nBarik er-Rabb ya Hananya. Barik er-Rabb ya 'Azarya. Barik er-Rabb ya Meesa'eel, 'abeed Allah el-'Aliyy.\n\nBarikou er-Rabb ya gamee' kha'ifi er-Rabb ilah es-sama', sabbihouhu wa maggidouhu wa zeedouhu 'ulouwwan ila el-abad.\n\nQad amana el-malik billah wa kull el-Kaldaniyyeen alladheena fi mamlakatih, wa aqam eth-thalathat fitya el-qiddiseen 'ala kull malih.\n\nUtlubou min er-Rabb 'anna ayyuha eth-thalathat fitya el-qiddiseen, Sadrak wa Meesak wa Abednagho, li-yaghfir lana khatayana."],
  [["kiahk-midnight-hymn-24"], "(21/1) Fi kaneesat el-abkar / fi magma' el-at-har / qa'im bi-kull waqar / Peniōt Ava Antonios\n\n(21/2) Qa'im bi-magdin 'azeem / ma'a libas el-iskeem / fi taqs es-Sarafeem / Peniōt Ava Antonios\n\n(21/3) Bi-salatin rouhaniyya / bi-hayatin ilahiyya / dashshanta el-barriyya / Peniōt Ava Antonios\n\n(21/4) Bi-gihadin fis-salawat / 'asharat es-sanawat / bi-dumou' fil-metanoiat / Peniōt Ava Antonios\n\n(21/5) Bi-naskin fil-aswam / 'ala mada el-ayyam / bi-nafsin la tanam / Peniōt Ava Antonios\n\n(21/6) Bi-zuhdin fil-ladhdhat / bi-hadheedh fil-ilahiyyat / wa ta'ammul fir-rouhiyyat / Peniōt Ava Antonios\n\n(21/7) U'teeta rouh Eliya / wa Hanna en-nabiyya / wa Youhanna ibn Zakariyya / Peniōt Ava Antonios\n\n(21/8) Irta' esh-shayateen / min qalbika el-ameen / wa salatika kull heen / Peniōt Ava Antonios\n\n(21/9) Harabouka muddatan taweela / badhalou kull waseela / bi-kam heela wa heela / Peniōt Ava Antonios\n\n(21/10) Bi-ukhtika dhakarouk / li-kay ma yuqliqouk / bi-hadha wa yurgi'ouk / Peniōt Ava Antonios\n\n(21/11) Natharou edh-dhahab wal-mal / amamaka 'ala el-gibal / yudawwi bayn er-rimal / Peniōt Ava Antonios\n\n(21/12) Atouka bi-tarab wa ghina' / wa sourat en-nisa' / li-tasqut fil-ighra' / Peniōt Ava Antonios\n\n(21/13) Wa atouka bi-shakl usoud / wa noumour wa fuhoud / bi-siyah kar-ru'oud / Peniōt Ava Antonios\n\n(21/14) Ga'ouka bi-adhahum / li-takhaf min ru'yahum / tawadu'uka akhzahum / Peniōt Ava Antonios\n\n(21/15) Sarakhta ya aqwiya' / li-madha hadha el-'ana' / turabun ana wa haba' / Peniōt Ava Antonios\n\n(21/16) 'Agabi li-tagamhurikum / 'ala du'fi wa tazahurikum / ana ad'af min asgharikum / Peniōt Ava Antonios\n\n(21/17) Ya burg 'ali wa haseen / ya mithal lil-munsahiqeen / tatawada' lish-shayateen / Peniōt Ava Antonios\n\n(21/18) Ya qudwa wa mithal / 'ala mada el-agyal / ya sakin el-gibal / Peniōt Ava Antonios\n\n(21/19) Ya 'azeem fi gihadik / ya hakeem fi irshadik / ishfa' fi awladik / Peniōt Ava Antonios\n\n(21/20) Lam nahya ka-hayatik / lam naslik fi sifatik / fadhkurna fi salatik / Peniōt Ava Antonios\n\n(21/21) Ishfa' fi madhallatina / wa du'f tabee'atina / fi muddat ghurbatina / Peniōt Ava Antonios"],
  [["kiahk-midnight-hymn-25"], "(18/1) Abda bism el-Ilah / sayyidina Pikhristos / wa ashrah fi sharaf ma'na / Maximos nem Dometios\n\n(18/2) Bada'a bi-khal' et-tagat / wa tarhiha 'an er-ru'ous / mahabbatan fi malik es-samawat / Maximos nem Dometios\n\n(18/3) Saha bi-tarateel wa alhan / hubban fir-Rabb el-quddous / wa sara agnadan shug'an / Maximos nem Dometios\n\n(18/4) Qal 'anhum abouhuma / el-Anba Maqarios / thawb er-ruhbana iftakhar bihima / Maximos nem Dometios\n\n(18/5) Ghalabou kull esh-shayateen / bism er-Rabb el-quddous / wattaka'a fin-na'eem fariheen / Maximos nem Dometios\n\n(18/6) Khalasou min mulk el-'alam / wa khazou Iblees el-mangous / wa nala el-farah ed-da'im / Maximos nem Dometios\n\n(18/7) Toubakum ya abahat / ya awlad Maqarios / ya kawakib gabal Shiheet / wa masabeeh dayr el-Baramous\n\n(18/8) Ya wadi Habeeb shabbahouk / el-aba' bil-firdaws / wa awlad el-moulouk sakanouk / Maximos nem Dometios\n\n(18/9) Ya gabal 'azeem esh-sha'n / mutashabbih bil-firdaws / maskan el-aba' er-ruhban / Isqeet Maqarios\n\n(18/10) Sakanahu aba'un abrar / sarikheen qa'ileen quddous / sahara layl wa nahar / awlad Maqarios\n\n(18/11) Ya maskan lil-ashrar / wa ma'wa lil-lusous / sayyaraka Abou Maqar / mutashabbihan bil-firdaws\n\n(18/12) Toubaka ayyuha el-barr / toubaka ya Maqarios / anta li-Shiheet fakhar / ma'a el-aba' er-ru'ous\n\n(18/13) Wa salami lith-thalathat Maqarat / wa kull el-aba' er-ru'ous / es-sukkan bi-gabal Shiheet / Isqeet Maqarios\n\n(18/14) Wa salami li-Anba Yo'annis / pi-hegoumenos / wal-ab el-Anba Bishoy / pi-rōmi entelios\n\n(18/15) Wa salami li-Anba Danyal / wal-ab Anba Isidhoros / wal-mukarram bi-kull ikram / el-Anba Arsanios\n\n(18/16) Wa la tansou batrakna / 'ind er-Rabb el-quddous / Anba (...) qudwatna / nem nen-ioti en-ni-episkopos\n\n(18/17) La tansa ya sayyidana / tughmat ni-monakhos / wa kull maratib millatina / pi-ouai en-ni-khristianos\n\n(18/18) Wa salami ila Maryam / esh-shafee'a fi kull gins / sahibat el-ism el-a'zam / wa miftah bab el-firdaws"],
  [["kiahk-midnight-hymn-26"], "(42/1) Fi kaneesat el-abkar / fi magma' el-at-har / qa'im bi-kull waqar / pi-jōri Ava Mousa\n\n(42/2) Kan asluhu 'abid awthan / qati' tareeq li-zaman / wa sa'al 'an ed-dayyan / pi-jōri Ava Mousa\n\n(42/3) Kan Mousa min el-barbar / hayatuhu malee'a bish-sharr / wa talab innahu yatabarrar / pi-jōri Ava Mousa\n\n(42/4) Sariq qatil zani / habb el-'alam el-fani / ghasalahu ed-dam el-qani / pi-jōri Ava Mousa\n\n(42/5) Sami' Mousa el-'atshan / 'an el-aba' er-ruhban / bi-Shiheet kanou sukkan / pi-jōri Ava Mousa\n\n(42/6) Sa'al hal feehi ilah / lahu el-'azama wal-gah / qalbi mushtaq li-samah / pi-jōri Ava Mousa\n\n(42/7) Agabahu Ava Isidhoros / ilahuna qawiyyun quddous / tanhani lahu er-ru'ous / pi-jōri Ava Mousa\n\n(42/8) Ilahuna ra'oufun hannan / akhadh shakl insan / min mahabbatihi radiya bil-hawan / pi-jōri Ava Mousa\n\n(42/9) Ilahuna wa'duhu ameen / yaqbal kull et-ta'ibeen / wa yuhibb el-munsahiqeen / pi-jōri Ava Mousa\n\n(42/10) Sallim nafsak fi eedeeh / wa utruk madeek 'alayh / bin-ni'ma tatoub ilayh / pi-jōri Ava Mousa\n\n(42/11) Waqaf Mousa wa qal / iqbalni ka-ibn dal / tawwibni atoub fil-hal / pi-jōri Ava Mousa\n\n(42/12) Bi-dumou' wabtihalat / bi-tanahhud wa bi-zafarat / wa nadam 'ala kull ma fat / pi-jōri Ava Mousa\n\n(42/13) Taqaddam lil-Maseeh bi-fu'ad / mahzoun wa garih / wa arad an yastareeh / pi-jōri Ava Mousa\n\n(42/14) Qaddam tawba wari'a / 'alanan wa bila rag'a / tafaseeluha muttasi'a / pi-jōri Ava Mousa\n\n(42/15) Wa idha bi-malak mawgoud / yamsah khatayahu es-soud / bayyad lawh el-mash-houd / pi-jōri Ava Mousa\n\n(42/16) Anba Makarios ra'ah / rabbuhu samahahu wa naggah / wankatabat lahu el-hayah / pi-jōri Ava Mousa\n\n(42/17) Nal awwal el-asrar / bil-ma' war-rouh wan-nar / wa azal kull el-awzar / pi-jōri Ava Mousa\n\n(42/18) Di et-tawba atharha 'ageeb / tash'il fil-qalb laheeb / wash-sharid yibqa qareeb / pi-jōri Ava Mousa\n\n(42/19) El-qatil asbah barr / wal-khati' ina' mukhtar / was-sariq min el-akhyar / pi-jōri Ava Mousa\n\n(42/20) Wat-tawba laha maf'oul / tag'al ez-zani batoul / wal-mutamarrid maqboul / pi-jōri Ava Mousa\n\n(42/21) Yut'ib nafsahu bi-israr / yimshi alaf el-amtar / yimla lahum el-girar / pi-jōri Ava Mousa\n\n(42/22) Sar yaqta' et-tareeq / fi thabat ma'a tadqeeq / wa taqaddam feema yaleeq / pi-jōri Ava Mousa\n\n(42/23) Fi fada'il fi salawat / fi sawm fi naskiyyat / bi-takhashshu' wa metanoiat / pi-jōri Ava Mousa\n\n(42/24) 'Abid zahid wa ameen / wa imanuhu asasuhu mateen / yur'ib esh-shayateen / pi-jōri Ava Mousa\n\n(42/25) Habb el-ikhwa wa habbouh / lil-kahanout intakhabouh / rafa'ou er-raghba wa talabouh / pi-jōri Ava Mousa\n\n(42/26) Lakin heen imtahanouh / tharou el-kahana wa taradouh / wa khada' lima aradouh / pi-jōri Ava Mousa\n\n(42/27) Qal istihqaqi yakoun / nabadhouka ya aswad el-lawn / ya ramadi el-gild tahoun / pi-jōri Ava Mousa\n\n(42/28) Sami' el-batrak aqwalah / wa 'irif taqwa ahwalah / wattida' rouhihi wa kamalah / pi-jōri Ava Mousa\n\n(42/29) Rasamahu bi-amr el-Quddous / wa sawt qal axios / sami'ahu kull en-nufous / pi-jōri Ava Mousa\n\n(42/30) Toubaka ya Mousa toubak / qad nilta rida mawlak / Rabb el-karma qawwak / pi-jōri Ava Mousa\n\n(42/31) Wa fi marra gamm talabouh / li-rahib istadhnabouh / fil-magma' hayhakmouh / pi-jōri Ava Mousa\n\n(42/32) Galhum Mousa el-qiddees / 'ala dahrihi er-raml fi kees / wa dakhal mahmoum wa ta'ees / pi-jōri Ava Mousa\n\n(42/33) Sa'alouh eh gab wayyah / wa eh el-haml elli ma'ah / qal innuhu shayil khatayah / pi-jōri Ava Mousa\n\n(42/34) Kan dars mufeed mash-hour / qabilahu er-ruhban bi-surour / samahou el-khati' el-maksour / pi-jōri Ava Mousa\n\n(42/35) Ya rayt nahya hayatak / ya raytina fi sifatak / udhkurna fi salatak / pi-jōri Ava Mousa\n\n(42/36) Quddam el-'arsh el-'ali / wa amam er-Rabb el-wali / udhkurna ya abana el-ghali / pi-jōri Ava Mousa\n\n(42/37) Anba (...) el-galeel / yu'ti lahu 'umr taweel / li-yakriz bil-Ingeel / pi-jōri Ava Mousa\n\n(42/38) Wa Anba (...) usqufna / ihfazhu ya Rabb wahfazna / wa bi-salatihi uhrusna / pi-jōri Ava Mousa\n\n(42/39) Wal-asaqifa wal-ikleerous / ihmihim ya Quddous / hawwithum bi-'asakir ni-aggelos / pi-jōri Ava Mousa\n\n(42/40) Wash-shamamisa war-ruhban / wal-khuddam fi kull makan / ya Rabb imla'hum iman / pi-jōri Ava Mousa\n\n(42/41) Anba Mousa toubak / qad nilta rida mawlak / Rabb el-karma sanak wa hamak / pi-jōri Ava Mousa\n\n(42/42) Tafseer ismak fi afwah / kull el-mu'mineen / el-kull yaqoulouna ya Ilah / el-Anba Mousa a'inna agma'een"],
  [["kiahk-midnight-hymn-27"], "(30/1) Fi sufouf el-mu'tarifeen / fakhr el-mugahideen / nagm bayn el-qiddiseen / Peniōt Ava Samou'eel\n\n(30/2) Bi-da'wa ilahiyya / qasadta el-barriyya / fi mahabba nariyya / Peniōt Ava Samou'eel\n\n(30/3) Malak kulluhu tahara / iqtadaka bi-mahara / li-Isqeet Anba Maqar / Peniōt Ava Samou'eel\n\n(30/4) Li-shaykh bayn er-ruhban / nasikan kull ez-zaman / qahar el-'adouw esh-shaytan / Peniōt Ava Samou'eel\n\n(30/5) Nasahaka bil-batouliyya / wal-mahabba en-naqiyya / wat-tawadu' bi-wasiyya / Peniōt Ava Samou'eel\n\n(30/6) U'teeta bi-ni'matih / di'fayn min rouhih / 'ind niyahatih / Peniōt Ava Samou'eel\n\n(30/7) Zidta min at'abik / wa qaharta ladhdhatik / wa hubbak li-ilahik / Peniōt Ava Samou'eel\n\n(30/8) Nilta abouwat Antonios / mahabbat Maqarios / wa iman Dioscoros / Peniōt Ava Samou'eel\n\n(30/9) Bi-ra'ihatika edh-dhakiyya / wa 'ishratika el-ilahiyya / mala'ta el-barriyya / Peniōt Ava Samou'eel\n\n(30/10) 'Allamtahum er-ruhbaniyya / wal-hayah en-naskiyya / wa ta'aleem el-orthodoksiyya / Peniōt Ava Samou'eel\n\n(30/11) Arsal el-Muqawqis bayan / maktoub min esh-shaytan / ila el-aba' er-ruhban / Peniōt Ava Samou'eel\n\n(30/12) Yaqoul bi-tabee'atayn / wa ghayr muttahidatayn / lir-Rabb el-fadi el-ameen / li-ilahina 'Immanu'eel\n\n(30/13) Haddad bi-qatl wa wa'eed / man ya'tarif bil-Ibn el-waheed / wa yatba' babahu el-habeeb / el-Anba Binyameen\n\n(30/14) Hagam 'ala es-sahra' / el-ashrar el-aqwiya' / wa rafadta bi-shamam wa iba' / Peniōt Ava Samou'eel\n\n(30/15) I'tarafta bil-Maseeh / i'tirafan sadiqan sareeh / wa mazzaqta et-tasreeh / Peniōt Ava Samou'eel\n\n(30/16) Tabee'a wahida naqiyya / lahoutiyya wa nasoutiyya / muttahida bil-kulliyya / Peniōt Ava Samou'eel\n\n(30/17) El-Kalima sar gasadan / el-Ilah sar ma'ana / wa ra'ayna magdahu magdan / Peniōt Ava Samou'eel\n\n(30/18) Darabouka bi-aydin qawiyya / galadouka fi wahshiyya / el-iman wadee'a ghaliya / Peniōt Ava Samou'eel\n\n(30/19) I'tarafta bi-iman wa yaqeen / bi-Yasou' burgika el-haseen / qala'ou 'aynaka el-yameen / Peniōt Ava Samou'eel\n\n(30/20) Awsayta arba'at ruhban / li-yahfazou el-iman / ittakhadhou el-Qalamoun makan / Peniōt Ava Samou'eel\n\n(30/21) Qaddastahu bi-salatik / wa dumou'ik wa metanoiatik / wa salbak li-dhatik / Peniōt Ava Samou'eel\n\n(30/22) Hawal el-barbar el-mutagabbireen / kasr nadhr el-batouliyyeen / sarakhta li-Yasou' el-mu'een / Peniōt Ava Samou'eel\n\n(30/23) Marra bika kaseeh / bi-qalbin gareeh ka'eeb / shafaytahu bi-quwwat el-Maseeh / Peniōt Ava Samou'eel\n\n(30/24) Sirta yanbou' shifa' / li-kull marad wa da' / hatta el-barbar wal-a'da' / Peniōt Ava Samou'eel\n\n(30/25) Qa'id el-barbar el-gabbar / sa'alaka ayyuha el-barr / zawgati 'aqir muhtar / Peniōt Ava Samou'eel\n\n(30/26) Talabta min Allah el-Ab / bi-iman ghayr murtab / fa-wahabahuma el-ingab / Peniōt Ava Samou'eel\n\n(30/27) 'Udta li-awladik / li-yata'allamou gihadak / wa fuzta bi-amgadik / Peniōt Ava Samou'eel\n\n(30/28) Udhkurna fis-salah / amam 'arsh el-Ilah / li-yarhamna nahnu el-khuta'ah / Peniōt Ava Samou'eel\n\n(30/29) Salli 'anna lid-dayyan / yuthabbitna fil-iman / ila akhir el-azman / Peniōt Ava Samou'eel\n\n(30/30) Ihfaz ya Rabb batrakna / wa shuraka'ahu asaqifatna / wa ruhbanana wa kahanatana / bi-salat Anba Samou'eel"],
  [["kiahk-midnight-hymn-29"], "Es-salam laki ayyatuha el-'Adhra' allati waladat el-Ilah, wa sarat kursiyyan lil-Maseeh el-azali wa ghayr el-mahwi ma'an.\n\nEs-salam lil-hamama el-hasana allati waladat Ibn Allah haqqan, Yasou' el-Maseeh el-Kalima el-khaliq. Es-salam li-firdaws el-Maseeh.\n\nTa'alou ayyuha esh-sha'b el-muhibb lil-Maseeh sayyidina, li-kay namdah es-sayyida el-'Adhra' qa'ileen: es-salam laki ayyatuha el-'Adhra' allati sarat kursiyyan lis-Sayyid el-Maseeh el-azali wa ghayr el-mahwi ma'an. Es-salam lil-hamama el-hasana.\n\nEs-salam laki ayyatuha el-'Adhra' allati istahaqqat an turdi' Ibn Allah min thadyiha et-tahir. Es-salam laki ayyatuha el-'Adhra' allati tagassad minha khaliq el-kull.\n\nEs-salam laki ayyatuha el-'Adhra' es-sitr er-rafee' wal-higab el-manee'. Es-salam laki ayyatuha el-'Adhra' sayyidat nisa' el-'alam. Es-salam laki ayyatuha el-'Adhra' ed-durra eth-thameena.\n\nEs-salam laki ayyatuha el-'Adhra' allati anarat el-afaq ba'd ez-zalam. Es-salam laki ayyatuha el-'Adhra' ibnat Yowaqeem, allati 'ataqat ginsana min nar el-gaheem.\n\nEs-salam laki ayyatuha el-'Adhra' allati fatahat lana bab el-firdaws marratan ukhra, ba'd ighlaqihi fi wagh Adam wa ummina Hawwa'. Es-salam laki ayyatuha el-'Adhra' el-hanouna 'ala gins el-bashar.\n\nEs-salam laki ayyatuha el-'Adhra' fakhr el-'iffa wal-batouliyya. Es-salam laki ayyatuha el-'Adhra' et-tahira awwalan wa akhiran. Es-salam laki ayyatuha el-'Adhra' allati akmalat kull el-fada'il.\n\nEs-salam laki ayyatuha el-'Adhra' el-mukammala bi-kull mahasin esh-sharee'a. Es-salam laki ayyatuha el-'Adhra' allati la yaqdir lisanun bashari an yablugh wasf fada'iliki, li-anna gamee' el-fada'il el-mutafarriqa allati fil-qiddiseen kamulat feeki, wa sar el-khalas mawgoudan.\n\nEs-salam laki ayyatuha el-'Adhra' walidat el-Ilah, allati qabilat ilayha el-Kalima el-azali min qibal el-bishara el-muhyiya.\n\nEs-salam laki ayyatuha el-'Adhra' allati sarat higaban qad ihtagab feeha es-sakin fis-samawat.\n\nToubaki anti ya Maryam et-tahira el-qiddeesa allati bila 'ayb. Toubaki anti ya Maryam ya farah Isra'eel.\n\nToubaki anti ya Maryam el-'Adhra', li-annahu qad zahar minki mawloud, wa huwa malik el-moulouk wa Rabb el-arbab.\n\nToubaki ya Maryam thumma es-salam laki rabawat salam. Ya man ga'alat lana dalla 'ind el-khaliq, wa sarat lana waseela wa shafee'a 'ind ibniha el-habeeb.\n\nEs-salam laki ya Maryam dhat el-quds wat-tahara wal-'iffa. Es-salam laki ya man khussisat bir-rahma doun sa'ir el-umma. Es-salam laki ya malikat el-moulouk, el-mukhtara min gins el-bashar.\n\nEs-salam laki ya man zahar nouruha washtahar. Es-salam laki ya man ushtumma bakhouruha wa fah. Es-salam laki ya man ashraq kawkabuha wa lah.\n\nEs-salam laki ayyatuha el-qiddeesa Maryam, allati khada'at laha kull er-rutab el-'ulwiyya, wal-'asakir el-mala'ikiyya. Es-salam laki ayyatuha el-'Adhra' tahleel el-mala'ika. Es-salam laki ayyatuha el-'Adhra' farah wa bahgat es-sama'iyyeen wal-ardiyyeen.\n\nEs-salam laki ayyatuha el-'Adhra' allati lam yougad ka-mithl taharatiha el-kamila mundhu awwal el-'alam. Es-salam laki ayyatuha el-'Adhra' allati sarat rahmatan lana nahnu el-masakeen.\n\nEs-salam laki ayyatuha el-'Adhra' allati sarat lana shafee'a yawm ed-deen amam ibniha el-habeeb alladhi waladat-hu. Fal-nasgud lahu wa nusabbihahu wa nazeed fi rif'atih.\n\nWa natlub min tahannuniki an tadhkureena 'indahu, li-kay yarhamna wa yaghfir lana khatayana, wa yatagawaz 'an athamina,\n\nWa yukhallisana min at'ab hadha el-'alam ez-za'il, wa min yad el-'adouw el-mudadd lana, li-kay nubarikahu muddat ayyam hayatina wa ila el-abad. Ameen."],
  [["kiahk-midnight-hymn-30"], "(24/1) Qabilta 'anni el-at'ab: ka-abin haqeeqi: wa mudabbir: a'tini ma'rifa.\n\n(24/2) 'Oud el-khalas: bi-marahimik: du'iya ismuka 'alayya: li-agid rahma.\n\n(24/3) Kitab yad khatayaya: ya mukhallis mazzaqtah: lamma 'ulliqta: 'ala es-saleeb.\n\n(24/4) Et-tinneen er-radi': el-marid: el-hayya es-samma': kasarta shawkatah.\n\n(24/5) Ya ilahi: ighfir li baghtatan: bi-saffin hasan: ka-in'amik.\n\n(24/6) Huwa mamdouh: fi fam alladheena: yu'minouna bihi: wa ra'in tabeeb li-ra'iyyatih.\n\n(24/7) Kull yawm yanbaghi: laka el-baraka wal-magd: kama yurdeek: wat-tarateel el-hasana.\n\n(24/8) Dhabeeha naqiyya: taseer zamaniyya li-sultanik: ma'a bakhourin maqboul: amam rububiyyatik.\n\n(24/9) Ayyuha er-Rabb el-mutahannin: ma'a rabawat agnad: el-mala'ika li-nusabbihak: kama yaleequ bik.\n\n(24/10) Bi-alsun wa quloub naqiyya: naqoul quddous: quddous quddous anta: ayyuha el-Quddous.\n\n(24/11) El-ghayr el-ma'it: el-Kalima Rabb es-Saba'out: es-sama' wal-ard: min qidam el-azman.\n\n(24/12) Mamlou'atan min: magdika el-muqaddas: wa 'izam galalik: ila akhir el-'alameen.\n\n(24/13) Na'am ayyuha el-Ilah: ig'alna ahlan li-barakat: uqnoumika et-tahir.\n\n(24/14) Li-anna lisani: qad yabis ma'a gismi: wa laysa ana mustahiqqan: li-anni ghashsh.\n\n(24/15) Wa qad akhta't: wa laysa li raha: wal-ana ana uhni lak: rukbatayya wa qalbi.\n\n(24/16) Wa as'al salahak: wa abtahil ilayk: an taghfir li: wa la tatrahni.\n\n(24/17) Ana el-gahil: fi amakin el-buka': wa shiddat el-makhad: ma'a sareer el-asnan.\n\n(24/18) Anta es-salih: wahdaka ayyuha: el-mashi 'ala: agnihat er-riyah.\n\n(24/19) La tasna' ma'i: ka-hafawati: wa aqwali el-mamlou'a: ghishshan wa zulma.\n\n(24/20) Ya man anta: wahdaka fa'iq el-gawhar: la tadhkur khatayaya: ayyuha el-khaliq.\n\n(24/21) Et-tab' el-ghayr el-mutagassid: akhadh gasadan: bi-kull naqawa: fa-ya ayyuha el-Ilah.\n\n(24/22) Imnahni an agid: rahma wa ni'ma: li-kay atanawal min gasadik: ghufranan li-zallati.\n\n(24/23) Khubzan natiqan: wa rouhaniyyan: wa sharaban kareeman: muwaqqaran.\n\n(24/24) Wa kadhalika: attaki' ma'a el-muttaki'een: wa kull el-mutana''imeen: fi firdaws el-farah."],
  [["kiahk-midnight-hymn-32"], "Khudhou bi-aydeekum el-'asharat awtar, el-qeethara alladhi li-Dawoud el-malik.\n\nWa arghan el-mouseeqa wal-bouq er-rouhani.\n\nWasrukhou bi-tahleel qa'ileen: barikou er-Rabb min es-samawat. Barikouhu fil-a'ali. Barikou er-Rabb ilahana ya sama' es-samawat, bi-sunougin shagiyyat es-sawt. Wa maggidou ismahu wa sabbihouh.\n\nFa-bi-ilahina yaleeq aswat el-mizmar, wa yahsun lahu en-nasheed fi Sahyoun, wan-nudhour fi Urushaleem. Anshidou lir-Rabb ilahina nasheedan gadeedan, wal-yafrah Isra'eel bir-Rabb ilahina.\n\nRattilou lahu bi-ittifaq es-sufouf wa tamageed rouhaniyya. Iftakhirou bihi ya kull qiddiseeh, wa surrou ma'ahu bi-magdin 'azeem. Udkhulou ila diyar qudsih, washkurouhu bit-tahleel. Rattilou li-ismihi el-'ali, li-annahu ga'alana lahu sha'ban mubarraran, wa umma mutahhara. Fal-nusabbihahu bi-ghayr futour.\n\nNasgud laka ayyuha el-Maseeh ilahuna ma'a abeeka es-salih war-Rouh el-Qudus, li-annaka ateet wa khallastana."],
  [["kiahk-midnight-hymn-33"], "(62/1) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/2) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/3) Ana aftah fayya wa atakallam, wa antiq bi-asrar khafiyya, bi-karamat umm en-nour Maryam, toubaki ya zayn el-bashariyya.\n\n(62/4) Bi-ibniki ya zayn el-'alam sirna, ahraran min ba'd el-'ubudiyya, wa min asr Iblees khallasna, toubaki ya zayn el-bashariyya.\n\n(62/5) Tammat 'anki kull el-aqwal, wash-shahadat en-nabawiyya, ethve epjin-masf en-Emmanouēl, toubaki ya zayn el-bashariyya.\n\n(62/6) Gibra'eel bil-bushra nadaha, bi-hulul el-Kalima el-azaliyya, bikr batoul hamalat mawlaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/7) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/8) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/9) Hall bi-rouh qudsihi fi ahsha'iki, wa akhadh minki en-nasoutiyya, basharan kamilan hamalathu yadaki, toubaki ya zayn el-bashariyya.\n\n(62/10) Khallas Adam wa baneeh, wa abra'ahu min summ el-hayya, wa ila martabatihi qad raddah, toubaki ya zayn el-bashariyya.\n\n(62/11) Dawoud abouki qal 'anki, wa nataq bi-shahadat nabawiyya, ilah el-aliha sar ibnaki, toubaki ya zayn el-bashariyya.\n\n(62/12) Du'eeti umman li-man ansha'aki, li-agl khalas el-bashariyya, ata wa sakan fi ahsha'iki, wa anti 'adhra' bi-bakouriyya.\n\n(62/13) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/14) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/15) Rabb el-magd ikhtar husnaki, wa zanaki bil-lahoutiyya, wa akhadh tab' en-nasout minki, toubaki ya zayn el-bashariyya.\n\n(62/16) Zar'un athmar min ghayr bidhar, zahar min ghayr ma' wa saqya, fi haql naqiyy tahir mukhtar, toubaki ya zayn el-bashariyya.\n\n(62/17) Sammaki el-aba' el-abrar, sama'an thaniya gasadaniyya, sakan feeki el-mawla el-gabbar, toubaki ya zayn el-bashariyya.\n\n(62/18) Shahid Hizqiyal wa ra'aha, baban makhtouman fish-sharqiyya, dakhal feehi wa kharag mawlaha, wal-bab masan bi-bakouriyya.\n\n(62/19) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/20) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/21) Sofonias sharah bi-kalam, 'an tadbeer el-lahoutiyya, qal yanzil ka-qatr bi-ghayr ghamam, toubaki ya zayn el-bashariyya.\n\n(62/22) Danyal 'ayan pi-thronos, wa hawlahu tughmat nouraniyya, wa 'alayhi galas el-malik el-quddous, toubaki ya zayn el-bashariyya.\n\n(62/23) Ta'ta' sama' es-samawat wa nazal, wattahad bin-nasoutiyya, wa huwa fi hidn abeehi lam yazal, toubaki ya zayn el-bashariyya.\n\n(62/24) Zaharat 'aga'ib wa ra'aynaha, fi kutub el-bee'a el-maseehiyya, bikr batoul hamalat mawlaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/25) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/26) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/27) 'Ala qadruki 'an kull tuqous, wa 'an et-tughmat el-'ulwiyya, wa 'asakir ni-aggelos, toubaki ya zayn el-bashariyya.\n\n(62/28) Ghafir kull khataya sha'bih, wa manihhum kull 'atiyya, tashabbah bil-'abd wa ahabbah, toubaki ya zayn el-bashariyya.\n\n(62/29) Futti 'an sa'ir pi-kosmos, nem ni-tagma nem ni-estratia, nem ni-ethmi nem ni-dikeos, toubaki ya zayn el-bashariyya.\n\n(62/30) Qoulou ya ikhwa \"toubaha,\" ouoh ten-shōs en-nēb Maria, amam man hamalat fi ahshaha, hiten ni-tōbh nem ni-epresvia.\n\n(62/31) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/32) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/33) Rabb el-magd qad hamalti, musawwir kull el-bashariyya, wa bi-kursi el-Ab tashabbahti, toubaki ya zayn el-bashariyya.\n\n(62/34) Labis minki tab' en-nasout, muttahidan bil-lahoutiyya, wa hamalti el-wahid min eth-thalouth, toubaki ya zayn el-bashariyya.\n\n(62/35) Man nal ma nilti ya Maryam, fi sa'ir kull el-bashariyya, wa kull shu'oub wa kull umam, toubaki ya zayn el-bashariyya.\n\n(62/36) Nahnu el-kull naqoul \"toubaha,\" wa nurattil bakir wa 'ashiyya, li-man ikhtar husn bahaha, bi-hulul el-Kalima el-azaliyya.\n\n(62/37) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/38) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/39) Hayyi'i li et-tawba ya Maryam, qabl an yadnou el-waqt 'alayya, wa astayqiz min ghaflat el-ayyam, wa anhad min ba'd tawaniyya.\n\n(62/40) Wa uhayyi' ez-zad qabl es-safar, wa ugahhiz lil-'amal matiyya, li-tusa'ideeni fi ard qafra, bi-salatiki ya sayyidat el-bashariyya.\n\n(62/41) Li-anni 'agiz wa guhdi qaleel, wa himli yathqul 'alayya, wa han waqti li-safar wa raheel, wa la li shafee'a illa hiya.\n\n(62/42) Ya man la natraga siwaha, wa nas'aluha bakir wa 'ashiyya, wa nata'allaq fi taraf rida'iha, wa malabisiha en-nouraniyya.\n\n(62/43) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/44) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/45) Wa aqra' salami li-umm en-nour, Maryam shafee'at kull el-maseehiyya, allati el-khalas minha mash-hour, li-gamee' sha'b el-ma'moudiyya.\n\n(62/46) Tunaggeena min kull shurour, wa min el-afat ez-zamaniyya, wa tusa'iduna fi kull umour, wa kull shu'oub el-maseehiyya.\n\n(62/47) Yaqoul el-kull \"toubaha,\" wa yas'alounaha bakir wa 'ashiyya, quddam man hamalat fi ahshaha, tashfa' feena el-kull sawiyya.\n\n(62/48) Wal-ab el-fadil batrakna, 'amoud ed-diyana el-maseehiyya, ra'in salih wa muthabbituna, bi-husn siyasa wa ra'iyya.\n\n(62/49) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/50) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/51) Ab el-aba' el-hibr el-warith, kahanout malki-sadaqiyya, bi-iman saheeh wa raga' thabit, wa mahabba orthodoksiyya.\n\n(62/52) Hafiz ghanamihi min yad edh-dheeb, wa min kull fikhakh shaytaniyya, mubtil 'anhum kull amr ghareeb, wa kull bida' el-Arioussiyya.\n\n(62/53) Ra'i sha'bihi bi-ladheedh sawtih, wa ta'aleemihi er-rouhaniyya, hanni'hu ya Rabb bi-kahanoutih, bi-'umr faseeh wa tuma'neena.\n\n(62/54) El-ab el-'amil bin-namous, wa qawaneen esh-sharatouniyya, Aba (...) pi-arkhi-erevs, 'amoud deen en-nasraniyya.\n\n(62/55) (Qarar) El-'ullayqa allati ra'aha, Mousa en-nabi fil-barriyya, wan-neeran tash'il guwwaha, wa lam tamassaha bi-adhiyya.\n\n(62/56) (Qarar) Mithal umm en-nour toubaha, hamalat gamr el-lahoutiyya, tis'at ash-hur fi ahshaha, wa hiya 'adhra' bi-bakouriyya.\n\n(62/57) Wal-ab el-fadil usqufna Anba (...), shareekuhu fil-khidma er-rasouliyya, bi-qabul salatihi yag'aluna, abna' el-malakout el-abadiyya.\n\n(62/58) Wa thabbit sa'ir kahanatina, qamamisa wa qusousiyya, wa adim 'imarat bee'atina, bi-raf' qarabeen mardiyya.\n\n(62/59) Wa ana huwa en-nazim Ghubriyal / mansoub bi-madeeh bikr naqiyya / wa natawassal bi-shugaa' wa batal / wa sabiqun lahu el-fadl 'alayya.\n\n(62/60) Kabadouki fakhr esh-shug'an / mansoub bin-nisba el-asliyya / muqaddam kull esh-shug'an / wa zayn kull el-Kabadoukiyya.\n\n(62/61) Pi-athlophoros emmartyros / kawkabun shariq fis-subhiyya / Pashois epouro Gi'orgios / sahib 'azm wa nagda qawiyya.\n\n(62/62) Wa akhtim aqwal rattabnaha / fi madeeh bikr wa naqiyya / wa kull maseehi yaqraha / tashfa' lahu li-mahw kull khatiyya."],
  [["kiahk-midnight-hymn-34"], "(32/1) Talabtuk, min 'umq qalbi, khallis 'abdak, ayyuha el-Maseeh sayyiduna.\n\n(32/2) Hull 'anni, ribatat el-khatiyya, wa anqidhni, ana el-khati'.\n\n(32/3) Kun li mu'eenan, wa khallisni, ayyuha es-salih, wa asghi li-sam'i.\n\n(32/4) Yudrikuni salahuk, 'agilan, a'tini ya Ibn Allah, azminatan ladheedha.\n\n(32/5) Usturni taht, zill ganahayk, wa qawwini ya malik, el-abad.\n\n(32/6) Fi sittat ayyam, khalaqta el-barriyya kullaha, wa fi sittat ayyam, qabilta el-alam bil-gasad.\n\n(32/7) Sab' marrat kull yawm, ubarik ismak, ishfi amradana, wa kun ma'ana.\n\n(32/8) Hou dha kull el-barriyya, tumaggid ismak, ayyuha es-Sayyid, isna' ma'ana.\n\n(32/9) Laka er-rububiyya, was-sultan, kun lana harisan, ila el-inqida'.\n\n(32/10) Asri' ya ilahi, li-tukhallisana, ya Yasou' ya Ibn Allah, tara'af 'alayya.\n\n(32/11) Kull rukba, tagthou amamak, hulwun huwa ismuka el-quddous, sayyidana ighfir li.\n\n(32/12) Kull el-alsun ma'an, tubarik ismak, bi-thalathat taqdeesat ma'an, nas'aluka an tarhamna.\n\n(32/13) Rudd waghaka, 'an khatayaya, ya malik el-magd, a'tini salamak.\n\n(32/14) Kull athami, Allahumma imhaha, wa kull a'da'i, ya Rabb hattimhum.\n\n(32/15) Ta'rif afkari, wa tafhas kulyati, ya malik es-samawat, ismuka mubarak.\n\n(32/16) Qalban tahiran, ikhluqhu fiyya, ayyuha el-Ibn el-quddous, tahhir qalbi.\n\n(32/17) Rouhaka el-quddous, la tanzi'hu minni, wasma' li-du'fi, wa a'inni.\n\n(32/18) Amil sam'ak, wasma'ni 'agilan, wa ruddani, ana ed-dall.\n\n(32/19) Thabbit li namousak, fi tareeq 'adlik, wa afhimni, ayyuha en-nour el-mushriq.\n\n(32/20) Malakoutuka ya ilahi, malakoutan abadiyyan, nasgud laka ya Ibn Allah, ila el-abad.\n\n(32/21) Anta Ibn Allah, amantu bik, nurattil lak, wa nakhdimuk.\n\n(32/22) Ya hamil khatiyyat el-'alam irhamna, tahhirna min khatayana, wa kull shurourina.\n\n(32/23) Utruk lana, athamana el-katheera, ayyuha el-Ilah el-haqeeqi, a'tina khalasan.\n\n(32/24) Kull el-anfus ma'an, tubarik ismak, a'tini burouda, waktub asma'ana.\n\n(32/25) Ta'anna 'alayya, la tuhlikni 'agilan, fal-tahdini, li-ard ghayr mudmahilla.\n\n(32/26) Aqoum bakiran, wa ubarik ismak, wa narfa'uhu ma'an, ya sayyidana irhamna.\n\n(32/27) Hulwun huwa neeruk, wa himluka khafeef, anta el-mutahannin, 'ala khaleeqatih.\n\n(32/28) Fi zaman maqboul, istagib li, la tasna' el-hukm, ya malikana ma'i.\n\n(32/29) Mahboubun huwa, ismuka el-quddous, anta huwa el-awwal, wal-akhir ma'an.\n\n(32/30) Farriq 'anni, kull el-abalisa, unzur ilayya, ya sayyidi kull heen.\n\n(32/31) Ighris feena, thamarat 'adlik, ilahi el-haqeeqi, tahhir qalbi.\n\n(32/32) A'tina salamataka el-haqeeqiyya, waghfir lana khatayana, bi-mahabbatik, ila el-inqida'."],
  [["kiahk-midnight-hymn-35"], "(29/1) Amdah 'adhra' batoul / bi-ma'ounatiha atakallam / wa aseeh bi-a'la sawt wa aqoul / es-salam laki ya Maryam\n\n(29/2) Bashsharaki Ghubriyal / bil-meelad el-a'zam / bil-bushra surra wa qal / es-salam laki ya Maryam\n\n(29/3) Ta'alou bi-agma'ikum / el-yawm li-nataqaddam / wa aseeh ana ma'akum / es-salam laki ya Maryam\n\n(29/4) Galeel el-umam esh-sha'b / el-galis fiz-zalam / ashraq 'alayhi nour er-Rabb / es-salam laki ya Maryam\n\n(29/5) Halaf er-Rabb li-Dawoud / bil-haqq wa lam yandam / wa bi-ibniki tamm el-maw'oud / es-salam laki ya Maryam\n\n(29/6) Khallas Adam wa baneeh / min nar Gahannam / wa raddahu ila na'eem kan feeh / es-salam laki ya Maryam\n\n(29/7) Dawoud el-yawm masrour / farih ma'ana heen tamm / kalamuhu fil-mazmour / es-salam laki ya Maryam\n\n(29/8) Dhalika el-haml el-mukhtar / u'gouba li-man yafham / ka-zar' bi-ghayr bidhar / es-salam laki ya Maryam\n\n(29/9) Ra's el-aba' Ibraheem / farih li-tamam qasam / min er-Rabb lahu qadeem / es-salam laki ya Maryam\n\n(29/10) Zalat el-la'na wal-'ar / wa 'anna wa qad rahim / idh hall fi sayyidat el-abkar / es-salam laki ya Maryam\n\n(29/11) Sama' anti wa mithal / li-gamee' man taqaddam / wa ila kull el-agyal / es-salam laki ya Maryam\n\n(29/12) Shahid bil-haqq Isha'ya / anna el-Ibn yatagassam / minki wa youlad zamaniyyan / es-salam laki ya Maryam\n\n(29/13) Sar en-nagm kad-daleel / lil-magous wa taqaddam / wa waqaf haythu 'Immanu'eel / es-salam laki ya Maryam\n\n(29/14) Daw' en-nagm nazarouh / wa arshadahum fiz-zalam / wa li-Heeroudus haqqaqouh / es-salam laki ya Maryam\n\n(29/15) Talab el-makkar wa rada / qatl el-mawloud wa za'am / annahu malik ardi / es-salam laki ya Maryam\n\n(29/16) Zafar bihi el-fursan / wa kull minhum qaddam / el-murr wadh-dhahab wal-luban / es-salam laki ya Maryam\n\n(29/17) 'Aqli fi wasfiki hayran / wa ana haqqan a'lam / anni 'agiz el-lisan / es-salam laki ya Maryam\n\n(29/18) Ghab 'aqli wa ham / fi man ahyana ba'd 'adam / kayfa harab li-gabal Qusqam / es-salam laki ya Maryam\n\n(29/19) Fil-Matariyya hammouh / fa-tala' shagar el-balsam / minhu el-mairoun sana'ouh / es-salam laki ya Maryam\n\n(29/20) Qal el-anbiya' bir-rouh / lamma awha wa alham / wa fil-kitab mashrouh / es-salam laki ya Maryam\n\n(29/21) Kam laki min a'ageeb / kam laki ayat 'izam / ikhtar feeha el-labeeb / es-salam laki ya Maryam\n\n(29/22) Lawla er-Rabb el-Ilah / li-khalas Adam taqaddam / la-dumna fi riqq a'dah / es-salam laki ya Maryam\n\n(29/23) Mousa fi Tour Seena / wa gabal bahr el-Qulzum / a'tahu rabbuhu lawhayn / es-salam laki ya Maryam\n\n(29/24) Nazeer el-'ashr kalimat / kutibat bi-ghayr qalam / wa ra'aki 'ullayqa bi-thabat / es-salam laki ya Maryam\n\n(29/25) Ha ibnuki qad nagga / sa'ir esh-shu'oub wal-umam / wa ila el-haqq ahda / es-salam laki ya Maryam\n\n(29/26) War-Rabb qad ahyana / heen ga' wa ta'allam / wa min edh-dhull fadana / es-salam laki ya Maryam\n\n(29/27) La tansay batrakna / wamnahhu wafir en-ni'am / wa shareekahu usqufna (...) / es-salam laki ya Maryam\n\n(29/28) Ya Rabb naggina / li-annana sha'buka wa ghanam / ra'iyyatuka farhamna / es-salam laki ya Maryam\n\n(29/29) Wa ila er-Rabb el-quwwat / fal-nasrukh ya Rabb irham / qa'ileen bi-a'la el-aswat / es-salam laki ya Maryam"],
  [["kiahk-midnight-hymn-37"], "(52/1) Iftah fayya bit-tasbeeh / wa aqoul bi-qalbin gareeh / ya rabbi Yasou' el-Maseeh / a'tini lisanan faseeh\n\n(52/2) Li-kay usabbih ismak / wa ashkur fadl in'amak / ya rabbi Yasou' el-Maseeh / 'allimni ahkamak\n\n(52/3) Quddousun ismuka wa 'ageeb / wa mumaggadun fi qiddiseek / ya rabbi Yasou' el-Maseeh / irham san'at yadayk\n\n(52/4) Mustahiqqun wa mustawgib / et-tasabeeh wat-tamageed / ya rabbi Yasou' el-Maseeh / tasbeehuka hulwun wa ladheedh\n\n(52/5) Sarakhtu toul en-nahar / madadtu nahwaka yadi / ya rabbi Yasou' el-Maseeh / ismuka hulwun 'indi\n\n(52/6) Ga'altu ittikali 'alayk / ya Rabb la tuhmilni / ya rabbi Yasou' el-Maseeh / la tatakhalla 'anni\n\n(52/7) Rouhaka el-quddous / la tanzi'hu minni / ya rabbi Yasou' el-Maseeh / bi-ma'ounatika ishmalni\n\n(52/8) Garahani el-'adouw bi-siham / wa garhuhu fi haq / a'tini gasadaka marham / wa damaka li tiryaq\n\n(52/9) Sab' marrat kull yawm / kull yawm ubarik ismak / ya rabbi Yasou' el-Maseeh / ig'alni min qismak\n\n(52/10) Ishtaqat nafsi ilayk / kal-ard el-'atshana / ya rabbi Yasou' el-Maseeh / bi-rahmatika la tansana\n\n(52/11) La tansa bee'atana / imla'ha min khayratik / ya rabbi Yasou' el-Maseeh / thabbitha bi-shahadatik\n\n(52/12) Shahadatuka hulwa fi halqi / kash-shahd dakhil fami / ya rabbi Yasou' el-Maseeh / ighsilni min ithmi\n\n(52/13) Nashkur sani' el-khayrat / nasgud lir-Rabb Yasou' / el-Maseeh Rabb el-quwwat / fal-narka' lahu bi-khushou'\n\n(52/14) Rattib feena ahkamak / wa bi-qawlika thabbitna / ya rabbi Yasou' el-Maseeh / irfa' sha'n kaneesatina\n\n(52/15) Irfa' sha'n el-maseehiyyeen / fi gamee' el-maskouna / ya rabbi Yasou' el-Maseeh / ishmalhum bi-ma'ouna\n\n(52/16) Wa in kunna fuqara' min el-mal / ismuka huwa yakfeena / ya rabbi Yasou' el-Maseeh / wa salahuka yughneena\n\n(52/17) Yagibu laka et-tasbeeh / yanbaghi laka el-barakat / ya rabbi Yasou' el-Maseeh / yanbou' kull el-khayrat\n\n(52/18) Ya Rabb khallis sha'bak / wa barik meerathak / irfa' sha'nahum bi-ismik / wa warrithhum malakoutak\n\n(52/19) Malakoutuka ya ilahi / malakoutun abadiyya / wa siyadatuka ya maliki / siyada azaliyya\n\n(52/20) Azaliyya wa murtafi'a / wa 'ageeba hiya af'aluk / ya rabbi Yasou' el-Maseeh / sayyid kull mamalik\n\n(52/21) Mamalik ed-dunya tazoul / wal-mal kulluhu fani / ya rabbi Yasou' el-Maseeh / mulkuka ghayr mutanahi\n\n(52/22) Tatanaha kull mamalik / tafna kunouz el-umara' / ya rabbi Yasou' el-Maseeh / anta kanz el-fuqara'\n\n(52/23) Fuqara' sha'bika aghnihim / wal-marda ishfihim / wal-aytam rabbihim / min fadlika aghnihim\n\n(52/24) Aghnihim min fadlik / awfi kull el-madyouneen / ya rabbi Yasou' el-Maseeh / anta ghina el-muhtageen\n\n(52/25) In kunna muhtageen / fa-lana durra thameena / lana el-hagar el-kareem / Yasou' ghali el-qeema\n\n(52/26) Ghali el-qeema wa kareem / aghla min ed-dunya tamam / ismuhu Yasou' el-Maseeh / el-ghafir kull atham\n\n(52/27) Ghafir kull edh-dhunoub / sami' li-man yad'ouh / ta'tarif lahu kull esh-shu'oub / wal-moulouk yusabbihouh\n\n(52/28) Sabbihouhu ya kull el-umam / maggidouhu ya kull esh-shu'oub / ya rabbi Yasou' el-Maseeh / tuballighna el-matloub\n\n(52/29) Matloubuna malakoutak / wa marahimuka mawgouda / ya rabbi Yasou' el-Maseeh / ya man tab'uhu el-gouda\n\n(52/30) Sahib gouda wa kareem / wa laysa lahu qatt nazeer / ya rabbi Yasou' el-Maseeh / anta 'ala el-kull baseer\n\n(52/31) Baseerun wa mutatalli' / 'alayna bi-tadabeerik / ya rabbi Yasou' el-Maseeh / la tuhwigna li-ghayrik\n\n(52/32) La na'rif ghayraka ilah / bi-Ingeelika saddaqna / anta huwa Ibn Allah / fi imanika thabbitna\n\n(52/33) Thabbitna 'ala el-iman / wanhadna min kull malal / ya rabbi Yasou' el-Maseeh / bi-ismika natahallal\n\n(52/34) Natahallal bil-alhan / wa nurattil bil-mazameer / ya rabbi Yasou' el-Maseeh / tasbeehuka bahga wa surour\n\n(52/35) Sourouruna tasabeehuk / bahgatuna hiya magduk / ya rabbi Yasou' el-Maseeh / el-'azama laka wahdak\n\n(52/36) Laka wahdaka ana akhta't / wa sana'tu esh-sharr amamak / li-tasduq fi aqwalik / wa taghlib fi ahkamik\n\n(52/37) Ahkamuka haqqun wa 'adl / wa marahimuka muttasi'a / ya rabbi Yasou' el-Maseeh / irham nafsi el-muttadi'a\n\n(52/38) Ittada'tu amam magdik / wattakaltu 'ala aqwalik / ya rabbi Yasou' el-Maseeh / la tatrahni 'ala shimalik\n\n(52/39) 'Ala shimalika la tuwaqqifni / ma'a el-qawm el-ashrar / as'aluka an taqbalni / kama qabilta el-'ashshar\n\n(52/40) Asrukh bi-sawt el-'ashshar / wa ana bi-ra'sin mutati / Allahumma ighfir li el-awzar / fa-ana 'abduka khati\n\n(52/41) El-khatiyya min tab'i / wa anta tab'uka el-ihsan / laysa 'abdun bila khatiyya / wala sayyidun bila ghufran\n\n(52/42) El-ghufran min 'indak / war-rahma hiya min qibalak / ya rabbi Yasou' el-Maseeh / ihdini ila subulik\n\n(52/43) Subuluka tahat 'anni / wal-'umr faragh minni / as'aluka taqbalni / wat-tawba a'tini\n\n(52/44) A'tini et-tawba wa ghufran / wa naqqini min kull 'uyoubi / ya rabbi Yasou' el-Maseeh / ighfir li dhunoubi\n\n(52/45) Dhunoubi thaqulat fawq ra'si / ka-himlin thaqeelin qasi / ya rabbi Yasou' el-Maseeh / ishfi kull hawassi\n\n(52/46) Marahimuka ya ilahi / hiya katheera giddan / marahimuka ya ilahi / la yuhsa laha 'adadan\n\n(52/47) Marahimuka ya ilahi / akthar min nabat el-ard / marahimuka ya ilahi / qad faqat kull 'adad\n\n(52/48) Marahimuka ya ilahi / ka-qatarat el-amtar / marahimuka ya ilahi / akthar min raml el-bihar\n\n(52/49) Marahimuka ya ilahi / ka-yanabee' el-miyah / marahimuka ya ilahi / kal-anhar el-gariya\n\n(52/50) Ya Rabb irham nafsi / ya Rabb khallisni / ya Rabb imhi ithmi / bi-salahika udhkurni\n\n(52/51) Quddous quddous quddous / Allah Rabb es-Saba'out / el-khaliq kull en-nufous / wa raziquhum bil-qout\n\n(52/52) Nas'aluka ya malikana / adim ri'asat batrakna / wa shuraka'ahu matarinatna / ameen hallelouia"],
  [["kiahk-midnight-hymn-38"], "(24/1) Ta'alou ayyuha esh-shu'oub: li-numaggid el-Maseeh: wa walidat el-Ilah: Maryam el-'Adhra'.\n\n(24/2) Kull mudun wa qura: el-orthodoksiyyeen: yumaggidouna fi kull heen: Maryam el-'Adhra'.\n\n(24/3) Kull el-agnas: taqoul es-salam: lil-mumtali'a magdan: Maryam el-'Adhra'.\n\n(24/4) Dawoud en-nabi: takallam bi-karamatik: ya Maryam el-malika: Maryam el-'Adhra'.\n\n(24/5) Min agl hadha: nu'azzimuki bi-istihqaq: ayyatuha el-qubba eth-thaniya: Maryam el-'Adhra'.\n\n(24/6) Es-sab' tughmat: es-sama'iyya: yumaggidouna kull heen: Maryam el-'Adhra'.\n\n(24/7) Ha el-anbiya': wa es-siddeeqoun: ya umm es-Sayyid: Maryam el-'Adhra'.\n\n(24/8) Igtami'ou wa maggidou: el-yawm ma'a er-rusul: li-kay numaggid: Maryam el-'Adhra'.\n\n(24/9) Yasou' el-Maseeh ilahuna: el-haqeeqi waladat-hu: kawnahu huwa el-Ilah: Maryam el-'Adhra'.\n\n(24/10) Murtafi'a giddan: akthar min el-mala'ika: wa kull et-tughmat: Maryam el-'Adhra'.\n\n(24/11) Kull esh-shu'oub el-mu'mineen: yusabbihouna el-malik el-Maseeh: li-agl walidat el-Ilah: Maryam el-'Adhra'.\n\n(24/12) Maryam el-'arous: Maryam en-naqiyya: umm er-ra'ouf: Maryam el-'Adhra'.\n\n(24/13) Moulouk el-ard ifrahou: bil-Maseeh min agl: es-sama' el-gadeeda: Maryam el-'Adhra'.\n\n(24/14) Tabarakta ayyuha el-Maseeh: ihfaz sha'bak: min agl en-naqiyya: Maryam el-'Adhra'.\n\n(24/15) 'Azeematun hiya karamat: walidat el-Ilah: akthar min gamee' el-qiddiseen: Maryam el-'Adhra'.\n\n(24/16) Ikleel fakhrina: hiya walidat el-Ilah: wa thabat taharatina: Maryam el-'Adhra'.\n\n(24/17) Ifrahou wa tahallalou el-yawm: ayyuha el-maseehiyyoun min agl: el-mumtali'a magdan: Maryam el-'Adhra'.\n\n(24/18) Zayyanti nufousana: ya walidat el-Ilah: el-fatah el-hakeema: Maryam el-'Adhra'.\n\n(24/19) Natlub ilayka ayyuha el-Maseeh: ihfaz sha'bak: min agl en-naqiyya: Maryam el-'Adhra'.\n\n(24/20) Ya Ibn Allah ilahuna: ighfir li-sha'bika min agl: sayyidatina wa malikatina: Maryam el-'Adhra'.\n\n(24/21) Farriq el-a'da' bi-mithalik: min qibal: el-ghayr munhall: Maryam el-'Adhra'.\n\n(24/22) Es-salam lil-kursi alladhi: li-Yasou' el-Maseeh: es-salam li-walidat el-Ilah: Maryam el-'Adhra'.\n\n(24/23) Anfus aba'ina: nayyihhum ayyuha el-Maseeh: min agl walidat el-Ilah: Maryam el-'Adhra'.\n\n(24/24) Ya malikana Yasou' er-ra'ouf: ihfaz Neeqoudeemous: min agl ummika el-'arous: Maryam el-'Adhra'."],
  [["kiahk-midnight-hymn-41"], "(16/1) Abda' bism Allah / es-sakin fin-nour / alladhi kallam Mousa / min fawq gabal et-Tour\n\n(16/2) Qa'ilan ya Mousa / inhad farihan masrouran / li-u'allimaka bima kan / kama 'anhu tanabba'oun\n\n(16/3) Inhad ya Mousa / was'ad ila a'la el-gibal / wabni hunak qubba / takoun laka shibh mazal\n\n(16/4) Wa gamee' ma qultuhu lak / uktubhu fil-hal / hadhihi hiya shahada / lil-Isra'eeliyyeen\n\n(16/5) Asri' ya Mousa / unzur hadha el-makan / wabni feehi qubba / bil-hagar es-sawwan\n\n(16/6) Wa 'ala shawari'iha / wa'mal laha arba'at arkan / wagma' ma yahtag / ilayhi el-banna'oun\n\n(16/7) Wa'mal kharig el-qubba / fus-ha kad-dihleez / wa utleeha ya Mousa / bidh-dhahab wal-ibreez\n\n(16/8) Dakhil ma'a kharig / karama lit-takrees / min a'la ila asfal / bidh-dhahab el-mawzoun\n\n(16/9) Wa'mal dakhil el-qubba / madhbah lil-qurban / wa'mal hawl el-madhbah / arba'at 'umdan\n\n(16/10) Yakoun min fawqiha / min edh-dhahab Karouban / bi-agniha mafrousha / ejen pi-hilastērion\n\n(16/11) Wag'al feeha / tabout el-'ahd el-matli / wa feehi el-qist edh-dhahab / bil-mann el-makhfi\n\n(16/12) Wa feehi shouriyyat Haroun / min edh-dhahab el-musaffa / wa feehi lawha el-'ahd / ma'a 'asat Haroun\n\n(16/13) Wa feehi el-manara / min edh-dhahab el-mukhtar / wa feehi el-ma'ida dhahab / tash'il ka-gamr en-nar\n\n(16/14) Wa zayyinha ya Mousa / bi-sa'ir kull el-anwar / wag'al feeha aydan / sab'at surug yuneeroun\n\n(16/15) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(16/16) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-43"], "(16/1) Qal er-Rabb li-Mousa / bi-sawt 'ali yunadeeh / qum isna' li taboutan / wa bidh-dhahab itleeh\n\n(16/2) Li-ada' sirri feeh / wa ag'al 'ahdi feeh / min khashab la yasous / wa bidh-dhahab tutlouh\n\n(16/3) Tashabbahti ya Maryam / bi-tabout el-'ahd el-matli / wa feehi el-qist edh-dhahab / bil-mann el-'aqli\n\n(16/4) Madeehuki fi fami / ahla min el-'asal / nuqri'uki kull salam / ya ibnat Sahyoun\n\n(16/5) Ya nagma tudawwi / ka-misbah en-nour / hamalti Ibn Allah / el-hayy el-ghayr manzour\n\n(16/6) Wa anqadh Adam / ba'd an kan ma'sour / wa 'ad huwa wa banouh / ila el-firdaws farihoun\n\n(16/7) Nawwarti el-'alam / ba'd an kan zulma / wa hamalti fi ahsha'iki / Ibn Allah el-Kalima\n\n(16/8) Anti hiya tabout / anti hiya el-hikma / anti hiya quwwatuna / wa farah es-siddeeqoun\n\n(16/9) Lamma arad Allah / wa sha' wakhtarak / wa arsal ilayki el-Kalima / bi-rouh qudsihi zanak\n\n(16/10) Wa hamalti fi ahsha'iki / er-Rabb ilahak / waladteehi wa radi' labanak / ka-sa'ir el-bashariyyeen\n\n(16/11) Hizqiyal tanabba' / fi ru'yahu wa qal / ra'aytu baban fil-mashriq / maqfoulan bil-aqfal\n\n(16/12) Dakhal feehi wa kharag / el-malik el-muta'al / wa lam yamassahu darar / wa bi-halihi makhtoumeen\n\n(16/13) Wa kam shahidou 'anki / fi nubouwat wa amthal / sawfa yazhar minki / er-Rabb el-muta'al\n\n(16/14) Wa yukhallis sha'bah / fi akhir el-agyal / bi-ibniki nilna el-ghufran / ya shouriyyat Haroun\n\n(16/15) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(16/16) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-45"], "(16/1) Ya Maryam sirti / madhbahan lil-ghufran / wa 'alayhi el-ma'ida dhahab / wa feehi el-gasad qurban\n\n(16/2) Huwa Ibn Allah el-hayy / el-mu'ti el-ghufran / li-kull naqiyy tahir / yaskun na'eem el-firdaws\n\n(16/3) Anti hiya el-madhbah el-'ali / el-mushtamila bil-anwar / wa nouruhu yatala'la' / mala' kull el-aqtar\n\n(16/4) Wa daw'uki ya Maryam / faq kull shumous wa aqmar / futti kull maratib / wa sa'ir kull tuqous\n\n(16/5) Futti er-ru'asa' / wal-arba'at hayawanat / wa aydan el-karasi / wal-arbab wal-quwwat\n\n(16/6) Hamalti Ibn Allah / khaliq kull el-makhlouqat / mu'ti kull hayah / li-kull gasad wa nufous\n\n(16/7) Ya zahrat el-atyab / bakhouruki 'anbar fah / ya nagma tudawwi / tudee' kal-misbah\n\n(16/8) Ya mamlou'a ni'ma / ya bad' el-afrah / bi-ibniki nilna el-khalas / wa na'eem el-firdaws\n\n(16/9) Danyal tanabba' / fi ru'yahu bi-thabat / qal ra'aytu kursiyyan ma'a nour / wa 'alayhi Rabb el-quwwat\n\n(16/10) Wa hawlahu ulouf wa ulouf / rabawat ma'a tughmat / yusabbihouna Allah / el-malik el-quddous\n\n(16/11) Tashabbahti ya Maryam / bi-kursi Allah el-khaliq / wa hamalti Ibn Allah / el-hayy en-natiq\n\n(16/12) Sammaki el-aba' / bab el-masharuq / wa kam wasafou 'anki / ya bikra wa 'arous\n\n(16/13) Er-Rabb ikhtaraki / min asl Yessa / min nasl naqiyy tahir / bayt en-nubouwa war-ru'asa'\n\n(16/14) Wa hamalteehi fi ahsha'iki / ya bikra wa 'arous / waladteehi wa radi' labanak / hōs rōmi entelios\n\n(16/15) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(16/16) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-47"], "(16/1) Ya qist dhahab ghali / wal-mann makhfi feeh / ramzan wa ishara / 'alayki ya walidat el-Ilah\n\n(16/2) Ya hagar el-gawhar / ya safeenat en-naga / toubaki ya Maryam / ya ibnat Sahyoun\n\n(16/3) Ya sullam Ya'qoub / hamalti ed-dayyan / wa sar fi ahsha'iki el-mahgoub / wa waladti Ibn el-insan\n\n(16/4) Wa shafa kull el-marda / wa fatah a'yun el-'umyan / wa aqam el-mayyit / ba'd an kan madfoun\n\n(16/5) Ya 'asat Haroun / nawwarti el-azhar / ya qubbat Mousa / el-mamlou'a anwar\n\n(16/6) Wa karma maghrousa / hamilat el-athmar / wa bi-ibniki nilna el-ghufran / ya gawhar maknoun\n\n(16/7) Dawoud qal fil-mazmour / wa qal 'ala el-qeetharat / er-Rabb ikhtar Sahyoun / wa sakan feeha bi-thabat\n\n(16/8) Hadha kulluhu mithal / wa ramzan wa isharat / 'alayki ya Maryam / ya ibnat Sahyoun\n\n(16/9) Er-Rabb ikhtar husnaki / fa-sakan feeki el-Ilah / waladteehi wa radi' laban / thadyayki bi-feeh\n\n(16/10) Irtafa'ti giddan / wa sirti ka-a'la samah / futti kull er-ru'asa' / wal-abrar wa es-siddeeqoun\n\n(16/11) Futti esh-Sharoubeem / ya sitt el-abkar / wa aydan es-Sarafeem / el-mamlou'a anwar\n\n(16/12) Ya ibnat Yowaqeem / min nasl el-abrar / ibnuki khallas Adam / ba'd an kan masgoun\n\n(16/13) Ya mamlou'a ni'ma / ya tuhr el-at-har / ya umm er-rahma / ya nour el-anwar\n\n(16/14) Bi-ibniki zalat ez-zulma / wa qad sirna ahrar / wa warithna el-malakout / bi-'imadina bil-mairoun\n\n(16/15) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(16/16) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-49"], "(16/1) Allah kallam Mousa / fawq gabal et-Tour aghar / qum isna' manara / min edh-dhahab el-mukhtar\n\n(16/2) Wa feeha sab'at surug / tunawwir layl wa nahar / min dakhil el-qubba / nem ti-kivōtos\n\n(16/3) Fa-sana' Mousa kama qal / wa 'amal el-manara / min edh-dhahab el-'al / toubaki ya mukhtara\n\n(16/4) Toubaki ya Maryam / futti kull amthal / wa nouruki ashraq feena / anon khen ni-pistos\n\n(16/5) Anti hiya el-manara / el-mamlou'a anwar / wa shu'a' nouriha ashraq / 'ala kull el-aqtar\n\n(16/6) Wa 'alawti ya Maryam / 'an el-aba' wal-abrar / hall bi-rouh qudsihi / feeki er-Rabb el-quddous\n\n(16/7) Ra'aki Mousa / fawq gabal et-Tour / shagara maghrousa / muhata bin-nour\n\n(16/8) Biki ya Maryam fuzna / bi-farah wa bahga wa surour / man nal ma nilti / fi sa'ir pi-kosmos\n\n(16/9) Laysa man yushbihuki / fil-ard wala fis-samawat / war-Rabb faddalaki / 'an kull el-makhlouqat\n\n(16/10) Wa qad shahidou 'anki / fi asfar wa nubouwat / sammaki el-aba' / ti-tshrompi ethnesōs\n\n(16/11) Dawoud abouki / fil-mazmour qad qal / er-Rabb ikhtar husnaki / wa zadaki nour wa gamal\n\n(16/12) Wa hall fi batniki / tis'at ash-hur bi-kamal / wa waladteehi wa radi' labanak / bi-bisharat pi-aggelos\n\n(16/13) Wa qal aydan / ya umm el-insan / wa insan hall feeha / wa huwa el-malik ed-dayyan\n\n(16/14) Alladhi huwa ansha'aha / wa arsal rouh qudsihi bi-bayan / wa wada'ti Allah el-haqq / el-khaliq kull nufous\n\n(16/15) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(16/16) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-51"], "(16/1) Ya shouriyyat Haroun / el-hamila gamr en-nar / wa bakhouruha wa 'anbaruha / mala' kull el-aqtar\n\n(16/2) Bi-wugoudiki ya Maryam / fuzna min harr en-nar / wa biki tamm el-maw'oud / kama 'anki tanabba'oun\n\n(16/3) Anti hiya esh-shouriyya / feeha teeb wa bakhour / hamalti Ibn Allah / ilah nour min nour\n\n(16/4) Wa hall fi batniki / tis'at shuhour / waladteehi wa radi' labanak / ka-sa'ir el-makhlouqeen\n\n(16/5) Ya shouriyyat Haroun / feeha bakhour min 'anbar / ya ibnat Dawoud / ya hagar el-gawhar\n\n(16/6) Hamalti el-ma'boud / wa zahar minki aghar / wa fakk kull wathaqat / wa kasar fakh el-arkhōn\n\n(16/7) Anti hiya esh-shouriyya / bakhour teebiki fah / wa mala' el-maskouna / wa biki nilna el-afrah\n\n(16/8) Nuqri'uki kull salam / fi kull masa' wa sabah / ya 'amoud deen / el-orthodoksiyyeen\n\n(16/9) Sulayman qal 'anki / fi Nasheed el-Anshad / ukhti wa sadeeqati / wa ilayki er-Rabb arad\n\n(16/10) Rawa'ih teebiki fah / min 'anbar wa zad / wa qal 'anki amthal / fin-nubouwat yash-hadoun\n\n(16/11) Toubaki ya Maryam / umm Iēsous Pi-ekhristos / ya haykal tahir / wa higab lil-Quddous\n\n(16/12) Ihfazi sha'b ibniki / shamamisa wa qusous / wa gamee' man fil-bee'a / esh-sha'b el-mugtami'oun\n\n(16/13) Es-salam laki ya Maryam / ya haykal mansan / nouruki ashraq feena / wa mala' kull el-akwan\n\n(16/14) Wa hamalti el-khaliq / Ibn Allah ed-dayyan / wa waladteehi insan / bil-lahout muttahidoun\n\n(16/15) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(16/16) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-53"], "Du'eeti ayyatuha el-'Adhra' Maryam el-qubba eth-thaniya allati lil-qiddiseen.\n\nMan yaqdir an yantiq bi-'izam karamat el-batouliyya allati li-walidat el-Ilah.\n\nAnti hiya et-tabout wal-madhbah alladhi wada'ou 'alayhi Karoubeem el-magd. Kull el-anfus ma'an yusabbihouna er-Rabb el-Ilah, wa yuqaddimouna lahu el-qarabeen, wa yu'tounaha lil-kahana.\n\nWa kan fil-qubba ma'idat dhahab, wa khubz el-wugouh el-mawdou' 'alayha, ma'a qist edh-dhahab el-mamlou' min el-mann. Ha'ula' yushbihouna Maryam el-'Adhra', li-anna khubz el-hayah alladhi nazal min es-sama' huwa Yasou' el-Maseeh.\n\nLi-annahu yaleeq biki ayyatuha el-qiddeesa kull magd wa karama ya walidat el-Ilah. Anti hiya el-manara el-hamila el-misbah el-mumtali' bi-nar el-lahout. Kull el-musawah el-'aliya allati an'am Allah lana biha fis-sama' wa 'ala el-ard ka-'azeem rahmatih, lamma tagassad min hadhihi el-'arous Maryam, el-migmara edh-dhahab el-'ali allati feeha el-'anbar.\n\nHina'idhin bil-haqeeqa la akhza el-yawm idha qultu annaki anti hiya el-migmara edh-dhahab en-naqiyya allati feeha el-gamr ma'a 'anbariha, allati fi yad Haroun ra'ees el-kahana, el-hamila el-bakhour wal-gamr el-mukhtar. Es-salam li-Maryam el-migmara en-naqiyya allati feeha el-gamr ma'a 'anbariha, wa huwa Yasou' el-Maseeh Ibn Allah, el-mann el-'aqli alladhi nazal min es-sama'.\n\nAnti hiya ez-zahra allati lil-bakhour min asl Yessa wa 'asat Haroun. Es-salam lillati waladat khaliq el-kull, Masiya ilahana, malik es-sama' wal-ard. Irtafa'ti giddan akthar min el-mala'ika wal-anbiya' war-rusul wash-shuhada' wal-qiddiseen, li-annaki anti hiya umm en-nour el-haqeeqi alladhi nasluk feehi ila mawdi' er-raha.\n\nIshfa'i feena amam ibniki el-habeeb malik el-magd fi yawm ed-deen, li-kay yarhamna wa yuthabbitna 'ala el-iman el-mustaqeem, wa yaghfir lana khatayana. Ameen."],
  [["kiahk-midnight-hymn-55"], "Toubaki anti ya Maryam el-'Adhra', li-anna Allah el-Kalima ikhtaraki lahu maskanan.\n\nToubaki anti ya Maryam el-'Adhra', el-qubba eth-thaniya allati lillah el-Ab.\n\nAyy madeeh, wa ayy tamgeed, wa ayy ta'zeem, uqaddimuhu ila mahall sharafiki ya walidat el-Ilah Maryam. Lakinnani as'al tahannun ilahina an yulhimani hikma sama'iyya, li-kay naqoul yaseeran mimma yaleeq bi-karamatiha, wa nurattil bi-sawt el-farah wat-tahleel hakadha qa'ileen:\n\nIfrahi ya fakhr el-mu'mineen el-orthodoksiyyeen allati biha warithou el-malakout. Ifrahi ya bahgat es-siddeeqeen allati min qibaliha khalasou min asr el-'adouw wa wasalou ila en-na'eem. Ifrahi ya ibnat Yowaqeem wa es-sayyida Hanna, allati takallam min agliha el-anbiya' wal-hukama', anna minha yatagassad el-mukhallis wa youlad meeladan batouliyyan.\n\nIfrahi ya tag esh-shuhada' alladhi biha taqawwou hatta fazou bi-irth malakout es-samawat. Ifrahi ya ra'ihat bakhour el-firdaws, allati bi-ibniha sirna nahnu el-maseehiyyeen banee el-malakout. Ifrahi ya walidat el-Ilah allati azharat et-teeb edh-dhaki alladhi min asl Yessa.\n\nIfrahi ya 'asat Haroun allati azharat wa awraqat min ghayr saqy. Ifrahi ya man hamalat alladhi la yahwihi makan fis-sama' wala 'ala el-ard. Ifrahi ayyatuha el-qubba eth-thaniya allati lil-qiddiseen. Ifrahi ayyatuha el-mushtamila bit-tahara dakhilaha wa kharigaha.\n\nIfrahi ayyatuha el-mumaggada min gamee' et-tughmat es-sama'iyya. Ifrahi ya man diya'uha yalma' akthar min daw' esh-shams. Ifrahi ayyatuha et-tareeq allati tousiluna ila ard el-hayah. Ifrahi ayyatuha el-mutamantiqa bil-farah wat-tahleel. Ifrahi ya ibnat Sahyoun nasl el-malik Dawoud.\n\nIfrahi ayyatuha el-qubba el-haqeeqiyya ed-dakhila quds el-aqdas. Ifrahi ayyatuha el-madhbah es-sama'i quds el-qiddiseen. Ifrahi ya mumtali'a ni'ma, er-Rabb ma'aki. Ishfa'i feena 'ind ibniki el-habeeb li-yaghfir lana khatayana. Ameen."],
  [["kiahk-midnight-hymn-56"], "(14/1) Du'eeti umm Allah / ya ibnat Yowaqeem / wa sirti ka-a'la samah / wa futti el-Karoubeem\n\n(14/2) Zahar minki yanbou' el-hayah / wa abra' kull saqeem / wa radd el-kharouf ed-dall / wa hattam fakh el-arkhōn\n\n(14/3) Ya qubbat Mousa / ya mamlou'a anwar / ya tabout el-'ahd / wa feehi kull el-asrar\n\n(14/4) Ya zahrat el-atyab / bakhouruki mala' el-aqtar / ya kanz el-gawhar / ya 'asat Haroun\n\n(14/5) Ya qist dhahab ghali / wal-mann makhfi feeh / ya haykal tahir / ahabbahu Allah wa sakan feeh\n\n(14/6) Wa man yu'min bi-ismih / ba'd el-mawt yuhyeeh / ya madhbah tahir / hamil es-sirr el-maknoun\n\n(14/7) Es-salam laki ya Maryam / ya sitt el-'adhara / sammaki el-aba' / kanzan wa manara\n\n(14/8) Wa kam darabou 'anki / ramzan wa ishara / ya bakhour el-'anbar / fi shouriyyat Haroun\n\n(14/9) Ya haykal wa higab / maskan lith-thalouth / ya kursi Allah el-Ab / Rabb es-Saba'out\n\n(14/10) Biki ya Maryam fuzna / bi-na'eem el-malakout / toubaki ya Maryam / etsoni en-Solomon\n\n(14/11) La tansay 'abdik / li-anni khati wa miskeen / wa argou shafa'atik / fil-mawqif yawm ed-deen\n\n(14/12) 'Ind Yasou' ibnik / kouni li 'awnan wa mu'een / li-kay yaghfir li dhanbi / wa man qad salafoun\n\n(14/13) (Qarar) Es-salam laki ya Maryam / ya mamlou'a ni'ma / ya mushtamila bil-anwar / ya umm er-rahma\n\n(14/14) Ishfa'i feena / fi yawm ez-zahma / bi-ibniki nilna el-khalas / ya ibnat Sahyoun"],
  [["kiahk-midnight-hymn-57"], "(24/1) Shere ne Maria: abda' feeki bi-madeeh. Shere ne Maria: nazm bi-qalb saheeh. Shere ne Maria: wa ashrah feeki wa aseeh. Shere ne Maria: qawl ghali mawzoun.\n\n(24/2) Shere ne Maria: bi-madeehiki yartah. Shere ne Maria: kull dhaleel muhtag. Shere ne Maria: ya bad' el-afrah. Shere ne Maria: laki 'indi 'arboun.\n\n(24/3) Shere ne Maria: thamarat 'arbouni. Shere ne Maria: ya tibb 'uyouni. Shere ne Maria: 'uzzali lamouni. Shere ne Maria: kam 'anni yaqoulou.\n\n(24/4) Shere ne Maria: ga'aki Ghubriyal. Shere ne Maria: bi-bashayir wa aqwal. Shere ne Maria: wa sakan feeki el-muta'al. Shere ne Maria: sirr makhfi maknoun.\n\n(24/5) Shere ne Maria: hall bi-kalimatih. Shere ne Maria: wa ashraq bi-qudratih. Shere ne Maria: sirti ka-sama'ih. Shere ne Maria: ya 'awsag bi-ghusoun.\n\n(24/6) Shere ne Maria: mukhallis el-'alam. Shere ne Maria: sar feeki qa'im. Shere ne Maria: wastayqaz kan-na'im. Shere ne Maria: wa makhmour bi-fanoun.\n\n(24/7) Shere ne Maria: Dawoud fil-mazmour. Shere ne Maria: qal banat Sour. Shere ne Maria: bi-hadaya wa nudhour. Shere ne Maria: qalou feeki bi-fanoun.\n\n(24/8) Shere ne Maria: rabawat thumma ulouf. Shere ne Maria: hawl el-'arsh wuqouf. Shere ne Maria: wa tughmat wa sufouf. Shere ne Maria: wa shuhada' muttasiloun.\n\n(24/9) Shere ne Maria: zidti fil-awsaf. Shere ne Maria: 'an kull el-awsaf. Shere ne Maria: wa mashayti bi-'afaf. Shere ne Maria: wa summeeti Sahyoun.\n\n(24/10) Shere ne Maria: Salome shahidat. Shere ne Maria: bi-anna el-'Adhra' wada'at. Shere ne Maria: amanat wa'taqadat. Shere ne Maria: wal-khatim masoun.\n\n(24/11) Shere ne Maria: Isha'ya qal 'anki. Shere ne Maria: bi-anna Yasou' ibnuki. Shere ne Maria: wa kharag min batniki. Shere ne Maria: wa nazarathu el-'uyoun.\n\n(24/12) Shere ne Maria: Sofonias khabbar. Shere ne Maria: bi-anna Yasou' yazhar. Shere ne Maria: shibh nada wa matar. Shere ne Maria: hawlahu sufouf la yuhsoun.\n\n(24/13) Shere ne Maria: toubaki thumma toubaki. Shere ne Maria: hayyarti el-'ulama'. Shere ne Maria: bi-wugoud er-rouh wal-ma'. Shere ne Maria: qaharna el-arkhōn.\n\n(24/14) Shere ne Maria: zann feeki aqwam. Shere ne Maria: bi-anna hadha el-habal haram. Shere ne Maria: hatta hall wa aqam. Shere ne Maria: el-amwat wal-magnoun.\n\n(24/15) Shere ne Maria: shabbahaki el-aba'. Shere ne Maria: qubba wa sahaba. Shere ne Maria: wa wada'ou bi-igaba. Shere ne Maria: wa gamee'uhum feeki muhtaroun.\n\n(24/16) Shere ne Maria: ghalab aqwam sabaqouh. Shere ne Maria: madahou ma lahiqouh. Shere ne Maria: ga'ou ba'dahu wagadouh. Shere ne Maria: bi-sirr khafi maknoun.\n\n(24/17) Shere ne Maria: feeki rida qalbi. Shere ne Maria: min sha'n talabi. Shere ne Maria: ya Maryam ya hasbi. Shere ne Maria: tagi wa ana doun.\n\n(24/18) Shere ne Maria: qubbat Mousa kan. Shere ne Maria: zakhrafaha bil-alwan. Shere ne Maria: wa ga'al feeha el-arkan. Shere ne Maria: bi-kull ala wa fanoun.\n\n(24/19) Shere ne Maria: lillah fil-qubba. Shere ne Maria: salawat wa talabat. Shere ne Maria: wal-qist 'alamat el-mahabba. Shere ne Maria: el-mann feehi maknoun.\n\n(24/20) Shere ne Maria: migmarat et-tas'eed. Shere ne Maria: feeha zahrat 'itr taqeed. Shere ne Maria: ya tabout 'ahd gadeed. Shere ne Maria: bi-safa'ih wa qouroun.\n\n(24/21) Shere ne Maria: nalou nour min nour. Shere ne Maria: sab' surug yuneeroun. Shere ne Maria: wa qadeeb kan madhkhour. Shere ne Maria: bism el-ab Haroun.\n\n(24/22) Shere ne Maria: haykal bi-mawa'id. Shere ne Maria: wa bakhour wa sa'a'id. Shere ne Maria: wa ayat wa shawahid. Shere ne Maria: 'anki yatanabba'oun.\n\n(24/23) Shere ne Maria: wa gamee' ma wada'ouh. Shere ne Maria: fil-qubba wagadouh. Shere ne Maria: wa li-qudsiki dhakarouh. Shere ne Maria: 'adhra' bikr masoun.\n\n(24/24) Shere ne Maria: lazim natragak. Shere ne Maria: 'ind el-Ab 'asak. Shere ne Maria: ya Maryam toubak. Shere ne Maria: tura'eena bi-'uyoun."],
  [["kiahk-midnight-hymn-59"], "Ta'alou ayyuha el-mu'mineen, li-nusabbih el-Maseeh wa numaggid walidat el-Ilah Maryam el-'Adhra'.\n\nKull ahad yukarrim el-'afeefa en-naqiyya umm malik el-magd Maryam el-'Adhra'.\n\nSa'ir el-maratib el-'ulwiyya was-sufouf en-nouraniyya wat-tuqous el-mala'ikiyya, irtafa'ti giddan akthar minhum ya Maryam el-'Adhra'. Fa-inna el-murattil Dawoud yasrukh bi-qeetharatihi fi mushaf el-mazameer, el-hasan fit-tarteel, hakadha qa'ilan: qamat el-malika 'an yameen el-malik bi-libas el-magd wad-diya'.\n\nWa yaqoul aydan: isma'i ya ibnati wa asghi bi-sam'iki, wansay sha'baki wa bayt abeeki, fa-inna el-malik ishtaha husnaki, li-annahu huwa rabbuki, wa huwa ya'ti wa yahillu feeki. Yasou' ilahuna el-haqeeqi alladhi ata wa tagassad li-agl khalasina. Tagassad min er-Rouh el-Qudus wa min Maryam el-'Adhra' el-'arous en-naqiyya.\n\nEs-salam li-Maryam umm 'Immanu'eel. Es-salam laki ya Maryam khalas abeena Adam. Es-salam laki ya Maryam umm malga'ina. Es-salam laki ya Maryam farah Hawwa'. Es-salam laki ya Maryam farah el-agyal. Es-salam laki ya Maryam farah Habeel es-siddeeq.\n\nEs-salam laki ya Maryam el-'Adhra' el-haqeeqiyya. Es-salam laki ya Maryam khalas Nouh. Es-salam laki ya Maryam el-ghayr danisa el-hadi'a. Es-salam laki ya Maryam ni'mat Ibraheem. Es-salam laki ya Maryam el-ikleel el-ghayr mudmahill. Es-salam laki ya Maryam khalas Ishaq et-tahir.\n\nEs-salam laki ya Maryam umm el-Quddous. Es-salam laki ya Maryam bi-tahleel Ya'qoub. Es-salam laki ya Maryam rabawat ad'af. Es-salam laki ya Maryam fakhr Yahouza. Es-salam laki ya Maryam umm es-Sayyid. Es-salam laki ya Maryam bisharat Mousa. Es-salam laki ya Maryam umm el-malik.\n\nEs-salam laki ya Maryam karamat en-nabi Samou'eel. Es-salam laki ya Maryam fakhr Isra'eel. Es-salam laki ya Maryam thabat Ayyoub es-siddeeq. Es-salam laki ya Maryam el-hagar el-kareem. Es-salam laki ya Maryam umm el-habeeb. Es-salam laki ya Maryam ibnat el-malik Dawoud.\n\nEs-salam laki ya Maryam sadeeqat Sulayman. Es-salam laki ya Maryam rif'at es-siddeeqeen. Es-salam laki ya Maryam khalas Isha'ya. Es-salam laki ya Maryam shifa' Armiya. Es-salam laki ya Maryam ma'rifat Hizqiyal. Es-salam laki ya Maryam ni'mat Danyal.\n\nEs-salam laki ya Maryam quwwat Eliyas. Es-salam laki ya Maryam ni'mat Aleesha'. Es-salam laki ya Maryam walidat el-Ilah. Es-salam laki ya Maryam umm Yasou' el-Maseeh. Es-salam laki ya Maryam el-hamama el-hasana. Es-salam laki ya Maryam umm Ibn Allah.\n\nEs-salam laki ya Maryam alladheena shahidou 'anha el-anbiya' qa'ileen: hou dha Allah el-Kalima ata wa tagassad minki bi-wahdaniyya la yuntaq bi-mithliha. Habalti wa waladti el-Kalima el-azali bi-ghayr ikhtilat wala imtizag, ayyatuha el-mamlou'a magdan.\n\nMan hiya el-'asa illa Maryam, li-annaha mithal batouliyyatiha. Habalat bil-ghayr manzour wa Ibn el-'Aliyy el-Kalima el-azali. Utlubi ila ibniki el-habeeb li-kay yun'im lana bi-ghufran khatayana. Ameen."],
  [["kiahk-midnight-hymn-60"], "(15/1) Rashi ō Maria: biki asbah Adam / Rashi ō Maria: ba'd an kan nadim / Rashi ō Maria: kan mukhalif wa athim / Rashi ō Maria: faz wa akhza el-arkhōn\n\n(15/2) Rashi ō Maria: ya farah Habeel / Rashi ō Maria: wa tag Isra'eel / Rashi ō Maria: u'teeti et-tahleel / Rashi ō Maria: bi-gamee' man yamdahoun\n\n(15/3) Rashi ō Maria: ya ni'mat Ibraheem / Rashi ō Maria: hou dha Ishaq saleem / Rashi ō Maria: Ya'qoub kan za'eem / Rashi ō Maria: ga'ahu Yousef wa ra'ah bi-'uyoun\n\n(15/4) Rashi ō Maria: Dawoud rattal wa qal / Rashi ō Maria: feeki sharah aqwal / Rashi ō Maria: wa aydan fil-amthal / Rashi ō Maria: hikmat Solomon\n\n(15/5) Rashi ō Maria: anti el-kursi el-mashrouh / Rashi ō Maria: shibh safeenat Nouh / Rashi ō Maria: zahrat 'itr tafouh / Rashi ō Maria: wa aghsan ez-zaytoun\n\n(15/6) Rashi ō Maria: markabat esh-Sharoubeem / Rashi ō Maria: agnihat es-Sarafeem / Rashi ō Maria: ya ibnat Yowaqeem / Rashi ō Maria: shouriyya ma'a Haroun\n\n(15/7) Rashi ō Maria: anti ni'mat Butrus / Rashi ō Maria: ya hikmat Boulus / Rashi ō Maria: ya farhat Filbus / Rashi ō Maria: tuhr el-mu'tarifeen\n\n(15/8) Rashi ō Maria: ya khalas Matiyas / Rashi ō Maria: wa amanat Toumas / Rashi ō Maria: ya quds el-aqdas / Rashi ō Maria: anti ghayrat Sim'an\n\n(15/9) Rashi ō Maria: ikleel esh-shuhada' / Rashi ō Maria: biki el-farah bada' / Rashi ō Maria: qaharti el-a'da' / Rashi ō Maria: wa akhzayti el-arkhōn\n\n(15/10) Rashi ō Maria: ya umm el-mawloud / Rashi ō Maria: nasl el-ab Dawoud / Rashi ō Maria: kammalti el-maqsoud / Rashi ō Maria: anti qal'a bi-husoun\n\n(15/11) Rashi ō Maria: min ba'd ma waladteeh / Rashi ō Maria: 'ala katfiki hamalteeh / Rashi ō Maria: tifl wa arda'teeh / Rashi ō Maria: kayfa hadha el-amr bi-hawn\n\n(15/12) Rashi ō Maria: hadha sirr maktoum / Rashi ō Maria: 'an el-kawn el-marsoum / Rashi ō Maria: sirr sar mafhoum / Rashi ō Maria: ba'd an kan maknoun\n\n(15/13) Rashi ō Maria: man huwa sahib el-afkar / Rashi ō Maria: yafhas hadhihi el-asrar / Rashi ō Maria: hadha nour min nour / Rashi ō Maria: la tudrikuhu zunoun\n\n(15/14) Rashi ō Maria: wa in qultu inni ahweeh / Rashi ō Maria: wa ba'd ma'aneeh / Rashi ō Maria: ma aqdar arweeh / Rashi ō Maria: lil-'ali wad-doun\n\n(15/15) Rashi ō Maria: wa in qal en-nazim / Rashi ō Maria: wasf sharafiki qa'im / Rashi ō Maria: lakin bi-'aza'im / Rashi ō Maria: minki muttasiloun"],
  [["kiahk-midnight-hymn-61"], "Ya M-R-Y-M / ya sitt el-abkar / qad nilti ta'zeem / min nour el-anwar / wa wuhibti ta'zeem / min 'indihi qad sar / wa hamalti el-khaliq / man dha la yahtar\n\nQad sirti u'gouba / lir-ru'asa' amthal / durra mahgouba / wa fil-Ingeel qad qal / yu'tounaki et-touba / fi kull el-agyal / ya ibnat Yowaqeem / qad futti esh-Sharoubeem\n\nMan nal ma nilti / ya umm er-rahma / wa anti qad sirti / mamlou'a ni'ma / wa lil-lahout sirti / higaban lil-Kalima / wahtar feeki / arbab et-tafheem\n\nYa tabout el-'ahd / ya migmarat Haroun / ya rouh el-magd / ya ibnat Sahyoun / ya nour el-'uyoun / beeki nas'ad / wa nahza bin-na'eem / ya mamlou'a ni'ma\n\nYa mamlou'a ni'ma / anti el-hisn el-haseen / anti kanz er-rahma / ya 'awn el-masakeen / bi-ibniki zalat en-niqma / ya shafee'at el-qiddiseen / shafee'atuna fiz-zahma / ya umm er-raheem\n\nNuqaddim laki et-ta'zeem / ya sitt el-abkar / ya ibnat Yowaqeem / ya kursi mukhtar / wal-mawloud minki kareem / azal 'anna el-'ar / el-Ilah el-'azeem / khaliq el-adhar\n\nYa zayn el-at-har / ya quds el-ahbar / ya tuhr el-at-har / ya nour el-anwar / ya kanz en-ni'ma / ya umm er-rahma / anti hiya el-karma / el-mamlou'a athmar\n\nYa ibnat Yowaqeem / qad nilti et-ta'zeem / anti hiya Urushaleem / dhat el-magd wal-fakhar / anti hiya Sahyoun / ya gawhara maknoun / fakakti el-masgoun / min yad el-makkar\n\nIbnuki khallas Adam / el-khati' en-nadim / wa 'ataq el-'alam / min kull el-adrar / rabbuki min sigharik / lamma ra'a tuhrak / qad tayyab dhikrak / fi kull el-aqtar\n\nArsal laki Ghubriyal / bi-muhkam el-aqwal / wa bashsharaki idh qal / Allah laki ikhtar / rouh qudsihi malak / wa sakan fi ahsha'ik / ya 'Adhra' toubak / fi kull el-a'sar\n\nInna ghayr el-mahsous / er-Rabb el-quddous / minki ata wa du'iya Iēsous / wa nazarathu el-absar / Mousa ra'a el-'awsag / wan-nar feehi tata'aggag / wa aghsanuhu tatawahhag / ma darrathu en-nar\n\nInna ma ra'athu el-'aynan / multahiban bin-neeran / fil-'awsag wal-aghsan / hiya Maryam zeenat el-abkar / wan-nar hiya Iēsous / er-Rabb el-quddous / mu'teena en-namous / maktouban fil-ahgar\n\nFi Isha'ya qad qeel / 'an hadha et-ta'weel / talid 'Immanu'eel / el-malik el-gabbar / Hizqiyal ra'a bab / dakhal feehi Rabb el-arbab / wa khatam el-bab muhab / 'ali el-miqdar\n\n'Alin huwa qadruki / li-anna Yasou' ibnaki / lamma wulida minki / tazayyanat el-amsar / aydan Danyal / tanabba' haythu qal / ra'aytu el-kursi el-'al / 'ali el-miqdar\n\nNazartu fawq el-arkan / shibh Ibn el-insan / wa lahu es-sultan / 'ala kull el-aqtar / wa huwa Rabb el-quwwat / wa min hawlihi tughmat / ulouf wa rabawat / min 'izam wa waqar\n\nYa ibnat Yowaqeem / futti el-Karoubeem / aydan es-Sarafeem / wa kull el-aba' el-abrar / minki ga' el-mawloud / er-Rabb el-ma'boud / yamdah feeki Dawoud / bil-'ashara awtar\n\nEl-watar el-awwal / qawl mubaggal / wal-'Adhra' tahbal / bil-malik el-gabbar / wal-watar eth-thani / Dawoud fit-tahani / yurattil bil-alhan / ma'a darb el-qeethar\n\nWath-thalith ya ibna / anti mu'tamana / bin-nour mushtamila / war-Rabb laki ikhtar / el-watar er-rabi' / asghi ya sami' / dha qawlan sha'i' / fi kull el-aqtar\n\nWal-khamis khabbar / hamama hiya tazhar / bidh-dhahab el-asfar / 'ala mankibayha sar / was-sadis qal feeh / qawlan ma ukhfeeh / lakinni arweeh / wa ash-huruhu aghar\n\nWas-sabi' idh qal / ya gabal Allah el-'al / tagassad minki el-muta'al / bila shakk wala inkar / wath-thamin rannam / lil-'Adhra' Maryam / ikhtaraha el-mu'azzam / kallalaha bil-fakhar\n\nEt-tasi' qal 'anha / yazhar haqqan minha / el-Ilah wa huwa ibnuha / wal-bakouriyya fi hifz wa waqar / el-watar el-'ashir / Allah el-qadir / fi Sahyoun zahir / maskan el-abrar\n\nLam yougad fid-dahr / mithluki ayyatuha el-bikr / li-annaki fakakti el-asr / 'an Adam wal-'ar / ya sayyidat el-akwan / ya fakhr el-iman / ana 'abduki hayran / ghariq fil-awzar\n\n'Alin huwa qadruki / la tatruki 'abdaki / qasdi min waladiki / tawba wastighfar / wal-'Adhra' tashfa' / fil-huddar agma' / wa hiya 'anna tadfa' / darabat el-ashrar\n\nQoum wanhad ya miskeen / walbas thawb el-yaqeen / wa qoul ameen ameen / fa-hiya tashfa' fil-hadireen / wa ana el-khati' el-miskeen / madihuha fi kull heen / mali yawm ed-deen / siwa sayyidat el-abkar"],
  [["kiahk-midnight-hymn-62"], "(56/1) Ya ibnat Dawoud, kam man kan qadeem, ga' bashshar bi-wroud, ibniki fil-'alam.\n\n(56/2) Kam man kan mawgoud, fi hubbiki hayim, kam amthal kam aqwal, wa nubouwat mawsoufi.\n\n(56/3) Ya baban maqfoul, ra'ahu Hizqiyal, fil-mashriq mashmoul, bin-nour el-muta'al.\n\n(56/4) Qal 'adhra' wa batoul, fi 'aqib el-agyal, satada' man khada'at, lahu rabawat wa uloufi.\n\n(56/5) Ya tabout el-'ahd, bidh-dhahab el-matli, madhuki mithl esh-shahd, wa asnaf el-'asali.\n\n(56/6) Wa bi-ibniki Iblees inhadd, min ba'd el-hiyali, wa biki itma'anna, min ba'd el-khawfi.\n\n(56/7) Ya gabal Allah surr, bihi Yasou' sayyiduna, wa waladteehi wa zahar, min Iblees 'ataqna.\n\n(56/8) Min ghayr zar' bashar, hatta khallasna, wa ta'allam sayyiduna, 'an sha'bihi youfi.\n\n(56/9) Ya huqq el-'anbar, ra'ihat teebihi fah, sayyiduna dabbar, wa hamalteehi bi-afrah.\n\n(56/10) Wa waladteehi wa zahar, nagmuhu fil-isbah, wa wudi' fi madhwad, bi-khiraq malfoufi.\n\n(56/11) Ya khashaban la yasous, wa qabilti el-bushra, wa hamalti el-Quddous, wa anti hiya 'adhra'.\n\n(56/12) Wa raga'na el-firdaws, bi-ibniki dafa'tan ukhra, wa biki itma'anna, min ba'd el-khawfi.\n\n(56/13) Ya dhukhr el-milla, wa ashab et-tarteel, nazarouki mushtamila, bi-shumous wa tahleel.\n\n(56/14) Wa kawakib gumla, fawq ra'siki ikleel, man yaqdir yantiq, aw yasma' wa yashoufi.\n\n(56/15) Ya ru'ya wa nudhour, andharaki Habaqouq, ibnuki nour min nour, khaliq ghayr makhlouq.\n\n(56/16) Fil-Ingeel mash-hour, bil-qawl el-mawthouq, magdi fi abi, wa magd abi huwa fiyya.\n\n(56/17) Ya zahrat el-atyab, taq er-Rabb laha, ya madeena wa higab, war-Rabb dakhilaha.\n\n(56/18) Markaba lil-Ibn, wan-nour shamilaha, ibnuki huwa en-nour, wa bil-Ab muttahidi.\n\n(56/19) Ya sullam marfou', ra'ahu el-ab Ya'qoub, min fawqihi mawdou', rouh Allah el-marhoub.\n\n(56/20) Qal \"er-Rabb Yasou', fil-'Adhra' mahgoub, mutahannin 'alim, raheeman wa ra'oufi.\"\n\n(56/21) Ya shouriyyat dhahab, feeha gamr en-nar, wa anti hiya aydan, misbah el-anwar.\n\n(56/22) Biki kull er-rida, fazou min el-adrar, wa biki itma'anna, min ba'd el-khawfi.\n\n(56/23) Ya Sahyoun anti, maskan haqqani, bikr wa hamalti, min ghayr insani.\n\n(56/24) Haqqan wa wada'ti, kawkab nourani, sar el-'alam fi, nourihi makshoufi.\n\n(56/25) Ya diya' wa baha', ya gawhar maknoun, Dawoud 'anki anba', fil-mazmour bi-fanoun.\n\n(56/26) Ilah el-aliha, yazhar fi Sahyoun, wa qad akmal ma qeel, min agliki bi-wsoufi.\n\n(56/27) Ya toubaniyya, sirti umm el-Quddous, amdahuki bi-'inaya, bi-nizamin makhsous.\n\n(56/28) Azharaki Isha'ya, wa tanabba' 'Amous, bi-hulul rouh Allah, fil-hasha wal-gawfi.\n\n(56/29) Ya daw' el-firdaws, ya quwwat Shamshoun, ra'aki Meekha'us, wa tanabba' Nahoum.\n\n(56/30) Surr Sofonias, wa andharana bi-'ouloum, qal Allah yanzil, ka-matar fawq soufi.\n\n(56/31) Ya 'ukkaz Haroun, min ghayr ma' farra', bi-awraq wa ghusoun, feehi wa lam tuzra'.\n\n(56/32) Ya haykal Sahyoun, minki er-Rabb asra', nazal sayyiduna, li-yuzeel el-khawfi.\n\n(56/33) Ya ghusn el-'awsag, wa mutawwag bin-nour, ra'ahu Mousa tawahhag, min fawq gabal et-Tour.\n\n(56/34) Fa-ma ahsan wa abhag, dha el-amr el-mash-hour, sha' ismuki fi kull el-'alam bi-wsoufi.\n\n(56/35) Ya fisqiyyat ma', bi-alwah marmar, sammaki el-'ulama', kanzan min gawhar.\n\n(56/36) Sirran munkatiman, sar minki mag-har, bil-gasad el-mukhtar, bihi el-mayyit 'oufi.\n\n(56/37) Ya qubbat Mousa, sammaki el-ahbar, karma maghrousa, hamilat el-athmar.\n\n(56/38) Bikr wa 'arous, min nasl el-at-har, khidr bi-ghayr fasad, lil-'arees mawsoufi.\n\n(56/39) Ya kursi 'al, fawqahu er-Rabb muqeem, ra'ahu Danyal, fawq esh-Sharoubeem.\n\n(56/40) Wa lamma shafahu qal, laki kull et-ta'zeem, ya 'Adhra' magduki, 'ali mawsoufi.\n\n(56/41) Ya lawhan maktoub, wa simat en-ni'ma, ashraq shams el-'adl, minki fiz-zulma.\n\n(56/42) Wa fi ahsha'iki hall, rouh Allah el-Kalima, ba'd an kan 'anna, bi-waghihi masroufi.\n\n(56/43) Ya ma'ida min nour, wa ta'am rouhani, khallasana bi-surour, min batniki insani.\n\n(56/44) Ga' wa abtal esh-shurour, wa kayd esh-shaytani, wa a'tana gasadahu, wa damahu el-mawsoufi.\n\n(56/45) Ya nagma tudawwi, waqt es-subhiyya, quds el-qiddiseen, zahra 'itriyya.\n\n(56/46) Wa anti hiya misbah, deen el-orthodoksiyya, wa biki itma'anna, min ba'd el-khawfi.\n\n(56/47) Ya haykal tahir, li-hulul el-lahout, minki sar zahir, ismuhu bin-nasout.\n\n(56/48) Wa huwa qadir qahir, wahid min eth-thalouth, tusabbih lahu kull, er-rabawat wal-uloufi.\n\n(56/49) Ya wi'a' el-asrar, min dhahab safi, wal-mann el-mukhtar, fi wastihi makhfi.\n\n(56/50) Raga' Adam lid-dar, ba'd an kan manfi, Hawwa' hiya aghwathu, wa biki qad 'oufi.\n\n(56/51) Ya labisat el-haybat, tawwahti el-'uqqal, kam nasabou nubouwat, kam bi-ahwal wa aqwal.\n\n(56/52) Kam ra'ou ru'yat, kam darabou amthal, kam tahayyar feeki, mu'allim ma'loufi.\n\n(56/53) Ya yanbou' esh-shuhada', anba' bil-qudra, baqeeti min ba'd, meeladiki 'adhra'.\n\n(56/54) Wa ihna ma'a Abou es-Sa'd, ahwalna 'ibra, wa fi Maryam hayya'na, mada'ih mawsoufa.\n\n(56/55) Wa salami ila el-'Adhra', el-batoul zayn el-abkar, umm ilah el-qudra, Yasou' 'alim el-asrar.\n\n(56/56) Wa salami ila el-'Adhra', fi sirri wal-ighar, man yamdahuha shatra, tashfa' feehi uloufi."],
  [["kiahk-midnight-hymn-64"], "Lisani el-ba'is wal-khati' la yastatee' an yantiq bi-karamat Maryam.\n\nLakinni as'al tahannun ilahina an yamnahani mantiqan wa hikma sama'iyya.\n\nLi-kay abtadi' bi-gasara wa aqoul guz'an yaseeran min mada'iha, mutayaqqinan minha an tusa'idani fil-qawl, li-kay amdahaha hakadha qa'ilan: ifrahi ya Maryam ya fakhr ginsina wa shafee'at el-mu'mineen. Ifrahi ya man nashalti abana Adam min hafwat el-khatiyya.\n\nIfrahi ya man khallasti Hawwa' min talaqat el-mawt. Ifrahi ya man ta'lou 'ala el-mala'ika min agl taharatiha. Ifrahi ya man sarat maskanan li-Rabb el-quwwat. Ifrahi ya kawkaban ashraq diya'uhu 'ala kawakib es-sama'.\n\nIfrahi ya man sar min qibaliha kull el-afrah el-ilahiyya. Ifrahi ya 'arous bila 'arees. Ifrahi ya man waladat alladhi tarta'id lahu sufouf el-mala'ika. Ifrahi ya man sarat mahallan li-hikmat el-hukama' wa anarat 'uqoul el-mu'mineen.\n\nIfrahi ya man qabilat ilayha el-bishara et-tahira el-mala'ikiyya, bi-hulul Ibn Allah fi ahsha'iha, el-Kalima el-azali alladhi tagassad wa wulida li-agl khalasina. Ifrahi ya man shafa'atuha maqbula 'ind er-Rabb fi gins el-bashar.\n\nIfrahi ayyatuha el-ard hamilat et-teeb, ma'din er-ra'fa. Ifrahi ayyatuha el-ma'ida hamilat surour el-ghufran. Ifrahi ya man sar ilayna min qibaliha el-wusoul lil-malakout. Nas'aluki udhkureena 'ind ibniki el-habeeb li-yaghfir lana khatayana. Ameen."],
  [["kiahk-midnight-hymn-65"], "(24/1) Usabbih bi-quwwa / li-rabbi Yasou' el-Maseeh / Rabb el-quwwat / istawgabti.\n\n(24/2) Kull ahad yaqoul / ya Maryam el-mubaraka / du'eeti sadeeqa / istawgabti.\n\n(24/3) Li-annaki el-qubba / allati sana'aha Mousa / bi-'izam karama / istawgabti.\n\n(24/4) El-khaliq huwa / alladhi ikhtaraha / ilah es-sama' / bi-yadayhi khalaqaha.\n\n(24/5) Min agl hadha / bada' Dawoud bi-arghanih / wa takallam min agliha / er-Rabb ikhtar Sahyoun.\n\n(24/6) Zakariyya nazar / el-qiddeesa Maryam / fi dhalika ez-zaman / mithl el-manara.\n\n(24/7) Isha'ya qal / bi-qalbin mutahallil / 'an el-'Adhra' / umm 'Immanu'eel.\n\n(24/8) Allati tud'a / el-ina' / wal-qist / wal-ghita'.\n\n(24/9) Urushaleem es-sama'iyya / madeenat el-abrar / anti akthar min es-sama' / ya Maryam bil-haqeeqa.\n\n(24/10) Wa kash-Sharoubeem / murtafi'a giddan / wa afdal min es-Sarafeem / bil-ulouf.\n\n(24/11) Wa aydan el-migmara / hamilat el-gamr / Maryam allati shahid / en-nabi min agliha.\n\n(24/12) Maryam walidat el-Ilah / el-hamila gamr / el-lahout / li-annaki istawgabti.\n\n(24/13) Man yaqdir yantiq / bi-karamat el-batoul / allati hamalat Allah fi batniha / istawgabti.\n\n(24/14) Murtafi'a giddan / akthar min / el-mala'ika / li-annaki sirti lana el-yawm / istawgabti.\n\n(24/15) El-qubba el-oula / fil-'aql ed-dakhil / wal-qubba eth-thaniya / Allah dakhilaha.\n\n(24/16) Khubz el-hayah / alladhi kharag minki / alladhi a'tana el-hayah / huwa el-mukhallis.\n\n(24/17) Kull el-asma' el-'aliya / el-ghayr el-mutagassideen / lam yablughou 'ulou / toubaniyyatik.\n\n(24/18) Du'eeti ayyatuha / el-'arous en-naqiyya / Maryam el-malika umm Ibn Allah / istawgabti.\n\n(24/19) Hina'idhin bil-haqeeqa / Allah arsal / kalimatahu dakhilaha / istawgabti.\n\n(24/20) Ibn Allah el-ka'in / qabl ed-duhour / er-Rabb el-azali / ata wa khallasana.\n\n(24/21) Li-annahu yaleeq biki / an yud'a ismuki / el-qist edh-dhahab / istawgabti.\n\n(24/22) Es-salam laki ya Maryam / el-hamama el-hasana / el-mamlou'a baraka / istawgabti.\n\n(24/23) Ya Allah farriq / baqiyyat khatayaya / wa baqiyyat a'mali / ya Rabb ighfir lana.\n\n(24/24) Ta'anna ya ilahi / 'ala 'abdik / waghfir li khatayaya / ya Rabb ighfir li."],
  [["kiahk-midnight-hymn-66"], "(33/1) Amdah fil-batoul / wa ashrah 'anha wa aqoul / anti asl el-usoul / ya gawhar maknoun\n\n(33/2) Bi-ibniki ya sittana / khalas ginsina / wa ballaghna el-muna / wa biki sirna farihoun\n\n(33/3) Tagassad bi-thabat / min sitt el-banat / sulib 'anna wa mat / 'ind el-Aqraniyoun\n\n(33/4) Thamarat 'arbouni / ya ibnat Sahyoun / uhibb ilahi / wa aseeh wa aqoul\n\n(33/5) Gaki Ghubriyal / bi-basha'ir wa aqwal / wa qabilti ma qal / bi-sirr khafi maknoun\n\n(33/6) Hall bi-kalimatih / wa sharah qudratih / sirti ka-sama'ih / ya ibnat Sahyoun\n\n(33/7) (Qarar) Sabani hubbik / ya fakhr er-rutab / Mousa ra'aki ya Maryam / 'agab min 'agab / wal-qanadeel fidda bitdawwi / was-sulban dhahab / ya qubbat Mousa ya Maryam / ya shouriyyat Haroun\n\n(33/8) Khallas Adam / ba'd an kan nadim / wa 'ataq el-'alam / wa nahnu biki farihoun\n\n(33/9) Da'im tamgeeduh / wa 'ahad talameedhuh / yukhallis 'abeeduh / min kayd el-arkhōn\n\n(33/10) Dawoud qal 'anki / el-malik ishtaha husnaki / wa tagassad minki / Rabb el-'arsh el-maknoun\n\n(33/11) Rabawat wa ulouf / hawl el-'arsh wuqouf / tughmat wa sufouf / wa shuhada' muttasiloun\n\n(33/12) Zalat 'anna el-ahzan / wa sirna fi itmi'nan / biki ya Maryam / ya fakhr el-bashariyyoun\n\n(33/13) Salome shahidat / inna el-'Adhra' waladat / amanat wa'taqadat / bis-sirr el-maknoun\n\n(33/14) (Qarar) Sabani hubbik / ya fakhr er-rutab / Mousa ra'aki ya Maryam / 'agab min 'agab / wal-qanadeel fidda bitdawwi / was-sulban dhahab / ya qubbat Mousa ya Maryam / ya shouriyyat Haroun\n\n(33/15) Sulayman abouki / sar yunshid bi-fanoun / wa Ya'qoub ra'aki / sullam murtafi'oun\n\n(33/16) Shahid 'anki er-ru'asa' / ya karma maghrousa / ya bikra wa 'arousa / kama 'anki tanabba'oun\n\n(33/17) Sofonias khabbar / bi-anna Yasou' yazhar / shibh nada wa matar / wal-khatm hisn masoun\n\n(33/18) Dallalat Hawwa' Adam / wa sar yabki nadim / kharag 'iryan 'adim / lawlaki ma rag'oun\n\n(33/19) 'Alin huwa qadruki / wa 'azeemun huwa magduki / wa Allah sharraf dhikraki / ya shouriyyat Haroun\n\n(33/20) Ghalab feeki el-maddah / ya bad' el-afrah / bi-madeehiki yartah / kull dhaleel mahzoun\n\n(33/21) (Qarar) Sabani hubbik / ya fakhr er-rutab / Mousa ra'aki ya Maryam / 'agab min 'agab / wal-qanadeel fidda bitdawwi / was-sulban dhahab / ya qubbat Mousa ya Maryam / ya shouriyyat Haroun\n\n(33/22) Feeki rida qalbi / ya Maryam talabi / Yasou' ibnuki hasbi / bi-quwwatihi akoun\n\n(33/23) Qadeem azali da'im / sulib 'anna wa ta'allam / istayqaz kan-na'im / wat-talameedh yakrizoun\n\n(33/24) Karazou fil-aqtar / er-rusul el-abrar / wa nadou bistibshar / el-aba' el-Ingeeliyyoun\n\n(33/25) Laki kull et-ta'zeem / ya ibnat Yowaqeem / hamalti sirran 'azeem / wa wada'ti el-maknoun\n\n(33/26) Mousa wa Danyal / darabou 'anki amthal / wa qabilti ma qal / bi-sirr khafi maknoun\n\n(33/27) Nawwarti el-akwan / ya fakhr el-iman / lawlaki ma kan / kull el-khala'iq yu'taqoun\n\n(33/28) (Qarar) Sabani hubbik / ya fakhr er-rutab / Mousa ra'aki ya Maryam / 'agab min 'agab / wal-qanadeel fidda bitdawwi / was-sulban dhahab / ya qubbat Mousa ya Maryam / ya shouriyyat Haroun\n\n(33/29) Hadaya bi-iman / atou biha el-a'yan / murran wa dhahaban wa luban / biha el-magous hamiloun\n\n(33/30) Wa sagadou lil-mawloud / er-Rabb el-ma'boud / wa Heeroudus sar mar'oub / wa gunduhu muhtaroun\n\n(33/31) La tansay fi dhalika el-heen / 'abdan khati' miskeen / shafa'atiki yawm ed-deen / li-sha'b ibniki agma'oun\n\n(33/32) Wa nas'al min goudihi el-ghufran / wa tawba ma'a iman / li-naseer fi itmi'nan / nahnu el-mu'mineen\n\n(33/33) (Qarar) Sabani hubbik / ya fakhr er-rutab / Mousa ra'aki ya Maryam / 'agab min 'agab / wal-qanadeel fidda bitdawwi / was-sulban dhahab / ya qubbat Mousa ya Maryam / ya shouriyyat Haroun"],
  [["kiahk-midnight-hymn-67"], "Anti mustahiqqa, akthar min gamee' el-qiddiseen, an tatlubi 'anna, ayyatuha el-mumtali'a ni'ma.\n\nAnti murtafi'a giddan, akthar min ru'asa' el-aba', wa mukarrama afdal, min el-anbiya'.\n\nWa laki sa'yun, bi-dalla, akthar min esh-Sharoubeem, wa es-Sarafeem.\n\nLi-annaki anti bil-haqeeqa, fakhr ginsina, wa shafee'at, nufousina.\n\nIshfa'i feena, amam mukhallisina, li-kay yuthabbitna, fil-iman el-mustaqeem.\n\nWa yun'im lana, bi-maghfirat khatayana, li-nafouz bi-rahma, bi-shafa'atik."],
  [["kiahk-midnight-hymn-68"], "Kull el-asma' el-'aliya, allati li-ghayr el-mutagassideen, ulouf el-mala'ika, wa ru'asa' el-mala'ika.\n\nLam yablughou, 'azamat toubawiyyatik, ayyatuha el-mushtamila, bi-magd Rabb el-gunoud.\n\nAnti mudee'a, akthar min esh-shams, wa lami'a akthar, min esh-Sharoubeem.\n\nWa es-Sarafeem, dhawi es-sitta el-agniha, yurafrifouna 'alayki, bi-tahleel."],
  [["kiahk-midnight-hymn-69"], "Magduki ya Maryam, arfa' min es-sama', wa anti akram min el-ard, wa sukkaniha.\n\nLi-annaki anti bil-haqeeqa, et-tareeq el-haqeeqi, el-mu'addi, ila es-samawat.\n\nLabisti el-farah, wat-tahleel, wa tamantaqti bil-quwwa, ya ibnat Sahyoun.\n\nYa man labisti, libas es-sama'iyyeen, hatta satarti Adam, bi-libas en-ni'ma.\n\nWa radadtihi marratan ukhra, ila el-firdaws, mawdi' el-farah, wa maskan es-siddeeqeen."],
  [["kiahk-midnight-hymn-70"], "Qubba haqeeqiyya, hiya Maryam el-'Adhra', mawdou' fi wastiha, esh-shahadat es-sadiqa.\n\nEt-tabout el-ghayr ed-danis, el-musaffah bidh-dhahab, min kull nahiya, wal-ghita' el-Karoubi.\n\nEl-qist edh-dhahabi, el-makhfi feehi el-mann, hou dha Kalimat el-Ab, ata wa tagassad minki.\n\nEl-manara edh-dhahabiyya, el-hamila en-nour el-haqeeqi, alladhi huwa nour el-'alam, alladhi la yudna minh.\n\nEl-migmara edh-dhahabiyya, el-hamila gamr en-nar, wal-bakhour el-mukhtar, el-'anbari.\n\n'Asa Haroun, allati azharat, waz-zahra el-muqaddasa, allati lil-bakhour.\n\nHadhihi gamee'uha ma'an, tadulluna 'ala, wiladatiki el-'ageeba, ya Maryam el-'Adhra'."],
  [["kiahk-midnight-hymn-71"], "Zayyanta nufousana, ya Mousa en-nabi, bi-karamat el-qubba, allati zayyantaha.\n\nEl-qubba el-oula, allati sana'aha Mousa, mawdi' maghfirat khataya, banee Isra'eel.\n\nSana'aha bi-magd, ka-qawl er-Rabb, wa ka-gamee' el-muthul, allati a'lamahu biha.\n\nKan fil-qubba, tabout musaffah, bidh-dhahab min dakhil, wa min kharig.\n\nKan fil-qubba, ghita', wa Karouba dhahab, yuzallilan 'alayh.\n\nKan fil-qubba, qist dhahabi, wa kayl mann, makhfi feeh.\n\nKan fil-qubba, manara min dhahab, wa sab'at surug, tudee' 'alayha.\n\nKan fil-qubba, migmara min dhahab, wal-'oud el-mukhtar, fi wastiha.\n\nKan fil-qubba, zahrat bakhour, yastanshiq ra'ihataha, gamee' Al bayt Isra'eel.\n\nKan fil-qubba, 'asa Haroun, hadhihi allati azharat, bi-ghayr ghars wala saqy.\n\nKan fil-qubba, ma'ida dhahabiyya, wa khubz et-taqdima, mawdou'an 'alayha.\n\nKan fil-qubba, ra'ees kahana, yus'id edh-dhaba'ih, 'an khataya esh-sha'b.\n\nIdha ishtamm ra'ihataha, dabit el-kull, yarfa' hunalik, khataya esh-sha'b.\n\nMin qibal Maryam, ibnat Yowaqeem, 'arafna edh-dhabeeha el-haqeeqiyya, li-maghfirat el-khataya."],
  [["kiahk-midnight-hymn-73"], "(22/1) Da'a Rabb el-karm wakeelahu wa qal lah:\n\n(22/2) \"Ud'u el-fa'ala wa a'tihim el-ugra wabda' min el-akhireen ila el-awwaleen, deenaran li-kull wahid\" (Matta 20 : 8).\n\n(22/3) Man hum el-fa'ala illa ru'asa' el-aba' Ibraheem wa Ishaq wa Ya'qoub Isra'eel.\n\n(22/4) Man hum el-fa'ala illa el-anbiya' alladheena tanabba'ou min agl magee' el-Maseeh.\n\n(22/5) Man hum el-fa'ala illa el-atfal alladheena qatalahum Heeroudus min agl el-Maseeh.\n\n(22/6) Man hum el-fa'ala illa er-rusul alladheena bashsharou bi-qiyamat er-Rabb.\n\n(22/7) Man hum el-fa'ala illa esh-shuhada' alladheena safakou damahum min agl ism el-Maseeh.\n\n(22/8) Man hum el-fa'ala illa el-mu'tarifeen wa lubbas es-saleeb wa sukkan el-barari.\n\n(22/9) Man hum el-fa'ala illa el-'adhara el-hakeemat allati hafizna husn batouliyyatihinna.\n\n(22/10) Man hum el-fa'ala illa ru'asa' el-asaqifa alladheena yufassilouna kalimat el-haqq bistiqama.\n\n(22/11) Man hum el-fa'ala illa el-asaqifa alladheena yuqatilouna 'an el-amana el-orthodoksiyya.\n\n(22/12) Man hum el-fa'ala illa el-qamamisa mudabbiri el-bee'a.\n\n(22/13) Man hum el-fa'ala illa el-qusous alladheena yuqassimouna gasad el-Maseeh.\n\n(22/14) Man hum el-fa'ala illa ru'asa' esh-shamamisa alladheena yakhdimouna er-Rabb mithl Istefanous.\n\n(22/15) Man hum el-fa'ala illa esh-shamamisa alladheena yahmilouna ka's dam el-Maseeh.\n\n(22/16) Man hum el-fa'ala illa el-ipodiakoniyyoun alladheena ya'izouna el-'almaniyyeen.\n\n(22/17) Man hum el-fa'ala illa el-aghnostosiyyoun alladheena yaqra'ouna el-kutub mithl Dawoud.\n\n(22/18) Man hum el-fa'ala illa el-arakhina muhibbi el-Ilah alladheena yahtammouna bi-hagat el-kaneesa.\n\n(22/19) Man hum el-fa'ala illa el-khuta'ah alladheena (tabou) wa yarga'ouna ila er-Rabb bi-qalbin mustaqeem.\n\n(22/20) Man hum el-fa'ala illa el-ikhwa muhibbi el-Ilah alladheena ta'ibou ma'ana fi hadhihi el-absalmodiyya.\n\n(22/21) Ayyuha el-Maseeh mukhallisuna a'tihim ugratahum 'iwad at'abihim fi malakout es-samawat.\n\n(22/22) Bi-salawat alladheena dhakarna asma'ahum, ya Rabb an'im lana bi-ghufran khatayana."],
  [["kiahk-midnight-hymn-74"], "Ayyuha el-Maseeh mukhallisuna, a'tihim ugratahum, 'iwad at'abihim, fi malakout es-samawat."],
  [["kiahk-midnight-hymn-75"], "(16/1) Marahimuka ya ilahi / katheera giddan / marahimuka ya ilahi / la tuhsa laha 'adadan\n\n(16/2) Qatarat el-amtar / ma'douda bayn yadayk / wa aydan raml el-bihar / ka'in quddam 'aynayk\n\n(16/3) Kam bil-akthar / khatayaya wa athami quddamak / wa ma sana'athu yadaya / zahir kulluhu amamak\n\n(16/4) Khataya siba'i wa gahli / ya Rabb la tadhkurha / wala tata'ammal athami / ya ilahi bal utrukha\n\n(16/5) Fa-innaka la tasha' mawt el-khati' / bal tuhibb rugou'ahu ilayk / ya ilahi iqbal talabati / raga'tu wa tubtu ilayk\n\n(16/6) Fa-inna el-'ashshar ikhtartahu / waz-zaniya ghafarta laha / wal-liss ya Rabb dhakartahu / rahmatuka la nihaya laha\n\n(16/7) Wa ana khati' aydan / ya Rabb 'allimni / li-kay asna' tawba / mithl ez-zaniya iqbalni\n\n(16/8) Ruddana ila khalasik / fa-innaka salihun wa raheem / isna' ma'ana ka-salahik / innaka qadirun wa kareem\n\n(16/9) Wa in hakamtana bi-'adlik / fa-la nagid hugga / lakin nantazir fadlak / wa marahimaka natraga\n\n(16/10) Marahimuka ya ilahi / ta'lou kull el-ab'ad / marahimuka ya ilahi / kar-raml bi-ghayr 'adad\n\n(16/11) Marahimuka ya ilahi / akthar min 'adad en-nugoum / wa akthar min nabat el-ard / wal-gibal wa kull en-nugoum\n\n(16/12) Ya malik es-salam / salamaka a'tina / qarrir lana salamak / wa hill rouhaka feena\n\n(16/13) Farriq a'da' el-bee'a / wa hassinha bil-iman / bi-husoun 'aliya manee'a / fa-la tatazaz'a' li-zaman\n\n(16/14) 'Immanu'eel nafsuhu / ka'in fi wastina el-an / bi-magd abeehi wa rouh qudsih / el-an wa kull awan\n\n(16/15) Fal-yubarikna kulluna / wa yutahhir qouloubana / wa yashfi amradana / wa yukhallis nufousana\n\n(16/16) Nasgud lil-Ab wal-Ibn / war-Rouh el-Qudus / el-an wa kull awan / wa ila el-abad ameen"],
  [["kiahk-midnight-hymn-77"], "Marahimuka ya ilahi ghayr muhsah, marahimuka ya ilahi mithl el-amtar.\n\nMarahimuka ya ilahi katheera giddan. Marahimuka ya ilahi akthar min er-raml.\n\nMarahimuka ya ilahi ta'lou 'ala es-samawat. Marahimuka ya ilahi akthar min el-afkar.\n\nMarahimuka ya ilahi tafouq el-mala'ika. Marahimuka ya ilahi mithl el-galeed.\n\nMarahimuka ya ilahi akthar min el-ulouf. Marahimuka ya ilahi rabawat ad'af. Marahimuka ya ilahi mithl el-anwar. Marahimuka ya ilahi akthar min el-qatarat. Marahimuka ya ilahi akthar min en-nugoum. Marahimuka ya ilahi akthar min el-yanabee'. Marahimuka ya ilahi akthar min es-sahab. Marahimuka ya ilahi la yuhsa laha 'adadan.\n\nMarahimuka ya ilahi akthar min er-riyah. Marahimuka ya ilahi aqwa min el-'awasif. Marahimuka ya ilahi akthar min et-taba'i'. Marahimuka ya ilahi tafouq 'ala el-khaleeqa. Marahimuka ya ilahi akthar min nabat el-ard. Marahimuka ya ilahi akthar min el-andiya. Marahimuka ya ilahi akthar min el-amtar el-gariya. Marahimuka ya ilahi tughatti el-gibal el-'aliya.\n\nMarahimuka ya ilahi tuhyi el-arwah. Marahimuka ya ilahi ta'ti 'alayna bil-in'am. Marahimuka ya ilahi ta'oul el-bashar. Marahimuka ya ilahi tu'ti en-nagah lil-baha'im. Marahimuka ya ilahi fal-ta'ti 'alayna mithl abeena Adam wa ummina Hawwa'. Marahimuka ya ilahi fal-ta'ti 'alayna mithl Habeel es-siddeeq awwal esh-shuhada'. Marahimuka ya ilahi ta'ti 'alayna mithl Akhnoukh el-barr alladhi rafa'tahu ila es-sama' hayyan.\n\nMarahimuka ya ilahi ta'ti 'alayna mithl Nouh el-barr alladhi khallastahu min ma' et-toufan. Marahimuka ya ilahi ta'ti 'alayna mithl Malki-Sadaq malik Saleem. Marahimuka ya ilahi ta'ti 'alayna mithl Ibraheem wa Ishaq wa Ya'qoub. Marahimuka ya ilahi ta'ti 'alayna mithl sa'ir el-anbiya' el-at-har. Marahimuka ya ilahi ta'ti 'alayna mithl er-rusul el-qiddiseen.\n\nMarahimuka ya ilahi ta'ti 'alayna mithl esh-shuhada' alladheena safakou dima'ahum 'ala ism el-Maseeh. Marahimuka ya ilahi ta'ti 'alayna mithl sa'ir el-mu'tarifeen. Marahimuka ya ilahi ta'ti 'alayna mithl lubbas es-saleeb el-abrar es-saliheen. Marahimuka ya ilahi ta'ti 'alayna mithl en-nussak el-mugahideen. Marahimuka ya ilahi ta'ti 'alayna mithl es-suwwah el-'abideen.\n\nMarahimuka ya ilahi ta'ti 'alayna mithl el-'adhara el-hakeemat. Marahimuka ya ilahi ta'ti 'alayna mithl el-'ashshar alladhi qabiltahu ilayk. Marahimuka ya ilahi ta'ti 'alayna mithl el-khati'a allati ghafarta laha khatayaha. Marahimuka ya ilahi ta'ti 'alayna mithl el-liss alladhi sulib 'an yameenak. Marahimuka ya ilahi ta'ti 'alayna mithl ahl Neenawa alladheena tabou ilayk.\n\nMarahimuka ya ilahi ta'ti 'alayna mithl el-khuta'ah alladheena ghafarta lahum khatayahum. Marahimuka ya ilahi ta'ti 'alayna mithl el-'umyan alladheena fatahta lahum a'yunahum. Marahimuka ya ilahi ta'ti 'alayna mithl el-khurs alladheena atlaqta lahum alsinatahum. Marahimuka ya ilahi ta'ti 'alayna mithl es-summ alladheena fatahta lahum adhanahum. Marahimuka ya ilahi ta'ti 'alayna mithl el-mukhalla'een alladheena anhadtahum.\n\nMarahimuka ya ilahi ta'ti 'alayna mithl el-amwat alladheena aqamtahum. Marahimuka ya ilahi ta'ti 'alayna nahnu sha'buka es-sarikheen ilayk. Marahimuka ya ilahi ta'ti wa tahillu 'ala ru'ous el-aba' el-kahana el-at-har. Marahimuka ya ilahi ta'ti wa tahillu 'ala ru'ous er-ruhban wal-'almaniyyeen. Marahimuka ya ilahi ta'ti wa tahillu 'ala ru'ous el-ikhwa alladheena ta'ibou ma'ana fi hadhihi el-absalmodiyya.\n\nMarahimuka ya ilahi ta'ti wa tahillu 'ala ru'ous el-maseehiyyeen el-orthodoksiyyeen min mashariq esh-shams ila magharibiha, wa min esh-shamal ila el-ganoub. Marahimuka ya ilahi ta'ti wa tahillu 'ala ru'ous kull el-mugtami'een fi hadhihi el-bee'a el-muqaddasa, min el-kibar wa es-sighar, er-rigal wan-nisa', esh-shuyoukh wash-shubban, er-ruhban wal-'almaniyyeen, el-ghuraba' wa ahl el-makan. Utruk waghfir lana khatayana allati sana'naha bi-ma'rifa wa bi-ghayr ma'rifa, wa allati sana'naha bi-iradatina wa bi-ghayr iradatina.\n\nAllahumma ighfir lana athamana ez-zahira wal-khafiyya, waghsil adnasana wa tahhirna min kull ghish wa min kull mura'ah wa min kull sharr, wa kull hasad wa tagriba. Hull 'anna kull wathaqat el-khatiyya, wa kull esh-shukouk wal-kibriya', watrud 'anna kull fi'l khabeeth wa kull nameema. Wa ab'id 'anna kull el-aqsam el-hanitha, wa kull la'na wa kull el-quwwat er-radiyya, min agl ismika el-quddous alladhi du'eena bih.\n\nAllahumma arsil 'alayna ni'mat rouhika el-quddous, wa tahannan 'alayna warhamna ka-'azeem rahmatik. Samihna bi-hafawatina. Nayyih nufous aslafina. Washfi amradana. Wa rudd ghurbat musafireena.\n\nWahfaz lana hayat es-sayyid el-batriyark Anba (___), wa kadhalika shuraka'ihi fil-khidma er-rasouliyya el-aba' el-matarina wal-asaqifa bi-kull makan. Wahfaz hayat el-aba' el-kahana wal-ikhwa esh-shamamisa wa sa'ir esh-sha'b el-maseehi min mashariq esh-shams ila magharibiha, wa min esh-shamal ila el-ganoub. Wa thabbitna nahnu wa iyyahum fil-bee'a el-muqaddasa el-gami'a er-rasouliyya.\n\nBi-shafa'at es-sayyida el-'Adhra' Maryam el-batoul et-tahira ez-zakiyya, wa Mar Marqus el-Ingeeli er-Rasoul karouz ed-diyar el-Masriyya, wal-mala'ika wa ru'asa' el-mala'ika, wal-aba' wal-anbiya' war-rusul wash-shuhada' wal-qiddiseen, wa kull alladheena ardou er-Rabb bi-a'malihim es-saliha, wa yurdounahu ila akhir ed-duhour, min dhurriyyat abeena Adam ila el-an wa kull awan wa ila dahr ed-duhour. Ameen."],
  [["kiahk-midnight-hymn-79"], "Ameen.\n\nYa Rabbu irham (3)\nYa Allah irhamna.\n\nYa Rabbu irham (3)\nYa Allah isma'na.\n\nYa Rabbu irham (3)\nYa Allah unzur ilayna.\n\nYa Rabbu irham (3)\nYa Allah ittali' 'alayna.\n\nYa Rabbu irham (3)\nYa Allah tara'af 'alayna.\n\nYa Rabbu irham (3)\nNahnu sha'buk.\n\nYa Rabbu irham (3)\nNahnu gibillatuk.\n\nYa Rabbu irham (3)\nNaggina min a'da'ina.\n\nYa Rabbu irham (3)\nNaggina min el-ghala'.\n\nYa Rabbu irham (3)\nNahnu 'abeeduk.\n\nYa Rabbu irham (3)\nAnta Ibn Allah.\n\nYa Rabbu irham (3)\nAmanna bik.\n\nYa Rabbu irham (3)\nLi-annaka ateet wa khallastana.\n\nYa Rabbu irham (3)\nTa'ahhadna bi-khalasik.\n\nYa Rabbu irham (3)\nWaghfir lana khatayana.\n\nYa Rabbu irham."],
  [["lent-weekday-gospel-response"], "Esh-sha'b:\n\nSalam Allah alladhi, yafouq kull 'aql, yahillu fi qouloubikum, bil-Maseeh Yasou' rabbina.\n\nAkhta'tu akhta'tu, ya rabbi Yasou' ighfir li, li-annahu laysa 'abdun bila khatiyya, wala sayyidun bila ghufran.\n\nAbana alladhi fis-samawat, li-yataqaddas ismuk, li-ya'ti malakoutuk, li-anna laka el-magd ila el-abad.\n\nLi-annahu mubarakun el-Ab wal-Ibn war-Rouh el-Qudus, eth-thalouth el-kamil, nasgud lahu wa numaggiduh."],
  [["lent-weekday-the-great-high-priest"], "Ra'ees el-kahana el-a'zam ila el-abad, et-tahir, quddous Allah.\n\n'Ala taqs Malki-Sadaq el-kamil, quddous el-qawi.\n\nEl-mutagassid min er-Rouh el-Qudus wa min el-qiddeesa Maryam el-batoul bi-sirrin 'azeem, quddous alladhi la yamout, irhamna."],
  [["lent-weekday-a-great-mystery"], "(16/1) Sirrun 'azeem, yafouq 'uqoul el-bashar, huwa sa'y mukhallisina, alladhi ata wa sar ibn bashar\n\n(16/2) Muhibb el-bashar es-salih, alladhi 'al Isra'eel, arba'een sana fil-barriyya, ata wa sar ibn bashar\n\n(16/3) Wa lamma akmal et-tawadu', ba'd thalatheen sana min ez-zaman, i'tamad wa sam, arba'een yawman wa arba'een layla\n\n(16/4) Wa kan ma'a el-wuhoush, lamma sam fil-barriyya, li-kay nasna' mithlah, fi zaman wahdatina\n\n(16/5) Ta'alou nasrukh nahwah, wa nabki amamah, sarikheen qa'ileen, kama 'allamana\n\n(16/6) \"Abana alladhi fis-samawat, li-yataqaddas ismuk,\" fi kull geel wa geel, wa ila abad el-abad\n\n(16/7) El-gasad wad-dam alladhan lak, huma li-maghfirat khatayana, ma'a el-'ahd el-gadeed, alladhi a'taytahu li-talameedhik\n\n(16/8) Fa-nahnu akhadhna minhum, hadha el-mithal alladhi a'taytahu lahum, li-kay nasna'ahu fi kull heen, ila magee'ika eth-thani\n\n(16/9) El-an tunawilna min gasadik, wa damika el-haqeeqiyyayn, tagdeedan li-qouloubina, wa ghufranan li-khatayana\n\n(16/10) Utrud esh-shayateen 'anna, li-nukmil bi-salam, li-annahu laysa lana siwak, fi diqatina wa shada'idina\n\n(16/11) Li-annana nahnu sha'buk, wa khiraf qatee'ik, tagawaz 'an athamina, ka-salih wa muhibb el-bashar\n\n(16/12) Wag'alna mustahiqqeen, ni'mataka ayyuha el-mukhallis, fi hadhihi el-ayyam wa nahnu bila khatiyya, ma'a sawm naqiyy\n\n(16/13) Wal-nuhibb ba'duna ba'dan, wa nasna' et-tawadu', li-annana bil-mahabba, nukmil el-wasaya\n\n(16/14) En-namous wal-anbiya', huma el-mahabba allati bi-ghayr riya', li-annana min qibal el-mahabba, nanal el-maghfira\n\n(16/15) Ig'al abwab el-kana'is maftouha lana, wa kammilna fil-iman el-mustaqeem, li-kay nanal el-wa'd es-sadiq, min famika el-qa'il\n\n(16/16) \"Ta'alou ilayya, ya mubaraki abi, rithou el-hayah, ed-da'ima ila el-abad.\"\n\nEsh-sha'b:\n\nMubarakun el-Ab wal-Ibn war-Rouh el-Qudus, eth-thalouth el-kamil, nasgud lahu wa numaggiduh."],
  [["lent-weekend-psalm-150"], "Yasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nHallelouia. Sabbihou Allah fi gamee' qiddiseeh. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu fi galad quwwatih. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu 'ala maqdiratih. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu ka-kathrat 'azamatih. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu bi-sawt el-bouq. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu bi-mizmar wa qeethar. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu bi-dufouf wa sufouf. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu bi-awtar wa arghan. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu bi-sunoug hasanat es-sawt. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nSabbihouhu bi-sunoug et-tahleel. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nKull nasama fal-tusabbih ism er-Rabb ilahina. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nEl-magd lil-Ab wal-Ibn war-Rouh el-Qudus. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nEl-ana wa kull awan wa ila dahr ed-duhour. Ameen. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nHallelouia. Hallelouia. El-magd huwa li-ilahina. Hallelouia.\n\nYasou' el-Maseeh sam 'anna, arba'een yawman wa arba'een layla.\n\nHallelouia. Hallelouia. El-magd huwa li-ilahina. Hallelouia.\n\nYa Yasou' el-Maseeh Ibn Allah, isma'na warhamna.\n\nEsh-sha'b:\n\nMubarakun el-Ab wal-Ibn war-Rouh el-Qudus, eth-thalouth el-kamil, nasgud lahu wa numaggiduh."],
  [["lent-midnight-psali-adam-on-first-canticle"], "Esh-sha'b:\n\nIhfazni ya ilahi, bi-ma'ounatik, wa a'tini khalasan, bis-salah was-sawm.\n\nKarma haqeeqiyya, ghayr shirreera, ighris feena, bis-salah was-sawm.\n\nLi-annaka anta ya Rabb, tu'teeni tawba, wa ghufranan, bis-salah was-sawm.\n\nA'tini ayyuha es-Sayyid, faman wa hikma, li-atadarra' ilayk, bis-salah was-sawm.\n\nIrhamna, ka-mithl rahmatik, min qibal salahik, bis-salah was-sawm.\n\nTusabbih kull el-khaleeqa, li-sultanik, wa rububiyyatik, bis-salah was-sawm.\n\nSalama wa mahabba, wa nuskan, fal-nastayqiz, bis-salah was-sawm.\n\nAyyuha el-Ilah er-rahoum, a'tini dalla, li-agid rahma, bis-salah was-sawm.\n\nYa Yasou' Ibn Allah, ig'al abwab el-kaneesa, maftouha lana bil-iman, bis-salah was-sawm.\n\nKa-'azamatik, rudd el-masbiyyeen, li-nudawim, bis-salah was-sawm.\n\nTusabbih kull esh-shu'oub, li-sultanik, wa rububiyyatik, bis-salah was-sawm.\n\nFal-tukhallisna yaduk, min athamina, wa shada'idina, bis-salah was-sawm.\n\nEl-khataya allati sana'tuha, wa 'adatiha, fal-yanhallou, bis-salah was-sawm.\n\nIrtafa'at giddan, esh-sharika, allati lit-tahara, bis-salah was-sawm.\n\nMahabba 'azeema, rasouliyya, fal-takun lana, bis-salah was-sawm.\n\nYa malik es-salam, a'tina meerathan, fi malakoutik, bis-salah was-sawm.\n\nUhrusna wa naggina, min esh-shurour, wal-awga', bis-salah was-sawm.\n\nUbsut yameenak, wa naggina min el-fana', li-nanal el-khalas, bis-salah was-sawm.\n\nNusabbihuk, wa nubarikuka bi-tahleel, wa nakhdimuk, bis-salah was-sawm.\n\nHa aba'una el-qiddiseen, ahabbou el-batouliyya, wa sakanou el-barriyya, bis-salah was-sawm.\n\nLaka el-'izz, wat-tamgeed, qabl ed-duhour, bis-salah was-sawm.\n\nIghfir lana khatayana, wa athamana, min agl ismika el-quddous, bis-salah was-sawm.\n\nYa mukhallis el-'alam, imla'na min, mawhibatika es-sama'iyya, bis-salah was-sawm.\n\nIhsibna ma'a khirafik, el-maqboula ka-dhabeeha, li-numaggidak, qa'ileen \"Hallelouia.\"\n\nEl-kahin:\n\nAmeen, hallelouia. Ya Allah irhamna.\n\nEsh-sha'b:\n\nYa Allah irhamna (2)"],
  [["lent-midnight-psali-adam-on-second-hoos"], "An'im li ya Allah, li-kay asna' iradatak, wag'alni mustahiqqan kull heen, an akoun ma'ak.\n\nHull zallati, bi-rahmatik, wa tahhir nafsi, wa 'aqli wa gasadi.\n\nLi-anni tagasart, li-kay asna' a'malan, idha tadhakkartuha, akhza.\n\nHaqqan aghdabtu, salahak, min agl a'mali esh-shirreera, wa khatayaya er-radee'a.\n\nIla ayna adh-hab, ana ed-da'eef, fa-inna es-sama' wal-ard, ma'an fi yadayk.\n\nHaqqan bil-haqeeqa, laysa li malga', wala khalasan, illa bi-rahmatik.\n\nHa hou dha ana, altagi' ilayk, li-kay agid rahma, idha qabiltani ilayk.\n\nAllah er-raheem, khaliq kull shay', ihfaz 'abdak, min kull sharr.\n\nIrhamna ya Yasou' el-Maseeh, ka-salahik, la tatrukni 'ank, li-anni fil-alamat.\n\nIqla' min qalbi, asl el-khataya, wat-tagdeef, wal-istihza'.\n\nWa khallisni aydan, min kull 'amal shirreer, alladhi huwa fakhr el-'alam, wa magduhu el-farigh.\n\nLa ta'khudhni fi, muntasaf ayyami, wala tuhlikni, min agl shurouri.\n\nEl-baha'im allati la ma'rifa laha, lam yasna'ou 'amali, li-anni aghdabtuka, mirararan katheera.\n\nAnta ya Rabb, ta'rif athami, bal tab'uka, esh-shafaqa.\n\nWayl li ana, el-insan esh-shirreer, idha waqaftu, amam magdik.\n\nAfnaytu kull zamani, fil-kasal, a'tini tawba, wa 'aqlan mustayqizan.\n\nAmil sam'aka ya Rabb, wasma'ni warhamni, iqlib huzni, farahan li.\n\nNa'am haqqan akhta'tu, fis-sama' wa 'ala el-ard, wa lam akun mustahiqqan an uhsab, ma'a khiraf qatee'ik.\n\nNafsi muta'allima, fa-'azziha ya Rabb, li-annaha bidoun rahmatika ya Allah, laysa laha raga'.\n\nMin agl ismik, ya ilah khalasi, tara'af 'ala maskanati, li-agid rahma.\n\nYa Allah muhibb el-bashar, er-ra'ouf, la tatrahni fi, asafil el-gaheem.\n\nAsri' li-tukhallisani, ayyuha el-ka'in ila el-abad, min shiqwat, en-nar el-abadiyya.\n\nYa mukhallis el-'alam, khallisni bi-quwwatik, min mawdi', et-tanahhud wal-buka'.\n\nYa man ya'lam el-afkar, qabl an takoun, min agl ismika el-quddous, khallis nafsi.\n\nIqbalni ilayka ya ilahi, ka-'azeem rahmatik, qul li-nafsi, \"Inni ana huwa khalasuki.\"\n\nBa'eedun el-khalas, minni, idh lam tudrikni, bi-rahmatika el-'azeema.\n\nBi-rahmatika ya Allah, hull el-marbout, bi-gamee' el-khataya, fi kull zaman hayatih.\n\nYa tura madha yakoun, wa ma huwa mu'add li, fil-yawm el-akheer, alladhi li-hukmika el-'adil.\n\nLi-anni akmaltu el-khataya, bi-kull naw', wa laysa fil-bashar, man sana' mithli.\n\nAnsit ya Rabb li-kalimati, wafham surakhi, wa a'inni fi, dhalika el-yawm.\n\nAsgud lak, bi-i'tiraf, wa as'aluk, ya rabbi ighfir li.\n\nEl-kahin:\n\nAmeen, hallelouia. Ya Allah irhamna.\n\nEsh-sha'b:\n\nYa Allah irhamna (2)"],
  [["lent-midnight-psali-watos-on-eighth-part-of-sunday-theotokia"], "Ta'alou gamee'an li-nata'allam, hadhihi el-fada'il el-'azeema, el-la'iqa lit-tahara, bis-salah was-sawm.\n\nKull wahid min aba'ina el-mukhtareen, dhou el-fada'il en-naqiyya, lam yaqtarib ila Allah, illa bis-salah was-sawm.\n\nEth-thalathat fitya atfa'ou laheeb el-atoun, alladhi da'afahu el-malik, min agl taharatihim wa'tirafihim, bis-salah was-sawm.\n\nLi-anna Dawoud el-murattil, maha er-Rabb athamah, wa ga'alahu malikan wa nabiyyan, bis-salah was-sawm.\n\nDanyal el-labis el-Ilah, wagad khalasan, fi gubb el-usoud, bis-salah was-sawm.\n\nAdam wa Hawwa' ma'an, khallas er-Rabb sabyahum, wa raddahum ila rutbatihim dafa'tan ukhra, bis-salah was-sawm.\n\nEliya dha el-fahm er-rafee', rufi' ila es-sama' bi-dalla, 'ala markaba nariyya, bis-salah was-sawm.\n\nShaqq Mousa el-bahr nusfayn, bi-'asahu wastahaqq, an yatakallam ma'a Allah, bis-salah was-sawm.\n\nYounan fi batn el-hout, wagad khalasan, ba'd thalathat ayyam, bis-salah was-sawm.\n\nRabb el-arbab, Yasou' dhou es-sulta el-'uzma, sam li-kay yu'allimana, baha' es-sawm (bis-salah was-sawm).\n\nWa aydan fal-nasum, bi-mahabba wa nusk, li-kay na'bur es-su'oubat, bis-salah was-sawm.\n\nFal-nafham ya ahibba'i, anna ra's el-hikma, hiya makhafat Allah, bis-salah was-sawm.\n\nAhl Neenawa wa Lout el-barr, alladheena kanou fil-geel el-awwal, nalou kulluhum el-khalas, bis-salah was-sawm.\n\nWa baghtatan tanhall, el-quwwat el-'aqliyya, idha dawamna, bis-salah was-sawm.\n\nSabrun 'azeem yudrikuna, min qibal el-mahabba allati bila sharr, fal-natamassak nahnu, bis-salah was-sawm.\n\nKull gibillat Allah, min Adam ila el-inqida', lam yaqdirou an yanalou el-khalas, illa bis-salah was-sawm.\n\nIs-harou fit-talabat bila malal, wa ahibbou el-wahdaniyya waz-zuhd, li-nakoun mustayqizeen, bis-salah was-sawm.\n\nYanbaghi lana an narfud, hadha ez-zaman el-mamlou' sharran, li-nazdad fit-tahara, bis-salah was-sawm.\n\nLa'alla Allah yun'im lana, bi-ghufran khatayana, wa yatrud 'anna esh-shayateen, bis-salah was-sawm.\n\nHou dha aba'una en-nussak, mu'allimi el-kaneesa, kammalou gihadahum, bis-salah was-sawm.\n\nKull muhibbi el-Maseeh, fal-yatamassakou bil-'iffa, wa yutahhirou hawassahum, bis-salah was-sawm.\n\nIghfirou yughfar lakum, athamakum ya ikhwati, wa bil-mahabba ihtadou, bis-salah was-sawm.\n\nBaqiyyat hayatina fil-'alam, imnahna ma'ounataka ayyuha el-Maseeh, naggina min et-tagarib, bis-salah was-sawm.\n\nToubahum alladheena samou, wa mana'ou shahawatihim, wastamarrou bila malal, bis-salah was-sawm."],
  [["lent-midnight-psali-adam-on-third-hoos"], "Tadhakkartu, khataya gahli, fa-ahmaltu dumou'i, wa galastu abki.\n\nKull et-tanahhudat, allati fi sadri, tash'il kan-nar, fi qalbi.\n\nMashourat 'aqli, tabi'tuha, wa awamir Yasou', lam ahfazha.\n\nKull mithalat esh-sharr, allati li-tabee'ati, tabi'tuha, bidoun raga'i.\n\nLi-dhalika saqattu, ila asfal, mithl el-bayt el-mabni, 'ala er-raml.\n\nHayat es-sama'iyyeen, bal wal-ardiyyeen, harat li-agl khatiyyati, idh sirtu teenan.\n\nHou dha ana anzur, nafsi ma'ita, mawdou'a fi qabr, mithl mayyit.\n\nIgtami'ou ya ikhwati, wabkou ma'i, ila akhir ez-zaman, li-anni saqattu.\n\nIghsil girahati, bi-dumou' et-tawba, wat-tawassul bil-buka', fil-layl.\n\nLi-annaka nashaltani, li-alla uhtaqar, ana alladhi saqat, bayn el-lusous.\n\nHassat el-khatiyya, iqla'ha ya ilahi, min qalbi ma'a, afkar gahli.\n\nA'tini hikma, rouhiyya, wa khisban, fi salati.\n\nLi-ata'ammaq fi, hikmat el-kalam, wa aseer fi widd, ba'd el-'adawa.\n\nAnta ta'rif ya sayyidi, anna hawassi, tameel ila gahalat, hadha el-'alam.\n\nWayl li, idha hasabta zallati, fa-khizyun 'azeemun ka'in, fi rouhi el-miskeena.\n\nYa Rabb isfah, 'an zallat, tabee'ati, wa du'f gasadi.\n\nAmil bi-sam'ik, li-du'fi 'agilan, kama sami'ta, talabat el-'ashshar.\n\nKhallisni ya muhibb el-bashar, li-anna hawassi, qad ghariqat fi, ahwal hadha el-'alam.\n\nNas'aluka ayyuha, el-malik el-'azeem, udhkur 'abdak, fi malakoutik.\n\nHou dha lissun, qal hakadha, fa-iftaqadtahu ya Rabb, bi-rahma wa khalas.\n\nLaka el-karama, wa laka el-'izza, ya khaliq, es-sama' wal-ard.\n\nIghfir li qaleelan, li-kay astareeh, li-anna ghalati wa zulmi, thaqula 'alayya.\n\nGasad ibnik, ig'alni mustahiqqan lah, li-yusayyirani gadeedan, feema yurdeeh.\n\nAyyuha er-ra'i, wal-mukhallis, utlub kharoufak, ana ed-dall.\n\nEl-kahin:\n\nAmeen, hallelouia. Ya Allah irhamna.\n\nEsh-sha'b:\n\nYa Allah irhamna (2)"],
  [["lent-midnight-psali-watos-on-the-commemoration"], "Talabtu ilayka ya sayyidana el-Maseeh, ighfir li ya malik el-magd, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nIftah a'yun 'aqli, li-kay a'rif magdak, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nLi-annaka anta huwa Ibn Allah, malga'i min geel ila geel, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nHaqqan ateet ila el-'alam, wa khallastana min esh-shirreer, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nIrhamna ya Allah, nas'aluka ya malikana, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nSab' tughmat el-mala'ika, yusabbihounaka ma'a gamee' et-tughmat, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nHa nahnu nurattil lak, ma'a kull el-karasi, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nLaka el-quwwa was-salah, wal-magd wal-karama, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nYasou' el-Maseeh huwa mu'eenuna, Yasou' el-Maseeh huwa thabatuna, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nYa rabbi Yasou' el-Maseeh, ihfaz sha'bak, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nKull esh-shu'oub yusabbihounak, li-annaka anta khalaqtahum, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nFal-nusabbihaka ma'a gamee' et-tughmat, thalath marrat qa'ileen \"quddous,\" udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nEsh-Sharoubeem yusabbihounahu, wa es-Sarafeem yumaggidounah, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nWa baghtatan mukhallisuna, kan ma'a er-rusul, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nEl-magd laka ma'a abeeka es-salih, war-Rouh el-Qudus, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nKhallisna ya sayyidana min et-tagarib, wa min kull ed-diqat, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nAmil sam'aka ilayya ayyuha el-Maseeh, wa a'tini raha ma'a gamee' el-qiddiseen, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nBarik el-miyah wath-thimar, waz-zar' wal-amtar, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nNatlub min agl kahanat er-Rabb, wash-shamamisa khallishum ayyuha el-Maseeh, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nWa aydan el-maseehiyyeen, ighfir lahum ya malikana, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nAyyuha es-Sayyid el-Ilah mu'eenuna, ihfaz gamee' sha'bak, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nQuddous ayyuha eth-thalouth el-aqdas, ihsibna ma'a kull mu'mineek, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nKull nafs orthodoksiyya, nayyihha ya muhibb el-bashar, udhkurni ya rabbi, mata ge'ta fi malakoutik.\n\nYa mukhallisana es-salih, irham 'abdaka wa aba'ah, udhkurni ya rabbi, mata ge'ta fi malakoutik."],
  [["lent-midnight-watos-psali-on-great-lent-doxology"], "Sa-abtadi' bishtiyaq, wa usabbih Allah el-abadi, \"usabbih marahimaka ya rabbi, ila abad el-abad.\"\n\nHullani min shurouri, wa bi-quwwatika ihfazni, min geel ila geel, bi-fami ukhbir bi-haqqik.\n\nYa gins el-bashar wa es-sama'iyyeen, utlubou wabkou 'alayya, athami 'alat 'ala ra'si, wa thaqulat 'alayya.\n\nAyyuha es-Sayyid Rabb el-quwwat, atlub ilayka an tastageeb li, ya Allah isma' tanahhudi, watrahha 'anni.\n\nAs'al min rububiyyatik, ana el-miskeen iqbalni ilayk, ig'alni mithl el-'ashshar, alladhi akhta' ilayk.\n\nWa haqqan takallamta ma'ah, wa ghafarta lahu wa hallaltah, wa tara'afta 'alayh, wa ghafarta lahu khatayah.\n\nTusabbihuhu el-buhayrat, qa'ila \"ighfir li khatayaya, ig'alni mithl ez-zaniya, allati khallastaha.\"\n\nKa-mithalat esh-shaytan, saqatat wanhallat, wa anqadhtaha wa naggaytaha, li-annaha ardatka amamak.\n\nYa Yasou' el-Maseeh ed-dabit, alladhi waladat-hu Maryam, ig'alni mithl el-liss, alladhi sulib 'an yameenak.\n\nWa mithlahu atlub ilayk, ayyuha er-Rabb el-'ageeb, li-annahu i'taraf bik, hakadha qa'ilan.\n\nWa aydan takallam bi-sur'a, qubalat ilah el-aliha, udhkurni ya rabbi, udhkurni ya ilahi.\n\nA'tini rahma ya malikana, wa hikma wa ghalaba, udhkurni ya maliki, mata ge'ta fi malakoutik.\n\nWa ha'ula' alladheena i'taraf, bihim bi-tafseer, wa anta ya mukhallisi, qabilta ilayka i'tirafah.\n\nTabarakta ayyuha er-Rabb wa an'amta lah, ya Yasou' el-Maseeh Ibn Allah, wa tara'afta 'alayh, wa arsaltahu ila el-firdaws.\n\nEl-wayl li li-agl khatayaya, li-anna el-khalas kharig 'anni, ana aydan el-khati' ya Yasou', ilahi wa maliki el-haqeeqi.\n\nTa'ammal ilayya ya ilahi, ya ilahi istagib li, wa tahannan 'alayya, wag'alni ka-ahad ha'ula'.\n\nAmil qalbi ila namousak, warham gahalati, li-anni a'rif annaka salih, wa ra'ouf wa raheem.\n\nUnzur wasma' warhamni, ayyuha el-ka'in ila el-abad, udhkurni bi-rahmatik, ila abad el-abad.\n\nIqta' min 'aqli, el-khataya wal-ghalat, atlub ilayka ya rabbi Yasou', la tubakkitni bi-ghadabik.\n\nYa Ibn Allah tara'af 'alayna, ayyuha el-khaliq el-mudabbir, wala bi-rigzik, tu'addib gahalati.\n\nYa Allah el-'azeem el-ghayr el-khati', esh-shagara el-mu'tiya el-hayah, li-annaka la tasha' mawt el-khati', mithl an yarga' wa yahya.\n\nIghfir li ana ed-da'eef, ayyuha er-Rabb ilah ed-duhour, tahannan 'ala du'fi, wala tanzur ilayya bi-ghadab.\n\nWa gamee' khatayaya alqaytuha saree'an, ayyuha er-Rabb ilahi, akhta'tu ya Yasou' rabbi, akhta'tu ya Yasou' ilahi.\n\nTa'anna 'alayya, wamhu kull athami, ya maliki la tahsib 'alayya, el-khataya allati sana'tuha.\n\nIqbalna ilayka ya Ibn el-Ab, ayyuha el-Mu'azzi isma'ni, as'aluka ya mukhallisi, fal-tudrikni marahimuk.\n\nImhu khatayaya ayyuha er-Rabb, el-ka'in mundhu el-bad', wa khallisni min esh-shada'id, el-mudadda li-nafsi.\n\nWaksir el-qa'imeen, nahwa nafsi wa rouhi, wala tahriq 'adam ma'rifati, mithl Sadoum.\n\nLi-anna khatayaya thaqeela 'alayya, isfah 'an zallati, wala tuhlikni aydan, mithl 'Amoura.\n\nLi-anni akhta'tu ya Rabb irhamni, akhta'tu ila el-ghaya, lakin ya Rabb isna' ma'i, mithl ahl Neenawa.\n\nFa-awqadou surugahum wastayqazou, wa talabou el-maghfira, ha'ula' alladheena tabou, wa ghafarta lahum khatayahum.\n\nAtlub min ra'fatik, ana el-'abd ed-da'eef, lakin fal-tudrikni marahimuk, ya rabbi saree'an.\n\nAtawassal ilayka qa'ilan, bi-lisani murattilan, sarikhan ma'a hadha esh-sha'b, bi-sawt la yaskut."],
  [["lent-midnight-psali-adam-on-fourth-hoos"], "Tawakkaltu 'alayk, ya malik ed-duhour, wa tadarra'tu ilayk, qa'ilan \"Ya Rabb irham.\"\n\nA'in du'fi, ila akhir ed-duhour, wa a'tini raha, \"Ya Rabb irham.\"\n\nLi-annaka anta huwa ilahuna, ateet li-tukhallisana, wa a'tina khalasan, \"Ya Rabb irham.\"\n\nKhallisna ayyuha es-Sayyid, min esh-shayateen, wa thabbitna fi ismik, \"Ya Rabb irham.\"\n\nIrhamna, ya mukhallisana, wa sayyidana Masiya, \"Ya Rabb irham.\"\n\nSittat ayyam ta'allamta, feeha 'anna, min agl kull el-khaleeqa, \"Ya Rabb irham.\"\n\nGamee' et-tughmat, es-sab' es-sama'iyya, yusabbihounaka kull heen, qa'ileen \"Ya Rabb irham.\"\n\nHaqqan et-taba'i', el-'ulwiyya el-'aqliyya, yumaggidouna eth-thalouth, qa'ileen \"Ya Rabb irham.\"\n\nLaka el-quwwa wal-magd, ayyuha edh-dhati, li-annaka anta huwa el-khaliq, \"Ya Rabb irham.\"\n\nYasou' huwa raga'una, Yasou' huwa thabatuna, fi shada'idina, \"Ya Rabb irham.\"\n\nKa-sultanik, sayyartana nahnu, fil-hurriyya, \"Ya Rabb irham.\"\n\nKull esh-shu'oub tusabbih, el-Maseeh er-Rabb, el-ghayr el-mahwi, qa'ileen \"Ya Rabb irham.\"\n\nA'tina salamak, ya ilahana, was-sabr, \"Ya Rabb irham.\"\n\nIrhamna warfa', ghadabaka 'anna, washfi amradana, \"Ya Rabb irham.\"\n\nTabarakta bil-haqeeqa, nas'aluka khallisna, min et-tagarib, \"Ya Rabb irham.\"\n\nEl-magd laka ma'a abeek, war-Rouh el-Qudus, anta quddousun wa mubarak, \"Ya Rabb irham.\"\n\nBaddid ya sayyidana el-a'da', wa mashouratahum abtilha aydan, ya muhibb el-bashar, \"Ya Rabb irham.\"\n\nNahnu nusabbihuka gahran, ma'a esh-Sharoubeem, wal-quwwat wal-karasi, \"Ya Rabb irham.\"\n\nBarik el-anhar, waz-zurou' wath-thimar, wal-amtar, \"Ya Rabb irham.\"\n\nNatlub min agl el-kahana, wash-shamamisa, khallishum ya sayyidana, \"Ya Rabb irham.\"\n\nYa Ibn Allah ilahuna, ihfazna nahnu, min el-khawf, \"Ya Rabb irham.\"\n\nYa Allah irhamna, li-nanal min asrarik, lil-maghfira, \"Ya Rabb irham.\"\n\nQuddous nasgud lak, ya Ibn el-Ab, wa Kalimat el-Ab, \"Ya Rabb irham.\"\n\nEl-anfus nayyihhum, ma'a es-siddeeqeen, fi malakoutik, \"Ya Rabb irham.\"\n\nTa'anna ya muhibb el-bashar, el-haqeeqi, 'ala 'abdika el-miskeen, \"Ya Rabb irham.\"\n\nKun ma'ahu wa khallishu, min esh-shayateen, wa min el-hasad wal-ghish, \"Ya Rabb irham.\"\n\nImhu 'anna, kull nagasa, wasma'na 'agilan, \"Ya Rabb irham.\"\n\nIqtarib min shada'idina, ayyuha el-Maseeh er-Rabb, Yasou' el-Ibn el-waheed, \"Ya Rabb irham.\"\n\nLi-kay tuthabbitna, fil-iman el-mustaqeem, li-annaka khallastana, \"Ya Rabb irham.\"\n\nIttali' 'alayna, wa khallisna, min esh-shayateen, \"Ya Rabb irham.\"\n\nUtrud el-afkar, esh-shirreera 'anna, wadhkur 'abdak, \"Ya Rabb irham.\"\n\nAs'aluka ya rabbi, khallisni min esh-shayateen, wa khallis sha'bak, \"Ya Rabb irham.\"\n\nEl-kahin:\n\nAmeen, hallelouia. Ya Allah irhamna.\n\nEsh-sha'b:\n\nYa Allah irhamna (2)"],
  [["lent-midnight-psali-adam-on-sunday-theotokia"], "Ta'alou fal-nusabbih, ma'a el-mala'ika, wa numaggid rabbana, Yasou' el-Maseeh.\n\nFal-nasum, sawman naqiyyan, wa nusalli, bi-qalbin munsahiq.\n\nWa aydan ta'arrou, min el-insan el-'ateeq, wa taqsihi esh-shirreer, wa a'malihi er-radee'a.\n\nWalbasou, el-insan el-gadeed, wa sallou el-an, bi-'izam quwwa.\n\nLi-anna ahl Neenawa, lamma akmalou, es-sawm, ghafar er-Rabb lahum.\n\nSamou, thalathat ayyam, wa sallou, bi-hutaf.\n\nDawoud en-nabi, wal-murattil, takallam fi, kitab el-mazameer.\n\nQa'ilan \"adhlaltu, nafsi bis-sawm, was-salah,\" lil-Maseeh edh-dhati.\n\nTamassakou bis-sawm, was-salah ma'an, wa qawwimouhuma bit-tahara, allati lil-qiddiseen.\n\nMuhibbeen 'amalahu, wa ta'affufah, li-tastahiqqou ed-dahr el-ati, bi-karamat 'azeema.\n\nKatheera giddan, el-fada'il allati, raddaha Allah lahum, min agl es-sawm.\n\nEl-anbiya', yuhibbouna es-salah, bi-wuqoufihim amam, 'Immanu'eel.\n\nEliya sa'id, ila es-sama', bi-dalla min qibal, es-salah was-sawm.\n\nEliya sarakh, mu'alliman esh-sha'b, qa'ilan \"ilbasou mus-han, wa sallou gayyidan.\"\n\nMalakout es-samawat, la takoun qareeba minna, illa bis-sawm, wal-ghufran wan-namous.\n\nAydan el-anbiya', bis-salah was-sawm, war-rahma, wat-tawba.\n\nYasou' el-Maseeh rabbuna, sam 'anna, wa 'allamana, an natoub.\n\nArba'een yawman, wa arba'een layla, fil-barriyya, bi-sirrin 'azeem.\n\nIfhamou dhalika el-yawm, wa tilka es-sa'a, allati li-magee'ikum, ila zulmat el-qabr.\n\nUdhkurou ed-daynouna, amam el-qadi, warfa'ou a'yunakum, ila es-Sayyid.\n\nFal-tantiq qouloubukum, bit-tamageed, wat-tahara, min qibal es-sawm.\n\nEs-salah was-sawm, yutahhiran nufousana, bil-wuqouf, fis-salah.\n\nFal-nashkur, rabbana Yasou', li-kay yanqul qouloubana, ila es-sama'.\n\nNursil laka et-tasbeeh, er-rouhi, wa nas'aluka bi-qalbin, mustaqeem.\n\nGamee' el-qiddiseen, samou, bidoun malal, el-arba'een yawman.\n\nMin agl a'malihim, wa batouliyyatihim, istahaqqou el-hayah, bis-sawm.\n\nKull shagara, thabita fil-firdaws, la tastatee', lin-nas idrakuha.\n\n'Azeema hiya el-karama, allati istahaqqaha Nouh, wa bis-sawm, sana' el-fulk.\n\nWarithou, el-hayah ed-da'ima, wa farihou ma'a el-Maseeh, el-ghafour.\n\nQalbi wa rouhi, tahhirhuma, dakhilan wa kharigan, min el-afkar esh-shirreera.\n\nUtlubou es-salam, wa giddou fi atharih, li-anna a'yun er-Rabb, tahrusuna.\n\nAmeelou sama'akum, wasma'ou wasaya er-Rabb, wasna'ou es-salam, ba'dukum li-ba'd.\n\nIhrisou 'ala es-sawm, bi-hirsin 'azeem, li-anna es-salawat bil-layl, tuneer el-'uqoul.\n\nIsma'ou mukhallisana, fil-Ingeel yaqoul, annahu bis-salah was-sawm, yakhrug esh-shayateen.\n\nIdha sumta, idhin ra'sak, waghsil waghak, warfa' 'aynayka ila es-sama'.\n\nQoumou sabbihou, Allah el-khaliq, li-nastahiqq nahnu, karamat 'azeema.\n\nWa nasrukh bi-sawt, wahid qa'ileen, \"Irhamna ya Allah, wa a'tina ni'ma.\"\n\nMin agl ismik, ayyuha el-Maseeh malikuna, isna' rahma, fi malakoutik.\n\nLi-anni akhta'tu ilayk, bi-kull naw', wa nas'aluka khallisna, min el-gaheem.\n\nYa ilah aba'ina, malik ed-duhour, khubzana alladhi lil-ghad, a'tina el-yawm.\n\nWala tudkhilna, fi tagriba, ya Rabb lakin naggina, min esh-shaytan.\n\nQuddous quddous, ayyuha el-waheed el-gins, es-sama' wal-ard, mamlou'a min magdik.\n\nIghfir lana ya ilahana, zallatina, wa tahhir nufousana, wa qouloubana wa agsadana.\n\nBaqiyyat ayyamina, namdah, es-sawm en-naqiyy, was-salah bila malal.\n\nLi-kay nahfaz, wasayak, waqbalna ilayk, fi diyarik.\n\nIrfa' 'anna, el-alamat esh-shirreera, ihsibna ma'a, qatee'ika wa khirafik.\n\nA'tina naseeban, ma'a qiddiseek, wag'alna mustahiqqeen, li-kay nasna' mashee'atak.\n\nAba'una wa ikhwatuna, ya Rabb nayyihhum, fil-firdaws, ila el-inqida'.\n\nYa Allah thabbitna, fil-iman el-orthodoksi, bi-shafa'at, walidatika Maryam.\n\nAyyuha el-Maseeh mukhallisuna, irham sha'bak, wa an'im lana kulluna, ka-'azeem rahmatik."],
  [["lent-midnight-watos-psali-for-great-lent"], "Ta'alou li-nasum, aswaman kamila, li-annahu bis-salah was-sawm, yaghfir lana er-Rabb.\n\nDanas qouloubina, fal-nutahhirhu bil-mahabba, bi-wasitat es-salah was-sawm, wal-a'mal el-la'iqa.\n\nFa-inna er-Rabb 'allamana, fi Ingeelih, annahu bis-salah was-sawm, natrud esh-shayateen.\n\nMadah es-Sayyid, alladheena samou lah, bis-salah was-sawm, bi-fikr ghayr nagis.\n\nTab aba'una, bi-birr wa tahara, wa bis-salah was-sawm, istahaqqou el-malakout.\n\nHawwa' wa abouna Adam, bakaya li-agl el-firdaws, wa bis-salah was-sawm, raddahuma muhibb el-bashar.\n\nEliya aghlaq es-sama', thalath sineen wa sittat ash-hur, bis-salah was-sawm, fa-lam tumtir es-suhub.\n\nDhabeehat abeena Ibraheem, qabilaha Allah es-Sayyid, bis-salah was-sawm, wa ga'alahu ra'ees aba'.\n\nIshaq rabatahu abouh, li-kay yuqaddimahu dhabeeha maqboula, wa bis-salah was-sawm, 'ouwwid bil-kabsh.\n\nWa aydan Ya'qoub Isra'eel, min agl nawayahu es-sadiqa (el-baree'a), bis-salah was-sawm, nal baraka min abeeh.\n\nLout el-barr istahaqq, an ya'ti ilayhi el-malakan, wa bis-salah was-sawm, khalas min esh-shidda.\n\nMousa akhadh el-lawhayn, wa wada'ahuma fil-qubba, wa bis-salah was-sawm, darab el-bahr fa-sar shatrayn.\n\nNouh el-barr ashar, ilayhi Allah bil-fulk, wa bis-salah was-sawm, khalas min et-toufan.\n\nRadd Allah ghadabahu baghtatan, 'an ahl Neenawa, bis-salah was-sawm, tarak lahum a'malahum esh-shirreera.\n\nHaqqan Younan kan, fi batn el-hout thalathat ayyam, wa bis-salah was-sawm, qadhafahu ila el-yabisa.\n\nEth-thalathat fitya el-qiddisoun, rafadou kalam el-malik, wa bis-salah was-sawm, atfa'ou laheeb el-atoun.\n\nAfwah el-usoud fil-gubb, lahasat qadamay Danyal, wa bis-salah was-sawm, sar 'azeeman fi Isra'eel.\n\nSamou'eel masih el-moulouk, qaddamahu abawahu ila bayt er-Rabb, wa bis-salah was-sawm, du'iya el-masih.\n\nHaqqan Yousef el-'afeef, khalas min ez-zaniya, wa bis-salah was-sawm, gu'ila ra'eesan 'ala Masr.\n\nHa el-ithna 'ashar rasoulan, karazou bil-ism el-mubarak, wa bis-salah was-sawm, aqamou el-amwat.\n\nDawoud dhou el-qeethar, u'teeyat lahu en-nubouwa, wa bis-salah was-sawm, sarat lahu el-mamlaka.\n\nKull en-ni'am el-'aliya, adrakat en-nussak, bis-salah was-sawm, wat-taqwa.\n\nKull en-nufous allati ardat, er-Rabb el-Ilah bil-a'mal, bis-salah was-sawm, fazat bi-malakout es-samawat.\n\nLi-hadha fal-nusabbihahu, wa numaggiduh, bis-salah was-sawm, was-sugoud amamah."],
  [["palmsunday-liturgy-gospel-2-response"], "El-galis fawq esh-Sharoubeem\n\nEl-yawm zahar fi Urushaleem\n\nRakiban 'ala gahsh bi-magdin 'azeem\n\nWa hawlahu tuqous ni-aggelos"],
  [["palmsunday-liturgy-gospel-3-response"], "Fit-tareeq farashou el-qumsan\n\nWa min esh-shagar qata'ou aghsan\n\nWa hum yaseehouna bil-alhan\n\nŌsanna epshēri en-Daveed"],
  [["palmsunday-liturgy-gsopel-4-response"], "El-yawm tammat el-aqwal\n\nMin en-nubouwat wal-amthal\n\nKama tanabba' Zakariyya wa qal\n\nNubouwa 'an Iēsous Pi-ekhristos"],
  [["holyweek-apocalypse-revelation-hymn-of-st-john-the-beloved"], "Barakat el-lahouti el-Ingeeli Youhanna el-batoul ta'ti wa tahillu 'ala hadha esh-sha'b kullih, qoulou kullukum: ameen yakoun."],
  [["pentecost-liturgy-ya-kol-alsefoof"], "Ya kull es-sufouf es-sama'iyyeen, rattilou li-ilahina bi-naghamat et-tasbeeh, wabtahigou ma'ana el-yawm fariheen, bi-qiyamat es-Sayyid el-Maseeh.\n\nEl-yawm qad kamulat en-nubouwat, wa tammat aqwal el-aba' el-awwaleen, bi-qiyamat er-Rabb min bayn el-amwat, wa huwa bad' el-mudtagi'een.\n\nQad qam er-Rabb mithl en-na'im, wa kath-thamil min el-khamra, wa wahabana en-na'eem ed-da'im, wa 'ataqana min el-'ubudiyya el-murra.\n\nWa saba el-gaheem sabyan, wa hattam abwabahu en-nuhas, wa kasar matareesahu el-hadeed kasran, wa abdal lana el-'uqouba bil-khalas."],
];
